window.EVENTS_B=[{"id":"B-001","branch":"B","stage":1,"day":1,"shichen":"辰时","checkpoint":"及笄·001辰","scene":"教坊后阁，晨光透窗。鸨母亲自为你梳起发髻，一支素银簪插上——樊楼姑娘的及笄礼，没有高堂，只有一班姐妹和一架旧琵琶。","options":[{"text":"抱琵琶谢过众姐妹","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"礼成，你抱琴一拜。从今往后，立身之本在弦上，不在别人眼里。","source":"宋代教坊乐籍制度，见《宋史·乐志》及宋人笔记所载官伎及笄旧俗。"},{"text":"偷偷垂泪感慨身世","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"姐妹替你拭泪。伤感难免，但往后的路，眼泪换不来。","source":"宋代教坊乐籍制度，见《宋史·乐志》。"}],"difficulty":1,"npc":["鸨母"],"foreshadow":"及笄之日立心：以技立身"},{"id":"B-001-未","branch":"B","stage":1,"day":1,"shichen":"未时","checkpoint":"及笄·001未","scene":"午后，鸨母摊开一本账册，说起及笄后你的缠头分成要重新立规矩：樊楼抽几成、教坊月钱几何，条条款款都在纸上。","options":[{"text":"逐条问清再画押","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"账目问得明明白白，鸨母反高看你一眼。懂账的姑娘，没人敢糊弄。","source":"《东京梦华录》载汴京酒楼伎艺应酬之俗，乐人缠头分成见宋人笔记。"},{"text":"不看账目直接画押","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"笔一落下，分成便吃了暗亏。第一张纸就含糊，往后步步被动。","source":"宋人笔记所载乐户经纪旧例。"}],"difficulty":2,"npc":["鸨母"],"foreshadow":"账目意识为自赎埋线"},{"id":"B-001-戌","branch":"B","stage":1,"day":1,"shichen":"戌时","checkpoint":"及笄·001戌","flavor":true,"scene":"夜里，姐妹们凑了一桌果子替你贺笄。灯花跳着，有人起哄让你弹一支，弹什么都行。","options":[{"text":"弹一曲《婆罗门》助兴","correct":true,"tags":["才华"],"dims":{"才华":1,"名声":1},"feedback":"弦声一起，满座安静。这一夜，你是被真心贺着的。","source":"《碧鸡漫志》载唐宋大曲名目流变。"},{"text":"收起银簪细细擦拭","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"簪子擦得发亮。成人的第一件首饰，往后的路也要这样亮。","source":"宋人笔记所载及笄遗俗。"}],"difficulty":1,"npc":["鸨母","樊楼姐妹"],"foreshadow":"姐妹情分是后文助力"},{"id":"B-002","branch":"B","stage":1,"day":2,"shichen":"辰时","checkpoint":"苦练·002辰","scene":"天刚亮，教坊老乐工已在廊下调弦。他说你指力有了，欠的是一口气——大曲转调时手腕要松，心要稳。","options":[{"text":"依言苦练转调百遍","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"指尖磨出薄茧，转调处终于行云流水。老乐工点头：这才是吃这碗饭的手。","source":"唐宋琵琶指法见《乐府杂录》及宋人笔记所载教坊习乐之严。"},{"text":"嫌枯燥草草练了几遍","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"转调处还是发涩。老乐工摇头走了，你心里也清楚欠了功夫。","source":"同上。"}],"difficulty":2,"npc":["老乐工"],"foreshadow":"转调功夫日后救场"},{"id":"B-002-未","branch":"B","stage":1,"day":2,"shichen":"未时","checkpoint":"苦练·002未","scene":"午后排曲，掌班让你在一众新曲里挑登台的开场。一支是熟烂的旧调，一支是新排的慢词，唱好了惊艳，唱砸了难堪。","options":[{"text":"选新曲,赌一把真功夫","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"新曲磨到月上才合弦。难是难，可樊楼的台子不记旧功劳，只认新声。","source":"《东京梦华录》载京瓦伎艺竞新斗巧之风。"},{"text":"选熟旧调求稳","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"稳是稳了，掌班却淡淡一句：樊楼最不缺的就是稳。你品出了分量。","source":"同上。"}],"difficulty":2,"npc":["掌班"],"foreshadow":"新曲与后文填词呼应"},{"id":"B-002-戌","branch":"B","stage":1,"day":2,"shichen":"戌时","checkpoint":"苦练·002戌","flavor":true,"scene":"夜静，你独坐灯下拨弦，不成曲，只是一遍遍试那几个还生涩的音。窗外州桥方向的夜市声隐隐传来。","options":[{"text":"把生涩处写进小谱","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"谱上记下错处，明日少错一分。好乐工都有一本自己的谱。","source":"宋代乐谱传习见《碧鸡漫志》所记乐工口诀旧例。"},{"text":"听夜市人声出了会儿神","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"人间烟火隔着一条街。你想，总有一天要清清白白走进那片热闹里去。","source":"《东京梦华录》载州桥夜市盛况。"}],"difficulty":1,"npc":[],"foreshadow":"州桥夜市为相遇埋点"},{"id":"B-003","branch":"B","stage":1,"day":3,"shichen":"辰时","checkpoint":"点曲·003辰","scene":"晨起，樊楼采买归来说起城中时兴：如今客人听曲，爱新词胜过大曲，哪家楼里有新声，哪家的席面就俏。","options":[{"text":"留心记些流行词调","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"《鹧鸪天》《蝶恋花》的腔你都暗暗记下。耳音好的姑娘，走到哪都有饭吃。","source":"《东京梦华录》及《梦粱录》载汴京歌楼词曲时兴之俗。"},{"text":"不屑逐流只管大曲","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"大曲自有筋骨，可客人不买账，席面冷清下来，掌班脸色也不好看。","source":"同上。"}],"difficulty":2,"npc":["掌班"],"foreshadow":"时兴词调引来填词人"},{"id":"B-003-未","branch":"B","stage":1,"day":3,"shichen":"未时","checkpoint":"点曲·003未","scene":"午后，一位常客席间点曲，点的正是你还没练熟的慢词，还笑着说：听闻姑娘什么都弹得。一桌子人都看过来。","options":[{"text":"坦然换一支拿手的","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"你笑道：好曲子不欺客，容奴换一支不辱耳的。满座反而叫好。","source":"宋代歌筵应酬分寸见宋人笔记所载酒令监筵旧俗。"},{"text":"硬着头皮弹生曲","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"弹到一半走了音，客人笑着圆场，那笑比骂还难受。台上一分虚，台下十分真。","source":"同上。"}],"difficulty":3,"npc":["常客"],"foreshadow":"席面分寸后文再用"},{"id":"B-003-戌","branch":"B","stage":1,"day":3,"shichen":"戌时","checkpoint":"点曲·003戌","scene":"夜场将散，楼里最红的姐姐拉你到一边，递来一碟果子，慢悠悠说起樊楼规矩：客可酬，情不可滥，分寸二字值千金。","options":[{"text":"记下这份提点","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你把这话记进心里。樊楼的水深，有人肯递一句真话，是福气。","source":"宋代歌楼应酬规矩见《东京梦华录》及宋人笔记。"},{"text":"回赠她一支银钗","correct":true,"tags":["自主"],"dims":{"自主":1,"名声":1},"feedback":"姐姐笑着收下。楼里的情分要来往，孤身一人走不远。","source":"宋人笔记所载教坊同侪往来旧俗。"}],"difficulty":1,"npc":["头牌歌伎"],"foreshadow":"头牌姐姐日后关键时相助","flavor":true},{"id":"B-004","branch":"B","stage":1,"day":4,"shichen":"辰时","checkpoint":"试弦·004辰","scene":"登台前最后一日。晨起试弦，发现常用的一根弦起了毛，音色发闷。换弦要误半天工，不换又怕台上出岔。","options":[{"text":"宁可误工也要换弦","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"新弦调准，音色清亮如初。台上的体面，都是台下肯下笨功夫换的。","source":"宋代乐器养护见宋人笔记所载教坊乐器修治旧例。"},{"text":"将就旧弦上了再说","correct":false,"tags":["才华"],"dims":{"才华":0},"feedback":"弦音发闷，你自己先皱了眉。糊弄乐器，就是糊弄耳朵尖的客人。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"工欲善其事的态度贯穿全线"},{"id":"B-004-未","branch":"B","stage":1,"day":4,"shichen":"未时","checkpoint":"试弦·004未","scene":"午后，掌班拿来明日登台的席单：开场你压轴前的位子。他又补一句，明晚有位爱听琵琶的雅客包了好席，耳朵极刁。","options":[{"text":"加练到深夜备足曲目","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"三支曲子磨到指尖发烫。雅客刁不刁不知道，你先要过自己的耳朵。","source":"《东京梦华录》载汴京酒楼笙歌竞逐、客点曲目之俗。"},{"text":"早睡养神明日再说","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"觉是睡足了，心里却总悬着。上台前那份空落，只有自己知道。","source":"同上。"}],"difficulty":2,"npc":["掌班"],"foreshadow":"雅客身份后文揭晓"},{"id":"B-004-戌","branch":"B","stage":1,"day":4,"shichen":"戌时","checkpoint":"试弦·004戌","flavor":true,"scene":"入夜，你把妆匣最底层的一个小木匣拿出来，里头是这几月攒下的零星缠头。铜钱碰撞，声音不大，却踏实。","options":[{"text":"记下数目重新藏好","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一笔笔记清。这匣子里攒的不是钱，是往后脱籍的底气。","source":"宋代乐人自赎旧例见宋人笔记所载乐户脱籍之难。"},{"text":"添一枚新得的铜钱","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"铜钱落进匣子，清脆一声。路远，就从这一枚一枚走起。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"木匣攒钱为自赎主线"},{"id":"B-005","branch":"B","stage":1,"day":5,"shichen":"辰时","checkpoint":"琵琶初试·005辰","scene":"初试之日。樊楼华灯未上，你抱着琵琶立在帘后，听得外头座次渐满。掌班掀帘看了一眼：姑娘，该你了。","options":[{"text":"定神登场,先声夺人","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":2},"feedback":"一声裂帛，满楼俱静，曲终喝彩轰然。樊楼记住了你的名字。","source":"《东京梦华录》载樊楼（白矾楼）为京师酒楼之冠，笙歌达旦。"},{"text":"怯场缩手弹得拘谨","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"曲子没出错，可也没出声色。客人礼貌地鼓了掌，转身接着喝酒。","source":"同上。"}],"difficulty":3,"npc":["掌班"],"foreshadow":"初试之名为后文发难伏笔"},{"id":"B-005-未","branch":"B","stage":1,"day":5,"shichen":"未时","checkpoint":"琵琶初试·005未","scene":"午后加场，昨夜那位耳朵刁的雅客果然在座，听罢一曲，命人送上一封缠头，又传话：指下有筋骨，难得。","options":[{"text":"谢赏并请教不足之处","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"雅客真说了三处瑕疵，句句在点上。肯听真话的人，才弹得进第二层。","source":"宋代文人评点伎艺见《碧鸡漫志》所载词乐品评之风。"},{"text":"受赏得意不再多问","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"缠头收下了，指点却错过了。好话养耳，真话养艺。","source":"同上。"}],"difficulty":2,"npc":["雅客"],"foreshadow":"雅客指点为技艺进阶线"},{"id":"B-005-戌","branch":"B","stage":1,"day":5,"shichen":"戌时","checkpoint":"琵琶初试·005戌","flavor":true,"scene":"初试之夜，楼中姐妹都来道贺。喧嚣散后，你抱琴坐到窗前，看楼下汴河方向的灯火，心慢慢静下来。","options":[{"text":"把雅客指点记进小谱","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"谱上又添三行字。名声是别人的，长进是自己的。","source":"宋代乐工传习口诀见宋人笔记。"},{"text":"给娘写了封平安信","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"信里只报喜。樊楼的灯再亮，也别忘了家里那盏。","source":"宋代书信托寄见宋人笔记所载汴京书铺递信之俗。"}],"difficulty":1,"npc":["樊楼姐妹"],"foreshadow":"家信为家世暗线留口"},{"id":"B-006","branch":"B","stage":1,"day":6,"shichen":"辰时","checkpoint":"较技·006辰","scene":"初试之后，楼外已有人来打听你的名字。晨起，掌班递来三张请帖，都是这几晚点你弹唱的席面。","options":[{"text":"拣清雅的席先应下","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"席不在多，在净。你挑席面的眼光，连掌班都暗暗点头。","source":"《东京梦华录》载汴京酒楼筵席点伎之俗。"},{"text":"三张帖子全应下","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"贪多赶场，嗓子先哑了。名声这碗饭，饿的人吃不长久。","source":"宋人笔记所载歌伎赶场伤嗓旧闻。"}],"difficulty":2,"npc":["掌班"],"foreshadow":"挑席原则护住后文口碑"},{"id":"B-006-未","branch":"B","stage":1,"day":6,"shichen":"未时","checkpoint":"较技·006未","scene":"午后，同楼一位资历深的歌伎当众发难，说你新得宠就翘尾巴，要与你当堂较技，一曲定高下。","options":[{"text":"拱手应战,曲里见真章","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"你不温不火弹完，满楼自有公论。较技赢的是艺，不是脸。","source":"《东京梦华录》载京瓦伎艺斗巧竞胜之风。"},{"text":"当场讥她倚老卖老","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"嘴上赢了，楼里传开的却是你刻薄。锋芒要用在弦上，不是舌上。","source":"同上。"}],"difficulty":3,"npc":["资深歌伎"],"foreshadow":"较技结下的梁子后文化解"},{"id":"B-006-戌","branch":"B","stage":1,"day":6,"shichen":"戌时","checkpoint":"较技·006戌","flavor":true,"scene":"夜散，较技输了的歌伎独自坐在后院擦琴。你端了盏热茶过去，她愣了一下，没接，也没推开。","options":[{"text":"放下茶盏陪她坐会儿","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"半晌她低声说了句「指法不错」。楼里的恩怨，有时一盏茶就化了。","source":"宋人笔记所载教坊同侪相处旧俗。"},{"text":"请教她一处旧指法","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"她终是伸手示范了一遍。肯低头学艺，比赢一场较技更体面。","source":"唐宋琵琶指法传承见《乐府杂录》。"}],"difficulty":1,"npc":["资深歌伎"],"foreshadow":"化敌为友,日后替她说项"},{"id":"B-007","branch":"B","stage":1,"day":7,"shichen":"辰时","checkpoint":"州桥初遇·007辰","scene":"你难得告了半日假，去州桥书肆寻两册旧词集。书肆不大，架间一个青衫书生正踮脚够高处一册《乐章集》，袖口磨得发白。","options":[{"text":"替他取下那册词集","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"书生接书道谢，眉目清瘦，眼里却有光。他说他也在寻好句子。","source":"《东京梦华录》载州桥一带书肆林立、士子往来之盛。"},{"text":"自顾寻书不去理会","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"你寻到书走了，身后书生还踮着脚。有些缘分，一转身就散了。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"州桥初遇,词缘之始"},{"id":"B-007-未","branch":"B","stage":1,"day":7,"shichen":"未时","checkpoint":"州桥初遇·007未","scene":"书肆里，那书生见你挑的也是词集，忍不住搭话，说他最佩服会唱的人——词要入了乐，才算活过来。","options":[{"text":"与他论词乐相合之理","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":1,"情缘":2},"feedback":"你谈起四声入乐，他听得入神，连说受教。这一席话，比初见更重。","source":"词乐关系见《碧鸡漫志》所论词曲声律。"},{"text":"寒暄两句便起身告辞","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"书生拱手自去。你抱着书出门，却总觉得方才的话没说完。","source":"宋人笔记所载市井士女酬答之常。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"词乐之论奠定相知根基"},{"id":"B-007-戌","branch":"B","stage":1,"day":7,"shichen":"戌时","checkpoint":"州桥初遇·007戌","flavor":true,"scene":"夜归樊楼，你翻着白日买的词集，忽然想起书肆里那句「词要入乐才算活过来」，指尖不自觉在桌上打着拍子。","options":[{"text":"挑一阕试着谱上新腔","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"旧词配新腔，竟意外地合。你忽然好奇，那人写词时听的是什么调。","source":"《碧鸡漫志》载宋人度曲填词、以词合乐之习。"},{"text":"在书页间记下他那句话","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"小字记在页脚。有些话值得记下来，慢慢想。","source":"宋代士人批点书籍之习见宋人笔记。"}],"difficulty":1,"npc":[],"foreshadow":"新腔试验引来正式唱和"},{"id":"B-008","branch":"B","stage":1,"day":8,"shichen":"辰时","checkpoint":"赠词·008辰","scene":"晨起，书肆伙计送来个纸包——是那青衫书生托带的：一阕新词，附了张小字条，说昨日一席话受益匪浅，拙词敢请姑娘一唱。","options":[{"text":"细读新词试谱曲调","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":1},"feedback":"词是好词，清瘦里有筋骨。你谱了半夜，弦声一起，词像真活了。","source":"宋代词乐唱和见《碧鸡漫志》及宋人词话。"},{"text":"搁置纸包先忙正事","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"纸包搁了三日。再打开时，那点初见的兴头已凉了一半。","source":"宋人笔记所载词简往来旧俗。"}],"difficulty":2,"npc":["落魄词人","书肆伙计"],"foreshadow":"首阕赠词开启唱和线"},{"id":"B-008-未","branch":"B","stage":1,"day":8,"shichen":"未时","checkpoint":"赠词·008未","scene":"午后你将新词试唱给掌班听。掌班听完沉吟半晌：词不俗，只是这人无名无姓，传出去怕带不动席面。","options":[{"text":"坚持词好便能立住","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你说：词好，奴家的琵琶也不差，两好合一好。掌班终是点了头。","source":"《东京梦华录》载酒楼新声竞逐、词以唱传之俗。"},{"text":"依掌班换唱名家旧词","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"旧词稳当，可你弹着总觉得少口气。稳妥二字，有时是捆人的绳。","source":"同上。"}],"difficulty":3,"npc":["掌班"],"foreshadow":"无名新词日后轰动汴京"},{"id":"B-008-戌","branch":"B","stage":1,"day":8,"shichen":"戌时","checkpoint":"赠词·008戌","flavor":true,"scene":"夜里你写回帖给书肆，谢过赠词，又忍不住在末尾添了一行小字，问他下一句平仄可有讲究。写完自己先笑了。","options":[{"text":"连谱一并封好送去","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"词回人去，谱也回人去。这一来一往，就不是一锤子买卖了。","source":"宋代词简往返见宋人词话所载唱酬之雅。"},{"text":"只回谢帖不提平仄","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"帖子回得客客气气。有些话不急，留到下次见面再说。","source":"宋人笔记所载士女酬答分寸。"}],"difficulty":1,"npc":[],"foreshadow":"回帖往来,情缘渐生"},{"id":"B-009","branch":"B","stage":1,"day":9,"shichen":"辰时","checkpoint":"锋芒·009辰","scene":"名声起来，麻烦也来。晨间有豪客遣仆来，出重金点你过府陪宴三日，话里话外不是听曲的意思。","options":[{"text":"婉拒:樊楼曲不出门","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你回得客气却铁硬：奴家卖艺不卖身。仆从讪讪去了，掌班暗竖拇指。","source":"宋代歌伎守身拒客事见宋人笔记所载名伎风骨旧闻。"},{"text":"含糊推说身子不适","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"推得了一时，推不了一世。含糊的话头，最易被人当成口子撕。","source":"同上。"}],"difficulty":3,"npc":["豪客仆从"],"foreshadow":"拒绝豪客引来权贵注目"},{"id":"B-009-未","branch":"B","stage":1,"day":9,"shichen":"未时","checkpoint":"锋芒·009未","scene":"午后席间，有客人借酒起了轻薄话头，满席哄笑。你抱着琵琶立在当场，进退之间，只在一句话。","options":[{"text":"一曲《凉州》压下满席","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"大弦嘈嘈如急雨，笑声全被弦声盖住。曲终你敛衽一礼，无人再敢轻薄。","source":"《凉州》大曲见《碧鸡漫志》所记唐宋大曲流变。"},{"text":"强笑着敷衍过去","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"笑声是止了，可那种笑黏在身上，洗不掉。忍下的每一分，都要自己消化。","source":"宋人笔记所载歌筵应酬之苦。"}],"difficulty":3,"npc":["醉酒客人"],"foreshadow":"锋芒初露,权贵线前奏"},{"id":"B-009-戌","branch":"B","stage":1,"day":9,"shichen":"戌时","checkpoint":"锋芒·009戌","flavor":true,"scene":"夜静，你卸了妆，对镜看着素净的脸。白日的哄笑还在耳边，可指尖搭在弦上时，心又稳了。","options":[{"text":"弹一段慢调平复心绪","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"弦声低回，把白日的浊气一点点滤净。琵琶是你的盾，也是你的药。","source":"宋人词话所载以乐遣怀之习。"},{"text":"把白日事记进小册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"记下谁的笑、谁的话。不是要记仇，是要记着：这楼里的路，得自己踩平。","source":"宋人笔记所载记事册之习。"}],"difficulty":1,"npc":[],"foreshadow":"小册记事后文派上用场"},{"id":"B-010","branch":"B","stage":1,"day":10,"shichen":"辰时","checkpoint":"樊楼立名·010辰","scene":"立名之夜到了。樊楼最大的厅座无虚席，都说要听那支无名书生的新词，配你的新腔。帘后，你最后一次调弦。","options":[{"text":"倾尽全力唱这一曲","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"一曲既终，满楼喝彩如雷，有人当场抄词。汴京自此知道樊楼有你。","source":"《东京梦华录》载樊楼笙歌之盛,新声传唱京师之俗。"},{"text":"求稳收了三分力气","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"唱得不坏，可缺了那点豁出去的光。立名只一回，收着唱可惜了。","source":"同上。"}],"difficulty":3,"npc":["掌班","雅客"],"foreshadow":"一词成名,引来暗处的目光"},{"id":"B-010-未","branch":"B","stage":1,"day":10,"shichen":"未时","checkpoint":"樊楼立名·010未","scene":"午后，楼外已有人传抄昨夜的新词。掌班笑得合不拢嘴，说打赏比平日多了三倍，问你想要什么彩头。","options":[{"text":"请把缠头按账结清","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"彩头不要，账目要清。掌班愣了愣，到底服了：这姑娘心里有杆秤。","source":"宋代乐人缠头分成旧例见宋人笔记。"},{"text":"讨一支时新珠钗","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"珠钗好看，却换不来脱籍的文书。热闹过后，账上没多几个钱。","source":"同上。"}],"difficulty":2,"npc":["掌班"],"foreshadow":"账目清白为自赎铺路"},{"id":"B-010-戌","branch":"B","stage":1,"day":10,"shichen":"戌时","checkpoint":"樊楼立名·010戌","flavor":true,"scene":"立名之夜，贺客散尽。书肆伙计又送来个小纸包，这回只有一张字条：「词因曲活，幸甚至哉。」字瘦，笔笔用力。","options":[{"text":"回他「曲待词新」四字","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"四字回过去，意思他懂：下一阕，还等他写。纸上往来，也有心跳。","source":"宋代唱酬字简见宋人词话。"},{"text":"把字条收进妆匣底层","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"字条和缠头匣子放在一处。一样是生计，一样是心事，都攒着。","source":"宋人笔记所载闺中藏札旧俗。"}],"difficulty":1,"npc":["书肆伙计"],"foreshadow":"四字之约,唱和不断"},{"id":"B-011","branch":"B","stage":1,"day":11,"shichen":"辰时","checkpoint":"唱和·011辰","scene":"晨起，那书生亲自来了书肆口信之外的东西——他候在樊楼后巷，抱着一册手抄词稿，说想把整册都交给你，只唱给你认可的调。","options":[{"text":"接下词稿约定唱和","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"词稿入手沉甸甸的。他说词，你谱曲，这才是棋逢对手的相知。","source":"宋代词人与歌者唱和见《碧鸡漫志》及宋人词话。"},{"text":"避嫌不收私人词稿","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"书生讪讪收稿而去。避嫌是稳妥，可有些稿，推开了就是一生。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"整册词稿为唱和主线"},{"id":"B-011-未","branch":"B","stage":1,"day":11,"shichen":"未时","checkpoint":"唱和·011未","scene":"午后，头牌姐姐提醒你：如今你是樊楼的脸面，私下收男子词稿，传出去招人话柄。她盯着你，等你的回话。","options":[{"text":"坦然:词稿是艺不是私","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你说得磊落：词过掌班的眼，曲走樊楼的台。行得正，话柄就抓不住。","source":"宋代歌楼规矩见《东京梦华录》及宋人笔记。"},{"text":"慌忙把词稿藏起来","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"一藏，倒像真有了什么。光天化日的事，别做得鬼鬼祟祟。","source":"同上。"}],"difficulty":3,"npc":["头牌歌伎"],"foreshadow":"磊落行事堵住日后谗言"},{"id":"B-011-戌","branch":"B","stage":1,"day":11,"shichen":"戌时","checkpoint":"唱和·011戌","flavor":true,"scene":"夜里你翻那册词稿，一页一页，多是写市井小人物：卖花的老妪、守桥的老卒。词不华丽，却句句有体温。","options":[{"text":"挑写老卒那阕先谱","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"谱到「霜满州桥」一句，你停了停。能写出这句的人，心是热的。","source":"宋代民间词风见宋人词话所载咏市井之作。"},{"text":"在稿边批注试唱心得","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"蝇头小楷写满页边。你批得认真，像在对一个看不见的人说话。","source":"宋代批点之习见宋人笔记。"}],"difficulty":1,"npc":[],"foreshadow":"「霜满州桥」句后文重现"},{"id":"B-012","branch":"B","stage":1,"day":12,"shichen":"辰时","checkpoint":"赠我词·012辰","scene":"唱和日深，词稿里有一阕明显是写你的——「弦上有霜华，不向人间媚」。晨读此句，你握着稿纸出了会儿神。","options":[{"text":"认真谱曲不负此句","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":2},"feedback":"他懂你弦上的骨头，你便还他弦上的魂。这曲谱得比哪支都用心。","source":"宋人词话所载以词赠歌者之雅事。"},{"text":"压下此阕暂不碰它","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"稿纸压回箱底。有些句子不敢碰，是怕自己接不住。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"赠我之词为定情信物"},{"id":"B-012-未","branch":"B","stage":1,"day":12,"shichen":"未时","checkpoint":"赠我词·012未","scene":"午后试唱新谱，老乐工在廊下听了半晌，忽然说：这词配你的弦，像量身裁的。写词的人，懂乐，更懂你。","options":[{"text":"请老乐工再指点转调","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"转调处又顺了三分。好曲是磨出来的，磨的是艺，也是心。","source":"唐宋乐工传习见《乐府杂录》。"},{"text":"红着脸岔开了话","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"老乐工笑笑没再往下说。有些心意，旁人都看在眼里。","source":"宋人笔记所载教坊日常。"}],"difficulty":2,"npc":["老乐工"],"foreshadow":"老乐工察觉情缘,后文成全"},{"id":"B-012-戌","branch":"B","stage":1,"day":12,"shichen":"戌时","checkpoint":"赠我词·012戌","flavor":true,"scene":"夜场散了，你收到书肆带回的回稿——那阕写你的词，他依你的批注重改了两个字，改得确实更好。末尾画了个小小的琵琶。","options":[{"text":"把改稿与原稿并藏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"两稿并在一处，一字之差，看得出他肯为你磨。这份心，比词重。","source":"宋代改词旧例见宋人词话所载炼字之习。"},{"text":"夜灯下再唱一遍新改","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"改过的句子在弦上滚过，字字妥帖。隔着半座城，你们在一首词里相见。","source":"《碧鸡漫志》所载词曲相合之理。"}],"difficulty":1,"npc":[],"foreshadow":"改词两稿为后文凭证"},{"id":"B-013","branch":"B","stage":1,"day":13,"shichen":"辰时","checkpoint":"词名之争·013辰","scene":"麻烦来了。新词传抄太广，有词客不服气，在瓦子里放话，说樊楼新声徒有其名，词是穷措大写的，不值一唱。","options":[{"text":"设席再唱以曲服人","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":2},"feedback":"你当众再唱，弦停满座寂然，先前放话的人也抄了词走。好曲不怕吵。","source":"《东京梦华录》载京瓦伎艺争胜、新声传唱之俗。"},{"text":"请掌班出面压一压","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"掌班压得住瓦子的嘴，压不住人心。艺上的事，终要艺来平。","source":"宋人笔记所载瓦子口舌之争。"}],"difficulty":3,"npc":["挑事词客","掌班"],"foreshadow":"词名之争惊动更高处"},{"id":"B-013-未","branch":"B","stage":1,"day":13,"shichen":"未时","checkpoint":"词名之争·013未","scene":"午后，书肆伙计带来口信：书生听闻外头讥他穷措大，要把词稿索回，说怕连累你的名声。","options":[{"text":"回话:词好何惧人言","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"你让伙计带话：词在奴家这里，谁也索不走。书生听罢，据说沉默良久。","source":"宋人词话所载词者相知、不以穷达易心之事。"},{"text":"劝他暂避风头也好","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"话是好意，可「避」字一出，像把他往外推了一步。他回了个「嗯」。","source":"同上。"}],"difficulty":3,"npc":["书肆伙计"],"foreshadow":"护词之举深植情缘"},{"id":"B-013-戌","branch":"B","stage":1,"day":13,"shichen":"戌时","checkpoint":"词名之争·013戌","flavor":true,"scene":"夜里，你点了支蜡，把白日那场再唱的曲目、座中反应一一记下，末了添一句：词无贵贱，入耳为真。","options":[{"text":"把这句抄给书生看","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"八字送去，书生回了满纸。两个穷讲究的人，总算不孤单。","source":"宋代词简唱酬见宋人词话。"},{"text":"独对灯花坐了半宿","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"名声是把双刃剑，今夜你头一回掂出它的分量。","source":"宋人笔记所载名伎处境之思。"}],"difficulty":1,"npc":[],"foreshadow":"「入耳为真」成二人信物"},{"id":"B-014","branch":"B","stage":1,"day":14,"shichen":"辰时","checkpoint":"脱籍律条·014辰","scene":"晨起你去了趟书铺，不为词集，为打听一件事：教坊乐籍的女子，若要自赎脱籍，律上该走哪条路，要备多少钱。","options":[{"text":"细查律条逐条抄录","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"条文抄得密密麻麻。路难走，但纸上明明白白写着：走得通。","source":"宋代乐户脱籍之制见《宋刑统》及宋人笔记所载。"},{"text":"听个大概便回去了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大概最害人。数目差一贯，文书差一字，脱籍就可能黄在最后一刻。","source":"同上。"}],"difficulty":3,"npc":["书铺掌柜"],"foreshadow":"脱籍律条为自赎路线图"},{"id":"B-014-未","branch":"B","stage":1,"day":14,"shichen":"未时","checkpoint":"脱籍律条·014未","scene":"午后你盘了盘缠头匣子：离自赎的数目还差一大截。鸨母恰好路过，瞟了一眼你的匣子，笑得意味深长。","options":[{"text":"坦然说明攒钱赎身","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你把话挑明：攒够了就走正路赎。鸨母收了笑：行，账目我不亏你。","source":"宋代乐人自赎旧例见宋人笔记。"},{"text":"慌忙遮掩说是体己","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"一遮掩，鸨母的眼神就变了。楼里的钱，藏出来的最不经查。","source":"同上。"}],"difficulty":3,"npc":["鸨母"],"foreshadow":"鸨母默许为后文关键人情"},{"id":"B-014-戌","branch":"B","stage":1,"day":14,"shichen":"戌时","checkpoint":"脱籍律条·014戌","flavor":true,"scene":"夜里你把抄来的律条又看了一遍，在最末一条旁边写了个小小的「盼」字。窗外更鼓声远，一更一更，都像在数日子。","options":[{"text":"把律条压在琵琶盒底","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"琴护着律，律护着人。往后每弹一曲，都离那纸文书近一分。","source":"宋人笔记所载乐户脱籍旧闻。"},{"text":"算了算还需多少场","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"数目写在纸上，吓人，却不绝望。有数的日子，熬得住。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"更鼓数日子呼应收官"},{"id":"B-015","branch":"B","stage":1,"day":15,"shichen":"辰时","checkpoint":"一词难求·015辰","scene":"唱和新词彻底火了。晨起楼外已有人排队求座，连外州来的客商都点名要听「樊楼琵琶、州桥词」。一词难求，说的就是眼下。","options":[{"text":"把新词唱成压轴定例","correct":true,"tags":["名声","才华"],"dims":{"名声":2,"才华":2},"feedback":"定例一立，座无虚席。你与书生的名字，从此绑在一处传遍汴京。","source":"《东京梦华录》载樊楼之盛与汴京新声竞传之俗。"},{"text":"涨价惜售吊足胃口","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"座价是上去了，口碑却淡了些。饥渴的把戏，玩一次鲜，玩两次贱。","source":"宋人笔记所载酒楼经营旧闻。"}],"difficulty":3,"npc":["掌班"],"foreshadow":"词名远播直达权贵之耳"},{"id":"B-015-未","branch":"B","stage":1,"day":15,"shichen":"未时","checkpoint":"一词难求·015未","scene":"午后，有富室托人带话，愿出百金请书生只为他们家写词，条件是断了与樊楼的唱和。书生让那人原话带回给你听。","options":[{"text":"由他自己定,不劝不拦","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"书生回绝了百金，只捎来一句：词有价，知音无价。你听完，指尖发烫。","source":"宋人词话所载清贫词人不肯鬻文之事。"},{"text":"劝他接下以解穷困","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"话是好心，可你听自己说出口，都觉得凉。他回：连你也这样想么。","source":"同上。"}],"difficulty":3,"npc":["落魄词人","富室仆从"],"foreshadow":"百金拒售,气节立住"},{"id":"B-015-戌","branch":"B","stage":1,"day":15,"shichen":"戌时","checkpoint":"一词难求·015戌","flavor":true,"scene":"夜里，书生托伙计送来新词一阕，是为白日之事写的：「百金难买弦上语」。字条上还沾着书肆的墨香。","options":[{"text":"连夜谱曲以答此心","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"谱到天色微明。他护住词，你护住曲，谁也没负谁。","source":"宋代唱和雅事见宋人词话。"},{"text":"将词笺收入琵琶盒","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"词笺挨着律条放好。一样是前程，一样是人心，都丢不得。","source":"宋人笔记所载藏札之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「百金难买」句为后文定情"},{"id":"B-016","branch":"B","stage":1,"day":16,"shichen":"辰时","checkpoint":"权贵初现·016辰","scene":"晨起，掌班神色凝重地告诉你：有位姓高的殿前权贵听闻了你的名字，遣人递话，说过几日要包下樊楼顶层，专听你弹唱。","options":[{"text":"照常准备,不卑不亢","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"权贵也是听客，曲子该怎么弹还怎么弹。你先稳了，掌班也跟着稳了。","source":"《东京梦华录》载樊楼为贵家宴集之所。"},{"text":"托病推掉这场席面","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"病推得掉席面，推不掉人心里的惦记。躲出来的清静，最不清静。","source":"宋人笔记所载权贵召伎之旧例。"}],"difficulty":3,"npc":["掌班"],"foreshadow":"高姓权贵登场,暗线启动"},{"id":"B-016-未","branch":"B","stage":1,"day":16,"shichen":"未时","checkpoint":"权贵初现·016未","scene":"午后，头牌姐姐悄悄找你：她年轻时也遇过这样的贵客，劝你一句——席上只谈曲，不接私话，赏物过手的都要让人看见。","options":[{"text":"谨记,事事摆在明处","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你把每条都记下。过来人的经验，都是用跟头换的，得接着。","source":"宋代歌伎自守之智见宋人笔记所载名伎旧事。"},{"text":"笑她过于小心了","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"姐姐叹了口气没再劝。有些坑，非得自己踩过才认得。","source":"同上。"}],"difficulty":2,"npc":["头牌歌伎"],"foreshadow":"姐姐的规劝救命于后"},{"id":"B-016-戌","branch":"B","stage":1,"day":16,"shichen":"戌时","checkpoint":"权贵初现·016戌","flavor":true,"scene":"夜里书生捎来一阕新词，写的是檐角风铃。字条上多了句闲话：听闻贵客将至，他只说「姑娘的弦，不必为谁改调」。","options":[{"text":"回信:弦有定音,人有定心","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"八字送去。他懂你未说出口的警觉，这份懂，比安慰值钱。","source":"宋代词简唱酬见宋人词话。"},{"text":"夜弹风铃词以静心","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"弦上叮咚如檐铃。天大的事，先把心调准了再说。","source":"宋人词话所载以乐定心之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「弦有定音」为拒权贵伏笔"},{"id":"B-017","branch":"B","stage":1,"day":17,"shichen":"辰时","checkpoint":"三本账·017辰","scene":"晨起对账，这月缠头进账不少。你想起书铺抄来的律条，把进账分成三份：一份赎金、一份日用、一份应急。","options":[{"text":"立账本分簿严加执行","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"三本小账立起来，钱各有去处。赎身不是梦，是一笔一笔的账。","source":"宋代市井记账之习见宋人笔记。"},{"text":"先买几样时新妆扮","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"妆匣满了，钱匣瘪了。楼里的姑娘，最怕把本钱穿在身上。","source":"宋人笔记所载歌伎挥霍误身之戒。"}],"difficulty":2,"npc":[],"foreshadow":"三本账为自赎进度条"},{"id":"B-017-未","branch":"B","stage":1,"day":17,"shichen":"未时","checkpoint":"三本账·017未","scene":"午后，有同行姐妹来借钱，说是家中急用。数目不小，够你赎金的三成。她红着眼眶，说满楼只有你拿得出。","options":[{"text":"借半数,立好字据","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"钱借了，字据也立了，情分账目两清。姐妹含泪道谢：你是个明白人。","source":"宋代民间借贷立约之俗见宋人笔记。"},{"text":"倾囊相借不立字据","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钱全出去了，话却没说死。仗义是好事，可赎身的日子不能靠别人自觉。","source":"同上。"}],"difficulty":3,"npc":["同行姐妹"],"foreshadow":"字据人情后文双收"},{"id":"B-017-戌","branch":"B","stage":1,"day":17,"shichen":"戌时","checkpoint":"三本账·017戌","flavor":true,"scene":"夜里记账，赎金那本的数字终于翻过一半。你盯着那个数看了很久，第一次觉得「离开」两个字，有了形状。","options":[{"text":"在账角画一朵小花","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"小花不成体统，却是给自己的。苦日子里，要会给自己发糖。","source":"宋人笔记所载账册批注之习。"},{"text":"合上账本弹曲安眠","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"曲子弹得很轻，怕吵醒钱匣里的指望。日子有声有色地往前挪。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"赎金过半,引来觊觎"},{"id":"B-018","branch":"B","stage":1,"day":18,"shichen":"辰时","checkpoint":"却金·018辰","scene":"高姓权贵的席面到了。顶层华筵，珍馐满案。他听罢一曲，抚掌称赞，随即命人捧上一副赤金头面：「姑娘配这个。」满座都在看你的反应。","options":[{"text":"谢赏不收,礼数周全","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你敛衽：赏奴家听曲钱，奴家受之无愧；这头面太贵重，不敢当。满堂叫好。","source":"宋代名伎却赠守节事见宋人笔记所载。"},{"text":"顺势收下以结善缘","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"金头面入手滚烫。权贵笑了，那笑的意思是：第一件能收，第二件呢？","source":"宋人笔记所载权贵结纳之手段。"}],"difficulty":3,"npc":["高姓权贵"],"foreshadow":"金头面之拒结下怨念"},{"id":"B-018-未","branch":"B","stage":1,"day":18,"shichen":"未时","checkpoint":"却金·018未","scene":"席散，权贵临走留下一句意味深长的话：「姑娘这样的人，困在樊楼可惜了。」鸨母送你回房，一路无话，脸色发白。","options":[{"text":"向鸨母明言自守之意","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你说：奴家卖艺不卖身，更不卖一辈子。鸨母长叹一声，点了点头。","source":"宋代名伎自守旧闻见宋人笔记。"},{"text":"装糊涂回房歇下","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"糊涂装得了一时。楼里上上下下都在猜你的态度，沉默最招解读。","source":"同上。"}],"difficulty":3,"npc":["高姓权贵","鸨母"],"foreshadow":"「不卖一辈子」为名句底线"},{"id":"B-018-戌","branch":"B","stage":1,"day":18,"shichen":"戌时","checkpoint":"却金·018戌","flavor":true,"scene":"夜里，书生听闻白日之事，遣伙计送来一阕词，题为《赠弦上霜》。末尾一句：「霜自有骨，不待春温。」","options":[{"text":"回赠旧帕包一方新墨","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"帕子是干净的，墨是普通的，意思他懂：我的清白，自己守得住。","source":"宋代士女赠答之雅见宋人词话。"},{"text":"弹《赠弦上霜》至三更","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"弦声清越如霜击瓦。这一曲不为客人，只为知音。","source":"《碧鸡漫志》所载以曲寄情之习。"}],"difficulty":1,"npc":["落魄词人","书肆伙计"],"foreshadow":"《赠弦上霜》为二人定情曲"},{"id":"B-019","branch":"B","stage":1,"day":19,"shichen":"辰时","checkpoint":"护词·019辰","scene":"风波殃及池鱼。晨起听闻，权贵的门客在瓦子里讥讽书生：「写词的也配攀樊楼？」更有人放话要让他开不成书肆的摊子。","options":[{"text":"托掌班为书生说公道话","correct":true,"tags":["情缘","名声","感情"],"dims":{"情缘":2,"名声":1},"feedback":"掌班出面，瓦子里的风声敛了三分。护他不必亲自动手，动的是真章。","source":"《东京梦华录》载瓦子口舌与酒楼调停之俗。"},{"text":"亲自去瓦子理论","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"你一去，反倒坐实了流言。满瓦子看的不是道理，是热闹。","source":"宋人笔记所载市井流言之烈。"}],"difficulty":3,"npc":["权贵门客","掌班"],"foreshadow":"书生受辱,权贵再施压力"},{"id":"B-019-未","branch":"B","stage":1,"day":19,"shichen":"未时","checkpoint":"护词·019未","scene":"午后书生来了，衣角沾尘，神色却平静。他说摊子还在，词也还在写，只是不想你因他受半分委屈。","options":[{"text":"直言:委屈是奴家自己选的","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":2},"feedback":"你答：与你唱和是奴家自己选的路，选了就认。书生怔住，眼眶微红。","source":"宋人词话所载风尘知己旧事。"},{"text":"劝他暂避外州风头","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"书生没接话。他穷，可从没想过躲。你这话，轻看了他的骨头。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"「自己选的路」为情缘宣言"},{"id":"B-019-戌","branch":"B","stage":1,"day":19,"shichen":"戌时","checkpoint":"护词·019戌","flavor":true,"scene":"夜里你翻出他改过的两稿词，并排放着看。一稿一词，一字一磨。外头的风浪再大，这两张纸上干干净净。","options":[{"text":"把两稿裱在一处收好","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"裱纸抚平，字字安稳。世道再浑，总要护住一处干净地方。","source":"宋代装裱藏书之习见宋人笔记。"},{"text":"依两稿之意再谱新腔","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"新腔比旧谱更沉。词没变，唱的人心境深了，曲就深了。","source":"《碧鸡漫志》所载词曲相生之理。"}],"difficulty":1,"npc":[],"foreshadow":"裱合词稿为后文信物"},{"id":"B-020","branch":"B","stage":1,"day":20,"shichen":"辰时","checkpoint":"缠头自攒·020辰","scene":"攒钱小坎。晨起盘账，赎金只差最后一成了。鸨母站在你房门口，破天荒地主动开口：数目我帮你核过了，不差。","options":[{"text":"请鸨母做个中人见证","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"中人一立，赎身就走上了明路。鸨母叹道：你是我见过最沉得住气的。","source":"宋代脱籍需中保之制见宋人笔记所载。"},{"text":"想再攒些体己再说","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"「再等等」三个字最耗人。鸨母点点头走了，你心里却空了一块。","source":"同上。"}],"difficulty":3,"npc":["鸨母"],"foreshadow":"中人既立,权贵再难暗手"},{"id":"B-020-未","branch":"B","stage":1,"day":20,"shichen":"未时","checkpoint":"缠头自攒·020未","scene":"午后，曾借你钱的姐妹提前来还账，还多封了一份利钱。她说：你那日肯信我，这份情我还一辈子。","options":[{"text":"收本金,利钱退回去","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"利钱推回去，情分留下来。姐妹抹着眼泪笑：往后你的事就是我的事。","source":"宋代民间借贷旧俗见宋人笔记。"},{"text":"连本带利都收下","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"账是清了，姐妹的眼神也淡了半分。有些钱收了，就收薄了人情。","source":"同上。"}],"difficulty":2,"npc":["同行姐妹"],"foreshadow":"还账姐妹为收官助力"},{"id":"B-020-戌","branch":"B","stage":1,"day":20,"shichen":"戌时","checkpoint":"缠头自攒·020戌","flavor":true,"scene":"夜里，你把三本账并排放好，赎金那本快写满了。窗外有细雪飘落，落在州桥方向的屋檐上。你想起词稿里那句「霜满州桥」。","options":[{"text":"抄「霜满州桥」贴于琴侧","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"四个字贴在琴侧。往后每调一次弦，都看见有人在词里等你。","source":"宋人词话所载题句于器之习。"},{"text":"把雪夜光景写进回帖","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"帖上写：今夜汴京落雪，宜有新词。书生收到，据说磨墨磨了半宿。","source":"宋代词简催稿之雅见宋人词话。"}],"difficulty":1,"npc":[],"foreshadow":"雪夜帖催生收官新词"},{"id":"B-021","branch":"B","stage":1,"day":21,"shichen":"辰时","checkpoint":"权贵发难·021辰","scene":"发难之日。高姓权贵遣管家登门，话挑得明明白白：愿出千金为你脱籍，纳你入府为妾，「这是多少姑娘求不来的造化」。","options":[{"text":"正色回绝:卖艺不卖身","correct":true,"tags":["自主","名声"],"dims":{"自主":3,"名声":1},"feedback":"你当庭答：奴家卖艺不卖身，更不卖一辈子。管家拂袖而去，满楼皆知。","source":"宋代名伎拒纳守身事见宋人笔记所载。"},{"text":"请管家回府容后再议","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"「容后再议」四个字，被管家带回去就是「有戏」。口子一开，难收。","source":"宋人笔记所载权贵结纳之手段。"}],"difficulty":3,"npc":["权贵管家","鸨母"],"foreshadow":"当面回绝,权贵由诱转压"},{"id":"B-021-未","branch":"B","stage":1,"day":21,"shichen":"未时","checkpoint":"权贵发难·021未","scene":"午后，报复来得很快：权贵的门客放话给全城酒楼，谁敢再请你弹唱，就是与高家过不去。掌班急得团团转。","options":[{"text":"稳住掌班:樊楼自有根基","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你说：樊楼立的是汴京的客，不是一家的客。掌班一咬牙：接着开门！","source":"《东京梦华录》载樊楼为京师酒楼之冠,宾客如云。"},{"text":"劝掌班暂避其锋","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"门一关，名声就散了一半。躲得过今日，躲不过这一退再退。","source":"宋人笔记所载酒楼应酬权势之难。"}],"difficulty":3,"npc":["掌班","权贵门客"],"foreshadow":"樊楼硬扛,舆论暗涌"},{"id":"B-021-戌","branch":"B","stage":1,"day":21,"shichen":"戌时","checkpoint":"权贵发难·021戌","flavor":true,"scene":"夜里，楼中姐妹聚到你房里，没人提白日的事，只是这个递果子，那个添灯油。头牌姐姐最后说了句：樊楼的姑娘，不归谁家的府。","options":[{"text":"与姐妹们击掌为约","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"掌心相击，脆生生一响。风浪再大，这屋里有一屋子人陪你扛。","source":"宋人笔记所载教坊同侪相扶旧俗。"},{"text":"弹一曲谢过众姐妹","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"弦声不急不缓，弹的是《风入松》。松有劲节，人也是。","source":"《碧鸡漫志》所载唐宋曲调名目。"}],"difficulty":1,"npc":["头牌歌伎","樊楼姐妹"],"foreshadow":"姐妹同心为后文声援"},{"id":"B-022","branch":"B","stage":1,"day":22,"shichen":"辰时","checkpoint":"定计·022辰","scene":"晨起，坏消息接二连三：权贵买通人散布流言，说你的新词来路不正，还说要在官府里查樊楼的账。楼中人心惶惶。","options":[{"text":"请鸨母亮账,自清于众","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":2},"feedback":"账目摊在日头底下，笔笔清白。流言撞上明账，自己先散了。","source":"宋代账目质证之俗见宋人笔记所载诉讼旧例。"},{"text":"隐忍不言待风头过","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"你不辩，流言就替你辩。三日之间，「来路不正」越传越像真的。","source":"宋人笔记所载流言之害。"}],"difficulty":3,"npc":["鸨母","权贵门客"],"foreshadow":"明账之举救樊楼于后"},{"id":"B-022-未","branch":"B","stage":1,"day":22,"shichen":"未时","checkpoint":"定计·022未","scene":"午后，书生匆匆赶来，说他打听到权贵的软肋：高家正在巴结朝中清议，最怕的就是「强纳乐籍」的名声传出去。","options":[{"text":"据此商定以名制名之策","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你二人灯下定计：把「拒纳」唱成佳话，让清议替你挡刀。险棋，但可下。","source":"宋代清议之重见宋人笔记所载士大夫风评之俗。"},{"text":"让书生莫再蹚浑水","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"书生摇头：你的浑水，我蹚定了。你想护他，他却先一步护住了你。","source":"宋人词话所载风尘知己旧事。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"以名制名为反击主线"},{"id":"B-022-戌","branch":"B","stage":1,"day":22,"shichen":"戌时","checkpoint":"定计·022戌","flavor":true,"scene":"夜里，书生留下一盏粗茶的工夫就走了。临走他说：这几日他写词，你只管弹，弹得越响，他们越不敢动你。","options":[{"text":"目送他到巷口灯影里","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"青衫没入夜色。你忽然明白，所谓并肩，就是风浪里谁也不松手。","source":"宋人笔记所载汴京夜巷灯市之景。"},{"text":"连夜练新曲备后日","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"他写他的词，你磨你的弦。两个人的仗，两个人各打各的半场。","source":"宋人词话所载唱和相砥砺之事。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"并肩之约直指收官"},{"id":"B-023","branch":"B","stage":1,"day":23,"shichen":"辰时","checkpoint":"霜弦引·023辰","scene":"反击落子。晨起，书生将一阕新词送上——《霜弦引》，通篇写风骨二字，句句有所指，又句句挑不出错。全城传抄，半日就出了城。","options":[{"text":"即刻谱曲,当众首唱","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":2},"feedback":"《霜弦引》一唱，四座动容。词不点名，人人都知道写的是谁的风骨。","source":"宋代以词讽咏见宋人词话所载寄托之体。"},{"text":"压两日再看风向","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"风向是等出来的，可势是做出来的。词热的时候不唱，凉了就白写了。","source":"同上。"}],"difficulty":3,"npc":["落魄词人","掌班"],"foreshadow":"《霜弦引》为反击利器"},{"id":"B-023-未","branch":"B","stage":1,"day":23,"shichen":"未时","checkpoint":"霜弦引·023未","scene":"午后，曾与你较技的那位资深歌伎主动登门，说要在她的席面上也唱《霜弦引》——满楼姐妹，一人一张嘴，替你传词。","options":[{"text":"谢过并把谱抄给她","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"谱子一份份传出去。一日之间，半城歌楼都在唱你的风骨。","source":"《东京梦华录》载汴京诸酒楼伎艺互通之俗。"},{"text":"婉谢怕连累于她","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"她撂下一句「当年较技输你，今日不能输阵」就走了。好意拒人，可惜。","source":"宋人笔记所载歌楼同侪之义。"}],"difficulty":2,"npc":["资深歌伎","樊楼姐妹"],"foreshadow":"半城传唱,权贵投鼠忌器"},{"id":"B-023-戌","branch":"B","stage":1,"day":23,"shichen":"戌时","checkpoint":"霜弦引·023戌","flavor":true,"scene":"夜里，书生捎来字条，只有一句：「词已出城，弦要跟上。」你笑着把字条压在琴下，净手，焚香，调弦。","options":[{"text":"回信:弦已上,请听满城","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"六字回过去，硬气又俏皮。这一夜汴京的弦声，你们俩一人一半。","source":"宋代词简唱酬见宋人词话。"},{"text":"弹《霜弦引》至月落","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"曲子弹了一夜，楼上楼下都静静听着。有些仗，是用琴声打赢的。","source":"《碧鸡漫志》所载以乐言志之习。"}],"difficulty":1,"npc":[],"foreshadow":"满城弦声逼权贵收手"},{"id":"B-024","branch":"B","stage":1,"day":24,"shichen":"辰时","checkpoint":"风向转·024辰","scene":"风向变了。晨起，城中清议之士纷纷为《霜弦引》叫好，有御史台的书吏私下放话：强纳乐籍一事若闹出来，高家脸上须不好看。","options":[{"text":"趁热打铁再唱一场","correct":true,"tags":["名声","才华"],"dims":{"名声":2,"才华":2},"feedback":"再唱一场，座中多了好些青衫士子。风骨二字，算是钉进了汴京人心里。","source":"宋代清议与词场唱和见宋人笔记及词话。"},{"text":"见好就收低调两日","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"低调没错，可势这东西，一松手就凉。掌班替你惋惜：火候正好啊。","source":"宋人笔记所载市井舆论消长之理。"}],"difficulty":3,"npc":["青衫士子","掌班"],"foreshadow":"士子声援为收官铺垫"},{"id":"B-024-未","branch":"B","stage":1,"day":24,"shichen":"未时","checkpoint":"风向转·024未","scene":"午后，高府管家再来，这回没了趾高气扬，只说主人「仰慕姑娘技艺」，愿以厚礼相赠，前事一笔勾销。话软了，意还在。","options":[{"text":"受道歉,礼仍不受","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你说：前事既销，礼便不必。话给足了对方面子，底线一寸没让。","source":"宋代酬答辞受之礼见宋人笔记所载。"},{"text":"收礼息事求个太平","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"礼一收，「一笔勾销」就成了「两相往来」。掌柜的脸色当场就变了。","source":"宋人笔记所载权贵结纳之手段。"}],"difficulty":3,"npc":["权贵管家"],"foreshadow":"权贵初挫,暗线转入下半场"},{"id":"B-024-戌","branch":"B","stage":1,"day":24,"shichen":"戌时","checkpoint":"风向转·024戌","flavor":true,"scene":"夜里难得松快，姐妹们凑了桌小宴给你压惊。酒是淡的，果子是甜的，窗外的雪化了，檐水滴滴答答。","options":[{"text":"敬众姐妹一盏淡酒","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"酒淡情深。你说：这口气，是姐妹们陪着挣回来的。满座红了眼眶。","source":"宋人笔记所载教坊宴集旧俗。"},{"text":"独回房给书生写信","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"信里写：雪化了，檐水很响，像极了那日书肆里你够书的动静。","source":"宋代书简寄情见宋人词话。"}],"difficulty":1,"npc":["樊楼姐妹"],"foreshadow":"檐水之喻呼应州桥初遇"},{"id":"B-025","branch":"B","stage":1,"day":25,"shichen":"辰时","checkpoint":"阶段收官·025辰","scene":"收官之日。晨起，鸨母亲自把赎身文书的底稿摊在你面前：中人已画押，数目已核清，只待官府过印。她问：想好了？","options":[{"text":"稳稳画押,自赎其身","correct":true,"tags":["自主","家世"],"dims":{"自主":3,"家世":2},"feedback":"笔落纸上，手很稳。从及笄那日到今日，你攒的不是钱，是这条命的主权。","source":"宋代乐户自赎脱籍之制见《宋刑统》及宋人笔记。"},{"text":"迟疑片刻再添体己","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"就这一迟疑，鸨母收了文书：再想想吧。门开着，你的脚却软了。","source":"同上。"}],"difficulty":3,"npc":["鸨母"],"foreshadow":"文书待印,下半程开局"},{"id":"B-025-未","branch":"B","stage":1,"day":25,"shichen":"未时","checkpoint":"阶段收官·025未","scene":"午后，樊楼为你办了一场小小的送别弹唱——人不走，身份先走。满楼姐妹都在，连老乐工都换上了干净的袍子。","options":[{"text":"弹最初那支新词作结","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":1},"feedback":"还是那支曲，还是从前的词，弹的人已不是从前的人。满楼泪中带笑。","source":"《东京梦华录》载樊楼笙歌之盛,新声传唱之俗。"},{"text":"弹一支喜庆大曲应景","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"大曲热闹，可总觉得缺了点什么。有些场合，要弹自己的来路。","source":"《碧鸡漫志》所载唐宋大曲名目。"}],"difficulty":2,"npc":["鸨母","老乐工","樊楼姐妹"],"foreshadow":"新词作结呼应立名之夜"},{"id":"B-025-戌","branch":"B","stage":1,"day":25,"shichen":"戌时","checkpoint":"阶段收官·025戌","flavor":true,"scene":"收官之夜，书生来了，带着雪夜你催来的那阕新词——《满州桥雪》。他说：词写完了，路还长。你赎你的身，我写我的词，谁也别停。","options":[{"text":"与他约:脱籍之日首唱此词","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"约定了：官府过印那天，樊楼最后一次点烛，唱《满州桥雪》。灯花轻轻爆了一声。","source":"宋人词话所载词者唱和定约之雅事。"},{"text":"将词稿收进琵琶盒底","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"词稿挨着律条和账册放好。匣子里如今有三样：前程、人心、底气。","source":"宋人笔记所载藏札旧俗。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"《满州桥雪》之约直通part2"},{"id":"B-026","branch":"B","stage":2,"day":26,"shichen":"辰时","checkpoint":"过印首唱·026辰","scene":"收官之约兑现之日。晨起，官府文书铺来话：过印定在午时，印泥一落，你便不再是乐籍。你抱着琵琶走向樊楼，最后一段路，走得很慢。","options":[{"text":"先净手焚香再动身","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"香灰落定，心也落定。这一印，要干干净净去领。","source":"宋人笔记所载脱籍过印前洁身之俗。"},{"text":"兴冲冲直奔文书铺","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"脚步太急，心里发飘。大事当前，先要自己稳得住自己。","source":"同上。"}],"difficulty":2,"npc":["鸨母"],"foreshadow":"过印仪式定下半场基调"},{"id":"B-026-未","branch":"B","stage":2,"day":26,"shichen":"未时","checkpoint":"过印首唱·026未","scene":"午后，印已落，文书入手尚温。樊楼最后一次为你点烛，满座旧客新朋。书生立在廊下，手里是那阕《满州桥雪》。","options":[{"text":"如约首唱《满州桥雪》","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":2},"feedback":"弦起雪落，唱到「霜满州桥」满座无声。这一曲，唱的是你自己的来路。","source":"《东京梦华录》载樊楼笙歌之盛；宋代脱籍谢宴见宋人笔记。"},{"text":"换支喜庆大曲贺新生","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"大曲热闹，书生却悄悄收了词稿。约好的曲子，爽约最伤知音。","source":"《碧鸡漫志》所载唐宋大曲名目。"}],"difficulty":3,"npc":["落魄词人","掌班","樊楼姐妹"],"foreshadow":"首唱之约兑现,信物链延续"},{"id":"B-026-戌","branch":"B","stage":2,"day":26,"shichen":"戌时","checkpoint":"过印首唱·026戌","flavor":true,"scene":"夜散，你与书生并肩走过州桥。雪早化了，桥石被夜市的灯照得发亮。他说：词里那句霜满州桥，今日才算写完。","options":[{"text":"答:霜化了,桥还在","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"桥下水声潺潺。两个人都没再说话，有些话，桥替你们说了。","source":"《东京梦华录》载州桥夜市灯火之盛。"},{"text":"把过印文书给他看","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"他捧着文书看了很久，比你还郑重。你的自由，他当喜事疼。","source":"宋人笔记所载士女同赏文书之雅事。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"州桥夜话定情缘新阶段"},{"id":"B-027","branch":"B","stage":2,"day":27,"shichen":"辰时","checkpoint":"新居·027辰","scene":"脱籍第一晨。你在樊楼住了这些年，如今要搬出去了。房里东西不多：一架琵琶、一只木匣、一册裱好的词稿。","options":[{"text":"三样东西亲自背着走","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"琵琶、钱匣、词稿，一样不让别人沾手。全部家当，都是自己挣的。","source":"宋人笔记所载乐户脱籍迁出旧俗。"},{"text":"托脚夫先运大件","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"脚夫毛手毛脚，琴盒磕了个角。心疼半天——贴身的东西，还是自己来。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"三件家当贯穿后半程"},{"id":"B-027-未","branch":"B","stage":2,"day":27,"shichen":"未时","checkpoint":"新居·027未","scene":"午后赁屋。州桥附近寻到一处小院，房东看你孤身女子，漫天要价，还旁敲侧击打听你的来历。","options":[{"text":"亮出脱籍文书议价","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"文书一亮，来历清清白白，价钱立时落了三成。清白两个字，能当钱使。","source":"宋代城市赁屋立约之俗见《东京梦华录》及宋人笔记。"},{"text":"怕事多付钱求安稳","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"钱是多花了，房东的眼神却更黏糊。你越含糊，别人越敢猜。","source":"同上。"}],"difficulty":2,"npc":["房东"],"foreshadow":"小院为自立根据地"},{"id":"B-027-戌","branch":"B","stage":2,"day":27,"shichen":"戌时","checkpoint":"新居·027戌","flavor":true,"scene":"新居第一夜，屋里还空荡。你把「霜满州桥」的字条贴上墙，琵琶靠墙立好，灯花一爆，竟有了点家的样子。","options":[{"text":"弹一曲安宅","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"弦声在新屋里撞出回声，四壁都是自己的。这回声，比樊楼的好听。","source":"宋人词话所载以乐安处之习。"},{"text":"给娘写信报新址","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"信尾写：女儿如今有自己的门了。写罢吹灯，睡得格外沉。","source":"宋人笔记所载书信托寄之俗。"}],"difficulty":1,"npc":[],"foreshadow":"新居安稳引来旁人侧目"},{"id":"B-028","branch":"B","stage":2,"day":28,"shichen":"辰时","checkpoint":"秘本·028辰","scene":"晨起，生计提上日程。脱籍是自由了，可缠头也断了。你摊开三本账：授艺、弹唱、还是别的营生，得选一条路走。","options":[{"text":"挂牌授琵琶兼应清唱","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"牌子挂出：授艺收钱，清唱看眼缘。技艺在身，走到哪都是饭碗。","source":"宋代民间乐人授艺营生见宋人笔记所载。"},{"text":"先吃老本再慢慢想","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"老本吃得人心慌。自由是好，可自由不养闲人，账上的数天天在瘦。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"授艺挂牌开启新营生线"},{"id":"B-028-未","branch":"B","stage":2,"day":28,"shichen":"未时","checkpoint":"秘本·028未","scene":"午后，老乐工登门贺你乔迁，带的礼是一册手抄的旧谱——教坊里传了几代的指法秘本，他说：给你，比烂在我手里强。","options":[{"text":"拜受秘本,执弟子礼","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"你郑重下拜。秘本里夹着他一生的批注，这是把半辈子的饭端给了你。","source":"唐宋乐谱私相传授见《乐府杂录》及宋人笔记。"},{"text":"推说无功不敢受禄","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老乐工叹着气把谱收回一半：只给你抄三页。客气用错地方，就是生分。","source":"同上。"}],"difficulty":2,"npc":["老乐工"],"foreshadow":"秘本批注为技艺再进阶"},{"id":"B-028-戌","branch":"B","stage":2,"day":28,"shichen":"戌时","checkpoint":"秘本·028戌","flavor":true,"scene":"夜里试读秘本，有一处古指法怎么也弹不顺。你想起白日书生说要去应漕试的闲话，忽然觉得，你们俩都在啃各自的硬骨头。","options":[{"text":"把难处记在谱边","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"难处记下，明日再磨。好手艺都是跟难题死磕出来的。","source":"宋代乐工习艺口诀见宋人笔记。"},{"text":"写信问他备考如何","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"信里不问功名，只问「砚可还暖」。他回了三个字：「弦可还顺？」","source":"宋代书简往来见宋人笔记所载。"}],"difficulty":1,"npc":[],"foreshadow":"漕试备考为书生个人线"},{"id":"B-029","branch":"B","stage":2,"day":29,"shichen":"辰时","checkpoint":"索贿·029辰","scene":"暗手动了。晨起，乐籍司一个小吏登门，皮笑肉不笑地说你的脱籍文书「手续存疑」，要你「补些规矩」——手一伸，意思很明白。","options":[{"text":"请其指明律条依据","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你搬出抄熟的律条逐条对，小吏支吾半天，灰溜溜走了。懂法的人不好敲。","source":"宋代乐户脱籍程序见《宋刑统》及宋人笔记所载吏治旧例。"},{"text":"塞钱了事息事宁人","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"钱塞出去，胃口就喂大了。三日后他又来了，这回要得更多。","source":"宋人笔记所载胥吏索贿之习。"}],"difficulty":3,"npc":["乐籍司小吏"],"foreshadow":"小吏背后是高家的手"},{"id":"B-029-未","branch":"B","stage":2,"day":29,"shichen":"未时","checkpoint":"索贿·029未","scene":"午后你留了心，托还账姐妹打听那小吏的底。消息回来：他新近手头阔绰，常出入高府后门。线头，对上了。","options":[{"text":"记下往来时日存证","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"时日、证人、话头，一一入册。对付暗手，最好的武器是白纸黑字。","source":"宋人笔记所载存证质对之俗。"},{"text":"怒冲冲去找他对质","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"对质没有凭据，反被他倒打一耙说你污蔑公人。气头上的棋，都是臭棋。","source":"宋人笔记所载胥吏反噬之例。"}],"difficulty":3,"npc":["还账姐妹","乐籍司小吏"],"foreshadow":"存证册为反击高家武器"},{"id":"B-029-戌","branch":"B","stage":2,"day":29,"shichen":"戌时","checkpoint":"索贿·029戌","flavor":true,"scene":"夜里，资深歌伎——如今该叫她姐姐了——提着一坛酒来看你。她说：出了乐籍，仗才刚开始，姐姐陪你打。","options":[{"text":"与她煮酒论对策","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"酒不深，计很深。她这些年攒下的人脉，比你想的厚得多。","source":"宋人笔记所载教坊旧人相扶之俗。"},{"text":"先敬她三盏谢旧恩","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"三盏酒，从较技唱到并肩。楼里结下的情分，出了楼更结实。","source":"同上。"}],"difficulty":1,"npc":["资深歌伎"],"foreshadow":"姐姐人脉网后文大用"},{"id":"B-030","branch":"B","stage":2,"day":30,"shichen":"辰时","checkpoint":"自赎冲刺·030辰","scene":"冲刺日。晨起你把三本账摊在桌上最后清算：赎金簿已结清，日用簿尚有余，应急簿原封未动。缠头积蓄，一文一文，干干净净。","options":[{"text":"三本合一立总账","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"总账一成，来路去向一目了然。这本账，往后谁查都不怕。","source":"宋代市井记账之习见宋人笔记。"},{"text":"账清了便烧了旧簿","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"火一点你就后悔了——谣言正愁没处钻，账簿是你最硬的盾。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"总账为后文自证关键"},{"id":"B-030-未","branch":"B","stage":2,"day":30,"shichen":"未时","checkpoint":"自赎冲刺·030未","scene":"午后，中人鸨母来做最后的交割确认。她翻着你的总账，忽然说：当年我以为你攒钱是心高，如今看，是心正。","options":[{"text":"谢她当年不亏之恩","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一揖到底。鸨母扶起你：往后你不是樊楼的人，是樊楼的体面。","source":"宋人笔记所载脱籍中保交割旧例。"},{"text":"淡淡交割不多言语","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"交割是完了，可多年的情分只落了个「淡」字。有些谢，说出口才算数。","source":"同上。"}],"difficulty":2,"npc":["鸨母"],"foreshadow":"鸨母之言为樊楼后援伏笔"},{"id":"B-030-戌","branch":"B","stage":2,"day":30,"shichen":"戌时","checkpoint":"自赎冲刺·030戌","flavor":true,"scene":"夜里，书生送来一阕小词贺你账册交割，题为《算来清白》。他说这是写过最难的一阕——数目字入词，比写雪难多了。","options":[{"text":"笑谱此词唱给他听","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"「一贯两贯」唱出来竟意外地好听。你俩笑作一团，像两个小孩。","source":"宋人词话所载以日常语入词之趣。"},{"text":"把词贴在总账扉页","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"账册第一页，不谈钱，谈清白。往后翻账的人，先看见的是人心。","source":"宋人笔记所载题句于册之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"《算来清白》为账册题签"},{"id":"B-031","branch":"B","stage":2,"day":31,"shichen":"辰时","checkpoint":"状纸·031辰","scene":"晨起，文书铺传来坏消息：你的脱籍正本被乐籍司压下了，理由含糊——「年份存疑，待查」。印都过了，正本却迟迟不发。","options":[{"text":"携律条抄本登门问期","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你把律条和过印回执摊在柜上：敢问疑在何条？书吏眼神躲闪，答不上来。","source":"宋代文书申诉程序见《宋刑统》及宋人笔记所载吏治旧例。"},{"text":"回家干等官府消息","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"等了三日，音讯全无。官府的「待查」两个字，能拖到地老天荒。","source":"宋人笔记所载胥吏延宕之习。"}],"difficulty":3,"npc":["乐籍司书吏"],"foreshadow":"正本被压,高家第二手"},{"id":"B-031-未","branch":"B","stage":2,"day":31,"shichen":"未时","checkpoint":"状纸·031未","scene":"午后，书生闻讯赶来，说他可以帮你写状纸催办——他熟条文，更熟这些胥吏怕什么。","options":[{"text":"与他共拟催办状纸","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"他执笔你核条，状纸写得绵里藏针。这一状递上去，吏员夜里要睡不着了。","source":"宋代民事状纸格式见宋人笔记所载词讼旧例。"},{"text":"怕牵连他功名推辞","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"书生把笔一放：你的事就是我的事，再说就生分了。你推掉的是援手。","source":"宋人词话所载士人任侠之习。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"联名状纸震动乐籍司"},{"id":"B-031-戌","branch":"B","stage":2,"day":31,"shichen":"戌时","checkpoint":"状纸·031戌","flavor":true,"scene":"夜里状纸拟好，书生临走从袖中摸出一方旧墨——正是当年你赠帕包过的那一方。他说：用你送的墨写你的状，才算物归原用。","options":[{"text":"亲手为他研这一方墨","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"墨香慢慢晕开，像这些年的来往。旧帕包过的墨，写今日的状，正好。","source":"宋代文房赠答之雅见宋人笔记。"},{"text":"将墨与词稿并藏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"墨收在词稿旁边。信物不多，就这几样，样样都长在日子里。","source":"宋人笔记所载藏札之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"旧墨写状,信物再激活"},{"id":"B-032","branch":"B","stage":2,"day":32,"shichen":"辰时","checkpoint":"清议·032辰","scene":"晨起递状。状纸递进乐籍司，不到半日，压着的正本有了动静——书吏亲自来传话：三日后发还。态度恭敬得判若两人。","options":[{"text":"记下书吏前后嘴脸","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"小册上又添一笔。不是记仇，是记世情：软的怕硬的，硬的怕懂法的。","source":"宋人笔记所载胥吏前倨后恭之态。"},{"text":"得理不饶人斥其索贿","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"骂是骂痛快了，可索贿无凭据，反落个咆哮公门的口实。赢了理，别输了分寸。","source":"宋人笔记所载词讼分寸。"}],"difficulty":2,"npc":["乐籍司书吏"],"foreshadow":"书吏记名,后文质证之用"},{"id":"B-032-未","branch":"B","stage":2,"day":32,"shichen":"未时","checkpoint":"清议·032未","scene":"午后，资深歌伎姐姐带来好消息：她辗转托上了御史台一位以清直闻名的士人，那人听闻《霜弦引》之事，愿见你一面，听你当面陈情。","options":[{"text":"备齐律条账册往见","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"士人看你账册井然、律条娴熟，慨然道：清议当为清白人张目。","source":"宋代御史风闻言事与清议之俗见宋人笔记。"},{"text":"空手赴约只凭口才","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"士人客气地听完，客气地送客。空口说清白，分量终究轻了些。","source":"同上。"}],"difficulty":3,"npc":["资深歌伎","清直士人"],"foreshadow":"清议背书为制胜一手"},{"id":"B-032-戌","branch":"B","stage":2,"day":32,"shichen":"戌时","checkpoint":"清议·032戌","flavor":true,"scene":"夜里，你把白日士人的话学给书生听。他听完笑道：你看，你的词是我写的，你的清白是自己挣的——咱们各出一半。","options":[{"text":"答:词也有一半是我的弦","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"灯下争功，争着争着都笑了。好的相知，就是功劳簿上不分彼此。","source":"宋人词话所载唱和相得之乐。"},{"text":"煮茶谢他连日奔走","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"粗茶两盏，喝到夜深。他走时靴子上都是霜，你没说破，心里记着。","source":"宋人笔记所载冬夜煎茶之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"各出一半之语暗合结局"},{"id":"B-033","branch":"B","stage":2,"day":33,"shichen":"辰时","checkpoint":"谣言起·033辰","scene":"正本发还之日将近，风向却再变。晨起，瓦子里新起一种谣言：说你的赎金来路不明，是「贵人的私房钱」，暗指你早被高家包下。","options":[{"text":"不动声色先查源头","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你托姐妹们分头听，三日内谣言的线头一路摸回高府门客。蛇出洞了。","source":"宋人笔记所载市井流言传播之态。"},{"text":"逢人便辩赌咒自证","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"越辩越像掩饰。谣言这东西，你追它就跑，你堵它就涨。","source":"同上。"}],"difficulty":3,"npc":["高府门客"],"foreshadow":"谣言源头直指高家"},{"id":"B-033-未","branch":"B","stage":2,"day":33,"shichen":"未时","checkpoint":"谣言起·033未","scene":"午后，谣言伤到了生计：两个来学琵琶的女学生家退了帖，说「等风头清清再来」。小院的门，一下子冷清了。","options":[{"text":"照常挂牌,弦声不断","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"学生走了，弦声没停。路人日日听得琴声如常，谣言先自矮了半截。","source":"宋人笔记所载市井观望之俗。"},{"text":"摘牌闭门暂避风头","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"门一关，倒像坐实了心虚。你越躲，看热闹的越觉得自己猜对了。","source":"同上。"}],"difficulty":2,"npc":["退学学生家属"],"foreshadow":"退帖学生后文归来"},{"id":"B-033-戌","branch":"B","stage":2,"day":33,"shichen":"戌时","checkpoint":"谣言起·033戌","flavor":true,"scene":"夜里，樊楼旧姐妹结伴来看你，带的不是安慰，是情报：哪家瓦子谁起的头、哪座茶肆谁传的话，拼凑出一张完整的谣言路线图。","options":[{"text":"绘图存证谢过姐妹","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"路线图一画，百口莫辩的脏水成了有据可查的案。姐妹们，是你的耳目。","source":"宋人笔记所载记事存证之俗。"},{"text":"留姐妹们小酌叙旧","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"酒喝到最后，有人哼起旧年的曲子。出了乐籍，情分没出籍。","source":"同上。"}],"difficulty":1,"npc":["樊楼姐妹"],"foreshadow":"谣言路线图为质证利器"},{"id":"B-034","branch":"B","stage":2,"day":34,"shichen":"辰时","checkpoint":"备证·034辰","scene":"晨起，书生带着新词来了，词牌《定风波》。他说：东坡先生写过「谁怕」，今日这阕，写给所有泼向女子的脏水。","options":[{"text":"郑重谱曲备日后之用","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":1},"feedback":"谱到「谁怕」二字，弦声陡然一振。好词配硬弦，这首歌是要打出去响的。","source":"宋人词话所载以词自明心迹之体。"},{"text":"劝他勿再卷入是非","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"书生把词稿压在你琴下：我的词早就站在你这边了，收不回去了。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"《定风波》为舆论决战曲"},{"id":"B-034-未","branch":"B","stage":2,"day":34,"shichen":"未时","checkpoint":"备证·034未","scene":"午后，御史台那位清直士人遣人传话：他已风闻乐籍司胥吏与谣言之事，请你备好证据——账册、律条抄本、谣言路线图，三日后当面对质。","options":[{"text":"三日不眠备齐三证","correct":true,"tags":["自主"],"dims":{"自主":3},"feedback":"账册编号、律条标签、路线图注证人。三日灯下，备的是一场堂堂之阵。","source":"宋代对质质证之俗见宋人笔记所载词讼旧例。"},{"text":"只带账册仓促应约","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"账册虽好，孤证难立。备料不足就上席，是对自己这半年辛苦的不敬。","source":"同上。"}],"difficulty":3,"npc":["清直士人"],"foreshadow":"三证齐备直指对质"},{"id":"B-034-戌","branch":"B","stage":2,"day":34,"shichen":"戌时","checkpoint":"备证·034戌","flavor":true,"scene":"备证第二夜，你熬得眼睛发涩。门外忽然有动静——是书生，抱着一摞他替你抄好的律条副本，说：你管账册，副本我来。","options":[{"text":"分灯共抄至天微明","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"一盏灯分成两桌，抄到鸡叫。这世上的并肩，多半是熬出来的。","source":"宋人笔记所载寒夜抄书之习。"},{"text":"劝他回去备考要紧","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他不肯走，说你的对质日就是他备考的休沐日。你拗不过，只好分他一半灯。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"分灯抄书为情缘高光"},{"id":"B-035","branch":"B","stage":2,"day":35,"shichen":"辰时","checkpoint":"乐籍刁难·035辰","scene":"对质日。乐籍司厅堂森然，小吏与书吏俱在，高府门客躲在屏风后。清直士人升座，请你先陈。满堂的目光落在你怀中的账册上。","options":[{"text":"呈三证,逐条自陈","correct":true,"tags":["自主","名声"],"dims":{"自主":3,"名声":2},"feedback":"账册对律条，路线图对人证。小吏面如死灰，屏风后的人悄悄退了。","source":"宋代词讼对质程序见《宋刑统》及宋人笔记。"},{"text":"先哭诉委屈再呈证","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"眼泪换不来公道，只会让人先看轻三分。堂上要的从来不是苦情，是证据。","source":"宋人笔记所载堂质之戒。"}],"difficulty":3,"npc":["清直士人","乐籍司小吏","高府门客"],"foreshadow":"对质大胜,高家断一臂"},{"id":"B-035-未","branch":"B","stage":2,"day":35,"shichen":"未时","checkpoint":"乐籍刁难·035未","scene":"午后堂散，处置下来：小吏夺俸问罪，压案书吏记过，你的脱籍正本当场发还，再无人敢说半个「疑」字。","options":[{"text":"当堂核验文书无误","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":2},"feedback":"印、押、年月，逐处验过。这纸文书上的每一个字，都是你自己挣来的。","source":"宋代官文书核验之俗见宋人笔记。"},{"text":"欣喜过望收文即走","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"出了衙门才发现副本未领。大热闹里最容易丢的，往往是小东西。","source":"同上。"}],"difficulty":3,"npc":["清直士人","乐籍司书吏"],"foreshadow":"正本到手,身份尘埃落定"},{"id":"B-035-戌","branch":"B","stage":2,"day":35,"shichen":"戌时","checkpoint":"乐籍刁难·035戌","flavor":true,"scene":"夜里，消息传遍，资深歌伎姐姐第一个砸门来贺，后头跟着还账姐妹、老乐工，挤了一院子。你下厨煮了一锅热汤饼。","options":[{"text":"与众人分食汤饼","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"一锅汤饼，众人分食，吃出了团圆的味道。你的胜，是一群人的胜。","source":"《东京梦华录》载汴京汤饼食俗。"},{"text":"弹《定风波》谢众人","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"「谁怕」二字出口，满院喝彩。这一曲，从此是你们这群人的歌。","source":"宋人词话所载以词明志之体。"}],"difficulty":1,"npc":["资深歌伎","还账姐妹","老乐工"],"foreshadow":"小院夜聚,班底成型"},{"id":"B-036","branch":"B","stage":2,"day":36,"shichen":"辰时","checkpoint":"户版·036辰","scene":"晨起，脱籍正本配上户版，你在汴京的户籍册上终于有了自己的一页。户吏盖章时说：姑娘这样的，本司一年也见不着一个。","options":[{"text":"收好户版谢过户吏","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"户版入手，薄薄一片，压得住半生。从今往后，你是汴京城堂堂正正的人。","source":"宋代户籍制度见《宋史·食货志》及宋人笔记所载。"},{"text":"得意忘形少了礼数","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"户吏撇了撇嘴。越是高处的日子，越要记得低处的礼数。","source":"同上。"}],"difficulty":2,"npc":["户吏"],"foreshadow":"户版落定,家世维度新生"},{"id":"B-036-未","branch":"B","stage":2,"day":36,"shichen":"未时","checkpoint":"户版·036未","scene":"午后，退帖的两个女学生家红着脸回来了，说眼见姑娘堂上自证清白，先前是听信谣言，愿双倍束脩复课。","options":[{"text":"按原价收,不究前事","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"原价复课，只多一句：往后听曲先看人。家长愧服，逢人便夸你的器量。","source":"宋人笔记所载市井师徒束脩之俗。"},{"text":"收双倍束脩作教训","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"钱是多收了，话也传出去了：这姑娘记仇。器量二字，比束脩值钱。","source":"同上。"}],"difficulty":2,"npc":["退学学生家属"],"foreshadow":"复课学生为授艺线开端"},{"id":"B-036-戌","branch":"B","stage":2,"day":36,"shichen":"戌时","checkpoint":"户版·036戌","flavor":true,"scene":"夜里，你把户版放进木匣最底层，和那支及笄的素银簪放在一起。两样东西，一头一尾，恰好是这些年的全部路程。","options":[{"text":"抚簪回想及笄那日","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"簪子还是那支簪子，人不是那个人了。匣子里装的，全是自己来路的碑。","source":"宋人笔记所载及笄遗俗。"},{"text":"写信告诉娘户版事","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"信里写：娘，女儿的名字，如今干干净净写在官府的册子上。","source":"宋人笔记所载书信托寄之俗。"}],"difficulty":1,"npc":[],"foreshadow":"木匣信物集齐,家世闭环"},{"id":"B-037","branch":"B","stage":2,"day":37,"shichen":"辰时","checkpoint":"弦正匾·037辰","scene":"晨起，高府又来人了。这回管家换了副嘴脸，说主人愿「捐资助姑娘开馆授艺」，只求姑娘在士人面前替高家说句话，把旧怨抹平。","options":[{"text":"拒捐助:旧怨自会随水","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你答：怨不怨的，是非公论自在人心，奴家的嘴不卖。管家悻悻而去。","source":"宋人笔记所载权贵弥缝旧怨之手段。"},{"text":"收下捐助各取所需","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"银子一进院，「被包下」的谣言就活了。他买的不是和解，是你的嘴。","source":"同上。"}],"difficulty":3,"npc":["权贵管家"],"foreshadow":"高家求和不成,余恨未消"},{"id":"B-037-未","branch":"B","stage":2,"day":37,"shichen":"未时","checkpoint":"弦正匾·037未","scene":"午后，清直士人听闻高家求和之事，遣人送话来：姑娘若开馆授艺，他愿题匾相赠——「弦正」二字，替你镇一镇汴京的耳朵。","options":[{"text":"拜谢受匾,悬于馆门","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「弦正」二字挂上门楣，清议的背书比千金重。高家的人再没来烦过。","source":"宋代士人题赠之雅见宋人笔记所载。"},{"text":"谦辞不敢当此二字","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"辞是谦逊，可清议递来的梯子不接，往后高家的脏水还会试着泼。","source":"同上。"}],"difficulty":2,"npc":["清直士人"],"foreshadow":"「弦正」匾为名声巅峰"},{"id":"B-037-戌","branch":"B","stage":2,"day":37,"shichen":"戌时","checkpoint":"弦正匾·037戌","flavor":true,"scene":"夜里匾挂上墙，你立在门口看了许久。书生来时，带了一小坛酒，说要贺「弦正馆」开张，酒是赊的，贺是真的。","options":[{"text":"笑纳赊酒,以曲相抵","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"一曲抵一坛，谁也不欠谁。账算得越糊涂，情分算得越明白。","source":"宋人笔记所载市井赊酒之俗。"},{"text":"替他把酒账结了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你悄悄结了他的酒账，他知道了佯装生气。清贫里的体面，要互相成全。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"弦正馆开张为新篇章"},{"id":"B-038","branch":"B","stage":2,"day":38,"shichen":"辰时","checkpoint":"开馆·038辰","scene":"弦正馆挂牌第一日。晨起洒扫，门刚开，外头已候着七八个学生——有瓦子里的小乐伎，也有清白人家送来学礼乐的女儿。","options":[{"text":"立馆规:先学德后学技","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"馆规三条：守时、敬艺、自重。学生记下，家长放心，弦正馆立住了。","source":"宋代民间塾学馆规之俗见宋人笔记。"},{"text":"来者不拒先收束脩","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"人收杂了，规矩松了，不出半月馆内起了口角。摊子易支，招牌难立。","source":"同上。"}],"difficulty":2,"npc":["弦正馆学生"],"foreshadow":"馆规三条为授艺线根基"},{"id":"B-038-未","branch":"B","stage":2,"day":38,"shichen":"未时","checkpoint":"开馆·038未","scene":"午后授课，一个瓦子来的小乐伎天资极好却自卑畏缩，说自己「出身贱，配不上好曲子」。你放下琵琶看着她。","options":[{"text":"以己身经历勉励她","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你说：曲不问出身，弦只认功夫。小姑娘眼里的光，一点点亮回来了。","source":"宋人笔记所载乐人传艺之事。"},{"text":"只管指法不管心事","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"指法教得再好，她心里的弯没转过来，弹出来的曲子始终矮着半头。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"小乐伎为传承线人物"},{"id":"B-038-戌","branch":"B","stage":2,"day":38,"shichen":"戌时","checkpoint":"开馆·038戌","flavor":true,"scene":"夜里备课，你翻出老乐工赠的秘本，对照自己这些年的小谱，把两处指法的体会写在馆用教材上，一笔一笔，写到夜深。","options":[{"text":"编一本弦正馆指法谱","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"秘本为骨，心得为肉。这本谱往后会传下去，比名声活得久。","source":"唐宋乐谱传习见《乐府杂录》及宋人笔记。"},{"text":"在谱首题「技艺立身」","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"四个字落在谱首。你这一生没别的诀窍，就这四个字，传给学生。","source":"宋人笔记所载题识之习。"}],"difficulty":1,"npc":[],"foreshadow":"指法谱为技艺传承信物"},{"id":"B-039","branch":"B","stage":2,"day":39,"shichen":"辰时","checkpoint":"备考·039辰","scene":"晨起，书生的漕试近了。他这几日一面温书一面还替你抄馆用谱，眼底乌青。你看着他，心里有了计较。","options":[{"text":"接回抄谱让他专心","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你把谱稿全抱回来：你的战场在考场，我的在弦上。他红了脸，拱手谢了。","source":"宋代漕试备考见宋人笔记所载科举旧俗。"},{"text":"由他帮忙不忍拒绝","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他累得写字手抖。爱一个人不是用一个人，这个理你懂，就是心软。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"漕试临近,情缘线分叉口"},{"id":"B-039-未","branch":"B","stage":2,"day":39,"shichen":"未时","checkpoint":"备考·039未","scene":"午后你去书肆，悄悄替他采买了一应考具：新笔、好墨、一方压纸的镇石。掌柜的笑问：姑娘这是替谁张罗的？","options":[{"text":"笑而不答付钱即走","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"考具包好，你只留了张字条：笔是新的，文章是你的。掌柜的笑得意味深长。","source":"宋代科举考具之俗见宋人笔记所载。"},{"text":"坦然说是替故人备","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"答得大方，掌柜反而赞了句「难得」。汴京城里，磊落比什么都体面。","source":"同上。"}],"difficulty":1,"npc":["书肆掌柜"],"foreshadow":"考具赠礼,呼应旧墨信物","flavor":true},{"id":"B-039-戌","branch":"B","stage":2,"day":39,"shichen":"戌时","checkpoint":"备考·039戌","flavor":true,"scene":"夜里你弹《满州桥雪》自娱，弹到一半停了。你想，若他此试得中，往后一个在官途，一个在馆中，这曲子还能不能这样唱。","options":[{"text":"把忧虑写进日记小册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"写下来，心就轻了些。往后的路往后走，今夜的弦只管今夜的音。","source":"宋人笔记所载记事册之习。"},{"text":"弹毕收琴不再多想","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"曲终收拨。你这一生最会的，就是把该弹的弹好，把该放的放下。","source":"宋人词话所载以乐遣怀之习。"}],"difficulty":1,"npc":[],"foreshadow":"得中之虑为part3情缘考验"},{"id":"B-040","branch":"B","stage":2,"day":40,"shichen":"辰时","checkpoint":"谣言反噬·040辰","scene":"收官战。晨起，瓦子里爆出大新闻：当日造谣的高府门客被人拿住了——他酒后与人夸口如何奉命构陷你，满座皆闻，人证一堆。","options":[{"text":"将人证线索呈送御史","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":2},"feedback":"线索整理成册呈上去，清议哗然。谣言的刀，终于转回去抵住造谣的人。","source":"宋代风闻言事与诬告之罪见《宋刑统》及宋人笔记。"},{"text":"亲自去瓦子揭穿他","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你一去，好好的人证局面搅成了泼妇骂街。正义要交给能办它的地方。","source":"宋人笔记所载瓦子争讼之失。"}],"difficulty":3,"npc":["高府门客","清直士人"],"foreshadow":"门客落网,高家断尾"},{"id":"B-040-未","branch":"B","stage":2,"day":40,"shichen":"未时","checkpoint":"谣言反噬·040未","scene":"午后，处置传闻甚快：门客逐出高府，高家闭门谢客。当年放话「谁请你就是与高家过不去」的话，如今成了汴京的笑柄。","options":[{"text":"对笑谈只淡淡一笑","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你不踩落水之人，只在馆里照常授课。这一份不动声色的体面，满城敬服。","source":"宋人笔记所载市井口碑消长之理。"},{"text":"逢人便说高家旧事","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"说多了，听的人心里起腻：得胜者聒噪，比失败者难看。分寸一失，口碑就损。","source":"同上。"}],"difficulty":2,"npc":["高府门客"],"foreshadow":"高家气焰尽挫"},{"id":"B-040-戌","branch":"B","stage":2,"day":40,"shichen":"戌时","checkpoint":"谣言反噬·040戌","flavor":true,"scene":"夜里，资深歌伎姐姐携酒来贺。她说当年较技输你不服，如今服了——不是服你的琵琶，是服你这一身摔不碎的骨头。","options":[{"text":"与她再弹当年较技曲","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"旧曲重弹，两人轮弦，弹到妙处相视大笑。输赢早忘了，曲子还活着。","source":"《东京梦华录》载京瓦伎艺斗巧之俗。"},{"text":"敬她一盏谢多年扶持","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"一盏酒敬得郑重。她笑骂你酸，眼眶却红了。有些谢，再晚说都不算晚。","source":"宋人笔记所载同侪宴集之俗。"}],"difficulty":1,"npc":["资深歌伎"],"foreshadow":"姐姐归心,人脉线圆满"},{"id":"B-041","branch":"B","stage":2,"day":41,"shichen":"辰时","checkpoint":"定额·041辰","scene":"晨起，弦正馆的门槛快被踏破了——自谣言反噬后，满城皆知你的清白与琵琶，投帖求学的排到巷口。","options":[{"text":"定额收徒,宁精勿滥","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"名额定十二人，多一个不收。帖子越难求，弦正馆的招牌越亮。","source":"宋代民间塾学收徒之俗见宋人笔记。"},{"text":"广收门徒趁热扩张","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"人一多，教不过来，弦声都毛了。招牌立起来难，砸起来只要一季。","source":"同上。"}],"difficulty":2,"npc":["求学者"],"foreshadow":"十二弟子为传承班底"},{"id":"B-041-未","branch":"B","stage":2,"day":41,"shichen":"未时","checkpoint":"定额·041未","scene":"午后，有富商遣人送重礼，想捐个「名誉馆主」的名分，条件是他家女儿免试入学、结业时弦正馆出具「第一」的评语。","options":[{"text":"退礼:弦正馆无第一可卖","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"礼单原样退回，附一句话：技艺面前，贫富同弦。这话传出去，求学帖更多了。","source":"宋人笔记所载市井师德之评。"},{"text":"收礼徇私卖出评语","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"银子进柜那日，小乐伎看你的眼神暗了暗。「弦正」两个字，裂了道缝。","source":"同上。"}],"difficulty":3,"npc":["富商仆从"],"foreshadow":"拒贿立信,呼应拒高家"},{"id":"B-041-戌","branch":"B","stage":2,"day":41,"shichen":"戌时","checkpoint":"定额·041戌","flavor":true,"scene":"夜里，书生进场前最后一晚，来你院中坐了坐。两人没说考场的事，只把那阕《算来清白》又唱了一遍，唱得歪歪扭扭，笑作一团。","options":[{"text":"唱毕祝他笔下生风","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他起身告辞，背影挺得笔直。你立在门口看他走远，像送一支出鞘的剑。","source":"宋代科举送考之俗见宋人笔记。"},{"text":"塞给他一包干粮","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"干粮包里卧着一张小字条：「弦正等你」。他揣进怀里，没敢回头。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"书生进场,情缘线悬置待发"},{"id":"B-042","branch":"B","stage":2,"day":42,"shichen":"辰时","checkpoint":"雅集约·042辰","scene":"晨起授课，小乐伎忽然在转调处弹出了秘本上最难的那一式，满室皆惊。她自己也愣住了，抱着琵琶不敢置信。","options":[{"text":"让她当众再弹三遍","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"一遍生，两遍熟，三遍满堂彩。你看着她，像看见当年樊楼帘后的自己。","source":"唐宋琵琶指法传习见《乐府杂录》。"},{"text":"淡然夸两句继续授课","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"话到嘴边只成了「尚可」。她眼里的光暗了半分——关键处的肯定，最省不得。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"弟子成才,技艺有继"},{"id":"B-042-未","branch":"B","stage":2,"day":42,"shichen":"未时","checkpoint":"雅集约·042未","scene":"午后，樊楼掌班来访，说楼中愿与弦正馆结个「雅集之约」：每月你的弟子可登樊楼之台试演，樊楼不取分文，只认技艺。","options":[{"text":"应约,定下试演章程","correct":true,"tags":["名声","才华"],"dims":{"名声":2,"才华":1},"feedback":"章程立得明白：台上凭本事，台下无干谒。旧东家与新馆，就此两相成全。","source":"《东京梦华录》载樊楼之盛与伎艺献演之俗。"},{"text":"婉拒怕学生学坏","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"掌班讪讪而去。樊楼的台子你站过，清白在心不在地——这梯子不该拆。","source":"同上。"}],"difficulty":2,"npc":["掌班"],"foreshadow":"雅集之约为弟子铺路"},{"id":"B-042-戌","branch":"B","stage":2,"day":42,"shichen":"戌时","checkpoint":"雅集约·042戌","flavor":true,"scene":"夜里你整理雅集章程，想起自己当年在樊楼帘后调弦的那个黄昏。从帘后到馆主，这条路你走了太久，也走得太直。","options":[{"text":"把章程抄赠鸨母一册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"鸨母收到章程，回了四个字：「楼里之光」。旧地旧人，都有了体面的收场。","source":"宋人笔记所载乐户旧主之谊。"},{"text":"独坐廊下听夜市声","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"州桥方向的喧闹隐隐传来。当年隔着一条街听热闹的人，如今立在热闹中央。","source":"《东京梦华录》载州桥夜市之盛。"}],"difficulty":1,"npc":[],"foreshadow":"回望樊楼为收官情绪铺垫"},{"id":"B-043","branch":"B","stage":2,"day":43,"shichen":"辰时","checkpoint":"放榜·043辰","scene":"晨起，漕试放榜前的汴京人心浮动。你照常授课，可学生弹错音时你走神了三次——小乐伎抿嘴笑你：先生今日心里有事。","options":[{"text":"坦然认下,照常把课上好","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你说：先生等的不是榜，是心安。课上得一丝不苟，学生们反倒更敬你。","source":"宋人笔记所载放榜前后士庶百态。"},{"text":"停课半日去打听榜讯","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"榜还没放，满城都是假消息。你白跑了半日，回来面对一屋子空等的学生。","source":"同上。"}],"difficulty":2,"npc":["弦正馆学生"],"foreshadow":"放榜在即,情缘线悬顶"},{"id":"B-043-未","branch":"B","stage":2,"day":43,"shichen":"未时","checkpoint":"放榜·043未","scene":"午后榜文出，书肆掌柜亲自跑来报信：你家那位，中了！虽然名次不高，可解送进京的文书上，有了他的名字。","options":[{"text":"先贺书肆再备贺礼","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你贺礼备得朴素：一方新砚，附字「磨墨如磨志」。掌柜的替你跑断了腿也乐意。","source":"宋代解试及第贺仪见宋人笔记所载。"},{"text":"喜极之下乱了方寸","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你在院里转了三圈不知先做什么。欢喜是真的，可欢喜也要有个章法。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜"],"foreshadow":"书生得中,身份差距浮现"},{"id":"B-043-戌","branch":"B","stage":2,"day":43,"shichen":"戌时","checkpoint":"放榜·043戌","flavor":true,"scene":"夜里书生来了，一身洗旧的青衫还是那身青衫，可眉眼间的郁气散了。他站在院门口，第一句话是：我中了。第二句：词我还写。","options":[{"text":"答:弦也还弹","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"四个字对四个字，像当年「曲待词新」。院中月光正好，谁也没提往后。","source":"宋人词话所载唱酬对答之雅。"},{"text":"设薄酌为他贺喜","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"酒还是赊的那坛剩下的。他说这酒比琼林宴的好喝，你笑他穷讲究。","source":"宋人笔记所载及第宴贺之俗。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「词还写弦还弹」为part3盟约"},{"id":"B-044","branch":"B","stage":2,"day":44,"shichen":"辰时","checkpoint":"物议·044辰","scene":"晨起，新的风声来了：书生得中后，有同年讥讽他「与乐籍女子往来」，劝他为官途计，早作切割。这话辗转传到你耳中。","options":[{"text":"静观其行,不乱己心","correct":true,"tags":["自主","情缘"],"dims":{"自主":2,"情缘":1},"feedback":"你不问、不闹、不试探。人心要看他怎么做，不是看别人怎么说。","source":"宋人笔记所载士人交游物议之俗。"},{"text":"主动疏远以全其前程","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"你三日不应他的约。第四日他立在馆门外，淋着雨，不走。","source":"同上。"}],"difficulty":3,"npc":["书生同年"],"foreshadow":"物议为情缘最大考验"},{"id":"B-044-未","branch":"B","stage":2,"day":44,"shichen":"未时","checkpoint":"物议·044未","scene":"午后，书生当众来了弦正馆——携着他的同年们，每人赠了一册他新刊的词集，扉页明明白白写着：「词因樊楼弦上活」。","options":[{"text":"当众谢过,坦然受书","correct":true,"tags":["情缘","名声","感情"],"dims":{"情缘":2,"名声":1},"feedback":"他把物议摊在太阳底下：这就是我的来路。同年们讪讪的，倒敬他三分磊落。","source":"宋人词话所载词人自题本事之习。"},{"text":"避入内室不肯露面","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你躲了，他一个人撑完了全场。夜里他留书：你退半步，我便要进两步。","source":"同上。"}],"difficulty":3,"npc":["落魄词人","书生同年"],"foreshadow":"当众认账,物议反转"},{"id":"B-044-戌","branch":"B","stage":2,"day":44,"shichen":"戌时","checkpoint":"物议·044戌","flavor":true,"scene":"夜里你摩挲那册新刊词集，扉页那句「词因樊楼弦上活」墨迹未干透。当年州桥书肆踮脚够书的穷书生，把你们的故事刊成了书。","options":[{"text":"将词集与词稿并藏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"手稿与刊本并排躺着，像一条路的两头。他走成了，你们也走成了。","source":"宋人笔记所载藏札之习。"},{"text":"挑灯通读并作批注","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":1,"才华":1},"feedback":"批到某阕，你写下「此句弦上当缓」。他日他翻到，定会笑出声来。","source":"宋代批点之习见宋人笔记。"}],"difficulty":1,"npc":[],"foreshadow":"刊本词集为定情信物升级"},{"id":"B-045","branch":"B","stage":2,"day":45,"shichen":"辰时","checkpoint":"自立开场·045辰","scene":"里程碑日。晨起，弦正馆首场公开雅集开演，弟子轮弦，你压轴。台下坐着旧日的樊楼客、清议士人、瓦子同行，还有新科的书生。","options":[{"text":"压轴弹《定风波》","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"「谁怕」声落，满堂起身。这一日之后，汴京提起你，先说弦正馆。","source":"《东京梦华录》载汴京伎艺献演之盛。"},{"text":"压轴弹稳妥的旧曲","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"旧曲无错亦无光。自立门户的第一台戏，你交出的是一份温吞水。","source":"同上。"}],"difficulty":3,"npc":["落魄词人","清直士人","弦正馆学生"],"foreshadow":"雅集定弦正馆江湖地位"},{"id":"B-045-未","branch":"B","stage":2,"day":45,"shichen":"未时","checkpoint":"自立开场·045未","scene":"午后雅集散场，小乐伎的首演博得满彩。有老客感慨：当年听先生弹，如今听先生的学生弹——这门手艺，算是在汴京扎下根了。","options":[{"text":"当众归功于众弟子","correct":true,"tags":["名声","才华"],"dims":{"名声":2,"才华":1},"feedback":"你把弟子们一个个叫上台前介绍。肯把学生举过头顶的先生，走得最远。","source":"宋人笔记所载师门奖掖之俗。"},{"text":"谦称全赖自己调教","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"话没说错，可弟子们脸上的光暗了。功劳这东西，越分越多，越独吞越少。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","樊楼旧客"],"foreshadow":"弟子扬名,传承线圆满"},{"id":"B-045-戌","branch":"B","stage":2,"day":45,"shichen":"戌时","checkpoint":"自立开场·045戌","flavor":true,"scene":"夜里，书生帮你收拾雅集散场后的谱架。他忽然说：今日你在台上，我在台下，中间隔着满座的人——可我听着，像只唱给我一个人。","options":[{"text":"答:满座都是弦外之音","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他愣了愣，笑了。谱架收拾完，两人在院里站了很久，谁也没说回屋。","source":"宋人词话所载知音之喻。"},{"text":"把压轴谱赠他收存","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"谱末你添了一行小字：此曲今日始，为君压轴。他收谱的手，很轻很轻。","source":"宋人笔记所载题赠之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"压轴谱为情缘新信物"},{"id":"B-046","branch":"B","stage":2,"day":46,"shichen":"辰时","checkpoint":"传器·046辰","scene":"晨起，老乐工登门，这回带来的是一个旧木盒——教坊历代掌事的调弦旧器，他说自己年事已高，这套东西，该交给汴京最正的弦。","options":[{"text":"设香案郑重拜受","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"旧器一件件过手，像接过一条看不见的河。老人临走时，背挺得笔直。","source":"唐宋教坊器物传承见《乐府杂录》及宋人笔记。"},{"text":"推说贵重不敢私藏","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老人抱着盒子站了很久：器物怕的不是换主，是没人再会用它。你终是收了。","source":"同上。"}],"difficulty":2,"npc":["老乐工"],"foreshadow":"旧器传承,技艺线封顶"},{"id":"B-046-未","branch":"B","stage":2,"day":46,"shichen":"未时","checkpoint":"传器·046未","scene":"午后，你拿旧器为弟子们演示调弦古法，小乐伎忽然问：先生，这些东西往后会传给我们吗？满室弟子都望向你。","options":[{"text":"立誓:技不传敝帚之人","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你答：谁把弦弹正了，东西就是谁的。技艺的传承不看名分，只看功夫。","source":"宋人笔记所载技艺传承择人之俗。"},{"text":"含糊说日后再议","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"弟子们眼里的光悬在半空。传承这件事，最怕先生说「以后再说」。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"传器之约呼应part3弟子线"},{"id":"B-046-戌","branch":"B","stage":2,"day":46,"shichen":"戌时","checkpoint":"传器·046戌","flavor":true,"scene":"夜里，你一件一件擦拭那些旧器，指尖触到前人磨出的凹痕。百年的指温都在这上面，你忽然懂了老乐工那句「别烂在我手里」。","options":[{"text":"为每件旧器登记造册","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"册上记器名、来历、前任主人。器物的账，和人心的账一样，要清白。","source":"宋人笔记所载器物著录之习。"},{"text":"用旧器试弹古曲","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"旧器出声，沉厚如新雪压枝。百年的弦音穿过你的手，又活了一回。","source":"《碧鸡漫志》所载唐宋古曲流变。"}],"difficulty":1,"npc":[],"foreshadow":"旧器册为技艺信物收尾"},{"id":"B-047","branch":"B","stage":2,"day":47,"shichen":"辰时","checkpoint":"揭帖·047辰","scene":"晨起，高家的最后一手来了：一纸无名揭帖贴在州桥，说你「以乐籍之身僭开馆授徒，有伤风化」。措辞阴毒，却拿不出一条实据。","options":[{"text":"携户版文书当众辩诬","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":2},"feedback":"你立于州桥，户版文书、清议题匾、堂断旧案一一亮出。围观者喝彩，揭帖被人撕了。","source":"宋代揭帖构陷与辩诬见宋人笔记所载词讼旧例。"},{"text":"报官请究匿名之人","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"官是报了，可匿名揭帖如泥牛入海。打蛇不死，反倒显得你只会告状。","source":"同上。"}],"difficulty":3,"npc":["高府余党"],"foreshadow":"揭帖事件为高家终局"},{"id":"B-047-未","branch":"B","stage":2,"day":47,"shichen":"未时","checkpoint":"揭帖·047未","scene":"午后，清直士人亲笔写就一篇《弦正辩》，历数你自赎、授艺、拒贿诸事，张贴于州桥原处。半日之间，满城传抄，揭帖之毒不攻自破。","options":[{"text":"登门拜谢士人仗义","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"士人扶起你：我辩的不是你一人，是这汴京还认不认「清白」两个字。","source":"宋代士人著文辩诬之雅见宋人笔记所载。"},{"text":"送礼厚酬以表情意","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"礼被原样退回，附一句：清议不收银。你惭愧收下这句话，比收下礼重得多。","source":"同上。"}],"difficulty":3,"npc":["清直士人"],"foreshadow":"《弦正辩》为舆论定音"},{"id":"B-047-戌","branch":"B","stage":2,"day":47,"shichen":"戌时","checkpoint":"揭帖·047戌","flavor":true,"scene":"夜里，书生拿着传抄的《弦正辩》来，读罢半晌不语。末了他说：清议辩的是你的清白，往后我要写的，是你的半生。","options":[{"text":"答:半生还长,慢慢写","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"灯下两人对坐，他研墨你调弦。半生这个词落地，往后的日子忽然有了形状。","source":"宋人词话所载词者立传之愿。"},{"text":"笑他先写好应试文章","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他正色道：应试文是饭碗，你的文章是性命。你笑着别开脸，耳根热了。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「写你半生」为part3情缘主线"},{"id":"B-048","branch":"B","stage":2,"day":48,"shichen":"辰时","checkpoint":"高家退·048辰","scene":"晨起，尘埃落定：高家举家迁出汴京外放就官，行前托人递来一封无落款的短笺，只有四个字——「弦正名正」。","options":[{"text":"收笺不答,恩怨两讫","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"笺收起，不置一词。赢到最后还肯不追打的人，才是真的赢干净了。","source":"宋人笔记所载恩怨了结之态。"},{"text":"回书讥讽其当年事","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"讥书送出，痛快一刻。可「弦正馆主人刻薄旧怨」的话，也跟着传出去了。","source":"同上。"}],"difficulty":2,"npc":["高府仆从"],"foreshadow":"高家退场,暗线收官"},{"id":"B-048-未","branch":"B","stage":2,"day":48,"shichen":"未时","checkpoint":"高家退·048未","scene":"午后，你盘了盘这一程的账：授艺束脩、雅集酬赠，加上赎后余资，竟比当年在樊楼时更为宽裕。应急簿第一次可以注销了。","options":[{"text":"注销应急簿留作纪念","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"簿末写「此簿从此无用」。当年怕得要死的应急钱，如今成了压箱底的老黄历。","source":"宋代市井记账之习见宋人笔记。"},{"text":"把余资尽数换成头面","correct":false,"tags":["家世"],"dims":{"家世":0},"feedback":"珠翠满匣那刻你心里一空——当年最看不上的活法，怎么自己走回去了。","source":"宋人笔记所载由俭入奢之戒。"}],"difficulty":2,"npc":[],"foreshadow":"账簿善终,自主线圆满"},{"id":"B-048-戌","branch":"B","stage":2,"day":48,"shichen":"戌时","checkpoint":"高家退·048戌","flavor":true,"scene":"夜里，樊楼旧姐妹、资深歌伎、还账姐妹、老乐工齐集小院，说是提前给你暖「收官」的场。院里挤满了人，比当年樊楼的厅还热闹。","options":[{"text":"轮弦共弹当年旧曲","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"一把琵琶众人轮着弹，走音处笑声最大。这一院的嘈杂，是你挣来的江山。","source":"宋人笔记所载宴集轮技之俗。"},{"text":"向众人一一致谢","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"谢到谁，谁就摆手自顾喝酒。谢到最后你也笑了——这群人，不需要谢。","source":"同上。"}],"difficulty":1,"npc":["资深歌伎","还账姐妹","老乐工","樊楼姐妹"],"foreshadow":"班底齐聚为收官夜铺垫"},{"id":"B-049","branch":"B","stage":2,"day":49,"shichen":"辰时","checkpoint":"送别约·049辰","scene":"晨起，书生来谈往后的路：他需赴京备考来年会试，少则半载。你们相对而坐，第一次正经谈起「以后」。","options":[{"text":"约法:各自精进,书信不断","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"他赴考，你授艺；信走驿路，词走弦上。约定立好，离别就不像离别了。","source":"宋代驿递书信之俗见宋人笔记所载。"},{"text":"流露不舍欲留其行","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"「别走」两个字到嘴边，你咽回去了。你有你的弦正馆，留不住，也不该留。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"半载之约为part3开局"},{"id":"B-049-未","branch":"B","stage":2,"day":49,"shichen":"未时","checkpoint":"送别约·049未","scene":"午后，你们商定联络的旧式：他每月寄一阕新词，你每月回一份改定的谱。词来谱往，像当年书肆与樊楼之间那一路。","options":[{"text":"以旧帕包新谱为首寄","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"还是那方旧帕，包过墨，如今包谱。信物转了一圈，包的都是同一个人心。","source":"宋代赠答信物之俗见宋人笔记所载。"},{"text":"托书肆掌柜作中转","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"掌柜的拍着胸脯应下：这条州桥路，我替你们跑到老。旧相识，最可靠。","source":"宋人笔记所载书肆代递之俗。"}],"difficulty":2,"npc":["落魄词人","书肆掌柜"],"foreshadow":"词谱往返为part3通信线","flavor":true},{"id":"B-049-戌","branch":"B","stage":2,"day":49,"shichen":"戌时","checkpoint":"送别约·049戌","flavor":true,"scene":"送别前夜，两人在州桥上走了最后一趟。夜市灯火如昼，书生指着桥栏说：当年你在书里记下我的句子，如今整座桥都记得你的曲子了。","options":[{"text":"答:桥记得,人更要记得","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他用力点头。桥下流水汤汤，你们谁都没说「等我」，可谁都说了。","source":"《东京梦华录》载州桥夜市灯火之盛。"},{"text":"约归来之日桥上相见","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"约在他放榜归来那日，还是这座桥。有了这个约，半载就只是一页日历。","source":"宋人词话所载桥畔订约之雅事。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"桥上之约直通part3重逢"},{"id":"B-050","branch":"B","stage":2,"day":50,"shichen":"辰时","checkpoint":"阶段二收官·050辰","scene":"收官日。晨起书生启程赴京，你送至城外长亭。他翻身上马，回身一揖：弦正馆主，后会有期。青衫渐远，官道尘起。","options":[{"text":"立至不见背影方回","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你没哭，站到天光透亮才转身。好的送别不是拖住，是站成一座路标。","source":"宋代长亭送别之俗见宋人笔记所载。"},{"text":"匆匆别过怕人瞧见","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"回城路上你悔了一路。磊落半生，偏在这一刻藏了——他该看见你送他的。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"长亭送别,part3以别开局"},{"id":"B-050-未","branch":"B","stage":2,"day":50,"shichen":"未时","checkpoint":"阶段二收官·050未","scene":"午后回到弦正馆，弟子们照常练琴，小乐伎的转调已弹得有模有样。馆门上的「弦正」匾被日头晒得发亮。一切如常，一切又都不一样了。","options":[{"text":"收心授课如常","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你拿起琵琶走进课堂。他走他的青云路，你守你的弦正馆——这才是你们的约。","source":"宋人笔记所载民间授艺之常。"},{"text":"怔忡半日无心授课","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"弟子们面面相觑。你终是抱起了琴——人走了，弦不能哑，这是你的本分。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"如常二字为收官定调"},{"id":"B-050-戌","branch":"B","stage":2,"day":50,"shichen":"戌时","checkpoint":"阶段二收官·050戌","flavor":true,"scene":"收官之夜，你独坐小院，把这些日子的物事一件件摆开：户版、总账、裱合的词稿、刊本词集、压轴谱、旧帕。二十五天前的脱籍女子，如今坐拥一整座江山。","options":[{"text":"抚物回望,弹《满州桥雪》","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"曲至「霜满州桥」，弦声平稳如常。来路皆在物中，去路皆在弦上。","source":"《碧鸡漫志》所载以乐述怀之习。"},{"text":"提笔给远行人写首信","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"信首写：今日馆中如常，弦正匾很亮。信末写：桥在，人在，谱已备好。","source":"宋代书简寄远之俗见宋人笔记所载。"}],"difficulty":1,"npc":[],"foreshadow":"物阵回望收官,part3待启"},{"id":"B-051","branch":"B","stage":3,"day":51,"shichen":"辰时","checkpoint":"弦正日隆·051辰","scene":"书生赴京月余。晨起，弦正馆门一打开，求学的帖子雪片似的——「弦正」二字如今是汴京一块响当当的招牌，连外州都有人慕名而来。","options":[{"text":"仍守十二人之额","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"额满即止，排队者登记候缺。招牌的成色，全在「不缺钱也不滥收」这口气。","source":"宋代民间塾学收徒之俗见宋人笔记。"},{"text":"扩招一班趁热打铁","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"班一扩，小乐伎都要替你带课了。先生教不过来，弦就教不正。","source":"同上。"}],"difficulty":2,"npc":["求学者"],"foreshadow":"候缺名册为part4生源线"},{"id":"B-051-未","branch":"B","stage":3,"day":51,"shichen":"未时","checkpoint":"弦正日隆·051未","scene":"午后，一位致仕的老官员登门，想请你入府为女眷授琵琶，束脩是馆中三倍，只是要按府里的规矩——女乐师入内院，出入由人引。","options":[{"text":"婉拒:弦正馆自有讲堂","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你答：府上小姐若肯来，馆里一视同仁。老官员怔了怔，反而遣女儿来报名了。","source":"宋人笔记所载士族延师旧俗。"},{"text":"为束脩应下入府","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"入府三日，引路仆妇的眼神让你浑身不自在。钱是好钱，可那份规矩太像从前。","source":"同上。"}],"difficulty":3,"npc":["致仕官员"],"foreshadow":"官员女儿入学为part4人脉"},{"id":"B-051-戌","branch":"B","stage":3,"day":51,"shichen":"戌时","checkpoint":"弦正日隆·051戌","flavor":true,"scene":"夜里算馆中账目，盈余已稳。你翻到总账扉页那阕《算来清白》，忽然想他——不知道京城今晚的灯，有没有州桥的亮。","options":[{"text":"把思念弹进练习曲里","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"指间的慢板比平日软了三分。思念这东西，藏不住，就让它住在弦上。","source":"宋人词话所载以乐寄怀之习。"},{"text":"核完账目早些安歇","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"账清心安。他走前说过，你守着弦正馆的样子，就是给他的定心丸。","source":"宋代市井记账之习见宋人笔记。"}],"difficulty":1,"npc":[],"foreshadow":"夜思为通信线情绪铺垫"},{"id":"B-052","branch":"B","stage":3,"day":52,"shichen":"辰时","checkpoint":"京信·052辰","scene":"晨起，书肆掌柜亲自跑来了——第一封京中来信到了。词稿三页，附信一封，第一句是：「汴京的弦声，京城没有。」","options":[{"text":"当场展读并回赠掌柜","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"词写京城风物，句句落脚在「不如州桥」。你赏了掌柜茶钱，谢他跑腿之劳。","source":"宋代驿递书信与词稿往来见宋人笔记所载。"},{"text":"揣进袖中回家再看","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"信在袖中焐了一路，到家反而不知先看哪句。好东西，第一口要趁热。","source":"同上。"}],"difficulty":1,"npc":["书肆掌柜"],"foreshadow":"词稿月月至,通信线运转"},{"id":"B-052-未","branch":"B","stage":3,"day":52,"shichen":"未时","checkpoint":"京信·052未","scene":"午后，你依约为他的新词谱曲。其中一阕写京城的雪，调子却怎么谱都觉得浮——直到你想起当年「霜满州桥」的那个雪夜。","options":[{"text":"以旧雪之意谱新雪","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":1},"feedback":"谱成回寄，附言：京雪亦州桥雪。两地一场雪，弦上便是同一个人间。","source":"《碧鸡漫志》所载依词度曲之法。"},{"text":"照字面谱成应景之作","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"谱工整却少了一口气。他词里的雪不是雪，是想你——你险些没接住。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"京雪州雪呼应,词谱合一"},{"id":"B-052-戌","branch":"B","stage":3,"day":52,"shichen":"戌时","checkpoint":"京信·052戌","flavor":true,"scene":"夜里，你把他的来信按次序收入木匣，和旧词稿、刊本词集放在一处。匣子渐渐满了，你把每封信的日期写在封皮上。","options":[{"text":"在匣盖内侧写「词谱」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"两个字写在盖里，合上便是两个人的山河。这匣子，已是半个嫁妆。","source":"宋人笔记所载藏札之习。"},{"text":"重读第一封州桥字条","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"「词因曲活，幸甚至哉」——八字旧笺，如今读来仍会心跳。幸好当年回了四个字。","source":"宋代词简唱酬见宋人词话。"}],"difficulty":1,"npc":[],"foreshadow":"信匣即嫁妆,呼应议婚"},{"id":"B-053","branch":"B","stage":3,"day":53,"shichen":"辰时","checkpoint":"月课·053辰","scene":"晨起考校弟子。月课之期，十二弟子轮弦，小乐伎压轴。她今日弹的，是你当年樊楼立名那支曲子——规矩完整，火候尚嫩。","options":[{"text":"点出三处火候再示范","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你接过琵琶弹同一支，满室听出差别。火候这东西，说得清，才传得下。","source":"唐宋乐艺考校之俗见《乐府杂录》。"},{"text":"夸其完整勉励过关","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"小乐伎欢天喜地，你却知道那三处没点透。先生的宽容，有时是学生的损失。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"月课考校为弟子进阶线"},{"id":"B-053-未","branch":"B","stage":3,"day":53,"shichen":"未时","checkpoint":"月课·053未","scene":"午后，小乐伎私下找你，红着脸问：先生当年在樊楼，第一次登台前夜里，怕不怕？她下月也要登樊楼的台试演了。","options":[{"text":"坦言当年之怕与不怕","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你说：怕，怕就对了——怕说明你拿它当事。她用力点头，眼里有了定色。","source":"宋人笔记所载乐人传艺问答之习。"},{"text":"只嘱她多练不必多想","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"她应了声「是」，可眼神还是飘的。怕这个字，要有人陪着拆，才拆得开。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"试演临近,弟子线蓄势"},{"id":"B-053-戌","branch":"B","stage":3,"day":53,"shichen":"戌时","checkpoint":"月课·053戌","flavor":true,"scene":"夜里你翻出当年自己初试前夜写的小谱，毛边都磨圆了。你把它抄了一份，准备在试演前夜送给小乐伎。","options":[{"text":"附字「弦上有来时路」","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"抄到当年记错的那个音，你笑了笑没改。错的也给她看——来路不丢人。","source":"宋代乐谱传习见宋人笔记。"},{"text":"又抄一份留作馆藏","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"一谱两份，一份传人，一份镇馆。弦正馆的根，从第一页就立住了。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"旧谱赠弟子,传器之约渐进"},{"id":"B-054","branch":"B","stage":3,"day":54,"shichen":"辰时","checkpoint":"王府帖·054辰","scene":"晨起，资深歌伎姐姐来串门，带来一个消息：高家在外任上攀附的一桩婚事黄了，听说是当年「强纳乐籍」的旧闻传到了对方耳朵里。","options":[{"text":"听罢淡淡翻过此页","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你说：他家的门槛高低，与我的弦无关。姐姐笑道：这才是真放下了。","source":"宋人笔记所载市井口耳相传之俗。"},{"text":"追问细节称快不已","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"你追问得越起劲，姐姐眼里的笑意越淡。赢家的快活，不该靠在输家的倒霉上。","source":"同上。"}],"difficulty":2,"npc":["资深歌伎"],"foreshadow":"高家余音渐收"},{"id":"B-054-未","branch":"B","stage":3,"day":54,"shichen":"未时","checkpoint":"王府帖·054未","scene":"午后，馆中来了一位不速之客：某王府的清客，替府中太妃打听，想请你在太妃寿宴上弹唱——这是汴京伎艺人求之不得的台面。","options":[{"text":"应下,但先立好章程","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"应约三条件：只献艺、不入席、酬劳当众交割。清客愣了愣，拱手说「正该如此」。","source":"宋人笔记所载王府宴集召伎旧例。"},{"text":"喜出望外满口应承","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"应得太快，清客眼里闪过一丝轻慢。台面上的体面，都是章程里先争来的。","source":"同上。"}],"difficulty":3,"npc":["王府清客"],"foreshadow":"王府寿宴为名声再进一级"},{"id":"B-054-戌","branch":"B","stage":3,"day":54,"shichen":"戌时","checkpoint":"王府帖·054戌","flavor":true,"scene":"夜里给书生回书，你写了王府寿宴的事，末了添一句：若你在，定要笑话我如今连王府的帖子都敢谈条件了。","options":[{"text":"再抄一份新谱随信寄","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"谱末小字：「此曲若进王府，你是第一个听过的。」先闻为快，是知音的特权。","source":"宋代书简附稿之习见宋人笔记。"},{"text":"信中问他京中可安好","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"问了三句衣食，一句考试。千言万语落到纸上，都是家常两个字。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"家常见问,情缘愈深"},{"id":"B-055","branch":"B","stage":3,"day":55,"shichen":"辰时","checkpoint":"词谱往返·055辰","scene":"词谱之约运转两月。晨起，掌柜的又送信来，这回他忍不住感慨：满城书生写词给歌楼，没见过你们这样一词一谱、雷打不动的。","options":[{"text":"答:约定了的事不雷打不动","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"掌柜的拱手：就冲这句话，这条州桥路我跑到老。守信的人，处处有人成全。","source":"宋代词简唱酬与信守之约见宋人词话。"},{"text":"笑谢掌柜不多解释","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"掌柜的挠头走了。有些约法不怕人知道，说出来，反倒更立得住。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜"],"foreshadow":"掌柜见证为议婚时的现成人证"},{"id":"B-055-未","branch":"B","stage":3,"day":55,"shichen":"未时","checkpoint":"词谱往返·055未","scene":"午后，本月的词稿里夹了张短笺：他在京中遇到当年讥讽过你的同年，那人如今反过来求他的词——他一字未给，只在笺上写了「词有价，知音无价」。","options":[{"text":"回笺:弦有价,风骨无价","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"八个字对八个字，隔千里击掌。当年樊楼那句旧话，如今成了你们的家训。","source":"宋人词话所载清贫词人不鬻文之事。"},{"text":"劝他不可太过得罪人","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"话虽在理，寄出去你就后悔了——他守的是你们的底线，你却劝他打折扣。","source":"同上。"}],"difficulty":3,"npc":["书肆掌柜"],"foreshadow":"风骨家训为议婚底气"},{"id":"B-055-戌","branch":"B","stage":3,"day":55,"shichen":"戌时","checkpoint":"词谱往返·055戌","flavor":true,"scene":"夜里，你把两个月往返的词谱摊了一桌，从头读起：京雪、驿柳、贡院的灯。他的词在长进，你的谱也是——两个人隔着千里，谁都没闲着。","options":[{"text":"将词谱合编成一册","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":1,"才华":1},"feedback":"册名你题了三个字：《往来集》。一来一往，就是你们这一程的全部史书。","source":"宋代词集编订之习见宋人词话。"},{"text":"挑最好的三阕唱给学生听","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"学生问写词的是谁，你答：一位故人。小乐伎挤挤眼，满室都是懂的笑。","source":"宋人笔记所载馆中唱词课徒之习。"}],"difficulty":1,"npc":[],"foreshadow":"《往来集》为part4刊行伏笔"},{"id":"B-056","branch":"B","stage":3,"day":56,"shichen":"辰时","checkpoint":"古谱·056辰","scene":"晨起，王府寿宴的请帖正式送到，撒金帖面，体面至极。帖上点明：闻先生「弦正」之名，太妃想听那支《定风波》。","options":[{"text":"依章程应约备曲","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"帖收得漂亮，章程守得更漂亮。王府的台子再高，你还是按你的规矩站上去。","source":"宋人笔记所载王府宴集召伎旧例。"},{"text":"为攀台面放宽章程","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"条件一松，清客顺势添了两条府里的旧规。台子越高，越要先把脚踩实。","source":"同上。"}],"difficulty":3,"npc":["王府清客"],"foreshadow":"寿宴献艺为名声顶点"},{"id":"B-056-未","branch":"B","stage":3,"day":56,"shichen":"未时","checkpoint":"古谱·056未","scene":"午后试演备曲，老乐工来听。听完他沉默许久，说：这支曲子如今的火候，教坊鼎盛时也没几个人弹得出来。你的眼睛，该往《霓裳》那样的古曲上放了。","options":[{"text":"拜请老乐工指授古曲","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"老人眼里泛光：我等这句话等了四十年。古曲的残谱，终于要从箱底见天了。","source":"《霓裳羽衣曲》唐宋流变见《碧鸡漫志》所载。"},{"text":"谦称不敢问津大曲","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老人叹了口气没再提。古曲不传不是秘惜，是怕没人敢接——你险些错过了。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"古曲残谱为part4技艺巅峰线"},{"id":"B-056-戌","branch":"B","stage":3,"day":56,"shichen":"戌时","checkpoint":"古谱·056戌","flavor":true,"scene":"夜里，老乐工遣人送来一函残谱，虫蛀了边角。你就着灯一页页翻，那些残缺的音符像断了线的旧事，等你一寸寸接回去。","options":[{"text":"依秘本逐页校补残谱","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"补到三更，补出第一个完整的乐句。四百年前的声音，在你指下喘了口气。","source":"唐宋古曲辑佚之习见《碧鸡漫志》。"},{"text":"先抄副本再行校补","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"原本供起来，副本上用功。敬古人的规矩，也是护宝物的章法。","source":"宋人笔记所载典籍抄副之习。"}],"difficulty":2,"npc":[],"foreshadow":"校补古曲为技艺线最高目标"},{"id":"B-057","branch":"B","stage":3,"day":57,"shichen":"辰时","checkpoint":"试演·057辰","scene":"晨起，小乐伎的樊楼试演就在今夜。她来馆中时手心全是汗，你递给她那份抄好的旧谱——你当年初试前夜的手稿。","options":[{"text":"赠谱并讲当年心路","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"她捧着谱，看到上面记错的那个音，忽然笑了：先生当年也会错。汗，止住了。","source":"宋代乐谱传习见宋人笔记。"},{"text":"只嘱她莫负弦正之名","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"「莫负」两个字压下去，她的手心汗更多了。勉励和施压，只差一个字。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"旧谱定心,试演在即"},{"id":"B-057-未","branch":"B","stage":3,"day":57,"shichen":"未时","checkpoint":"试演·057未","scene":"午后樊楼试演，你坐在当年那些雅客坐过的位子上。帘起，小乐伎登场，起手三音沉稳清亮——是弦正馆的路数，满楼皆惊。","options":[{"text":"曲终起身第一个喝彩","correct":true,"tags":["名声","才华"],"dims":{"名声":2,"才华":1},"feedback":"你一站起，满楼跟着站。当年你在这台上挣来的掌声，如今原样传给了她。","source":"《东京梦华录》载樊楼伎艺献演之盛。"},{"text":"含笑端坐不动声色","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"掌声起了，却慢了半拍。前辈的一声喝彩，是新人的半条命——你险些忘了。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","掌班"],"foreshadow":"试演大捷,传承线落地"},{"id":"B-057-戌","branch":"B","stage":3,"day":57,"shichen":"戌时","checkpoint":"试演·057戌","flavor":true,"scene":"夜里小乐伎回馆，眼睛亮得像星星，拉着你讲了一晚上的台上细节。讲到最后她忽然红了眼眶：先生，我也算站住过了。","options":[{"text":"答:站住了,就别下来","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"她重重点头。你看着她，像看一株自己亲手扶直的竹子——已经拔节了。","source":"宋人笔记所载师门奖掖之俗。"},{"text":"煮两盏茶陪她细说","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"茶续了三遍，她的话才说完。有些夜晚不讲技艺，只讲高兴。","source":"宋人笔记所载夜话煎茶之习。"}],"difficulty":1,"npc":["小乐伎学生"],"foreshadow":"弟子自立,传器之约将近"},{"id":"B-058","branch":"B","stage":3,"day":58,"shichen":"辰时","checkpoint":"寿宴·058辰","scene":"晨起，王府寿宴日。你携琵琶入府，献艺一章即退。太妃听罢《定风波》，赏下一对玉搔头，又传话：好一个「谁怕」，老婆子记住了。","options":[{"text":"谢赏退席不宴不叙","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"赏收得大方，席退得干净。当夜汴京传开：弦正先生的规矩，王府也敬。","source":"宋人笔记所载王府宴集献艺旧例。"},{"text":"奉太妃命多留叙话","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"叙话间贵妇人的试探一句接一句，你应对得累。章程松一寸，麻烦进一尺。","source":"同上。"}],"difficulty":3,"npc":["王府太妃","王府清客"],"foreshadow":"玉搔头为后文议婚礼单伏笔"},{"id":"B-058-未","branch":"B","stage":3,"day":58,"shichen":"未时","checkpoint":"寿宴·058未","scene":"午后回馆，满汴京都知道太妃赏了玉搔头。有同行酸言酸语，说你这是攀上王府了。你听完，只做了一件事。","options":[{"text":"照常授课不理酸言","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"馆中弦声如常，三日后酸言自熄。名声到了一定份上，沉默就是最贵的回应。","source":"宋人笔记所载市井口舌消长之理。"},{"text":"设帖宴请以正视听","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"帖子一撒，倒像真有什么要「正」。清白的事摆宴席，越描越像遮掩。","source":"同上。"}],"difficulty":2,"npc":["同行乐人"],"foreshadow":"沉默应讥为后文物议预演"},{"id":"B-058-戌","branch":"B","stage":3,"day":58,"shichen":"戌时","checkpoint":"寿宴·058戌","flavor":true,"scene":"夜里独对玉搔头，你把它和及笄那支素银簪并排放着。一支是王府的赏，一支是当年的礼——两支流光之间，隔着你的半生。","options":[{"text":"以银簪为主玉簪为辅","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"玉搔头收进匣侧，银簪留在案头。贵的收起来，真的放眼前。","source":"宋人笔记所载首饰藏用之习。"},{"text":"记入册中注明来历","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"册上写明：太妃赏，某年月日。每件东西的来路清白，人也就清白。","source":"宋人笔记所载器物著录之习。"}],"difficulty":1,"npc":[],"foreshadow":"两簪并陈为收官回望意象"},{"id":"B-059","branch":"B","stage":3,"day":59,"shichen":"辰时","checkpoint":"来路册·059辰","scene":"晨起，京城来信。书生说会试已毕，文章自觉尚可，只是考前有座师门下的人探问他的「私行」——他问：若榜上有名，物议必至，你可准备好了？","options":[{"text":"回信:物议来,我迎战","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"你回：当年高家的风浪尚且过得，何况几句闲话。你只管放榜，我自有章程。","source":"宋代科举物议之俗见宋人笔记所载。"},{"text":"回信流露半分忧惧","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"一个「怕」字写在纸上，寄出去就撤不回了。他还在等放榜，不该先接你的愁。","source":"同上。"}],"difficulty":3,"npc":[],"foreshadow":"迎战之言为物议战定调"},{"id":"B-059-未","branch":"B","stage":3,"day":59,"shichen":"未时","checkpoint":"来路册·059未","scene":"午后，你提前做了件事：把户版文书、堂断旧案、清议题匾的来历整理成一份「来路册」。物议若来，你打算让它撞上早有准备的墙。","options":[{"text":"成册备而不用为上","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"册子备好收进匣中。最好的反击是备而不发——它在那儿，你就永远不虚。","source":"宋人笔记所载存证备质之俗。"},{"text":"先发制人四处出示","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"人家还没开口，你先把家底抖了一街。防备做成表演，体面先输了三分。","source":"同上。"}],"difficulty":3,"npc":[],"foreshadow":"来路册为物议战底牌"},{"id":"B-059-戌","branch":"B","stage":3,"day":59,"shichen":"戌时","checkpoint":"来路册·059戌","flavor":true,"scene":"夜里，你把「来路册」放进木匣，与词稿、刊本、旧帕躺在一处。这匣子如今装的是：他的词、你的路、你们两个人全部的来处。","options":[{"text":"抚匣自语:都不丢人","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"四个字说完，心彻底定了。物议来罢——这一匣子东西，件件经得起日头。","source":"宋人笔记所载藏札之习。"},{"text":"把册子再校一遍字","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"逐字校过，无一含糊。你跟这世道打交道这些年，最懂一字之差的分量。","source":"宋人笔记所载文书校雠之习。"}],"difficulty":1,"npc":[],"foreshadow":"木匣集大成,议婚前夜"},{"id":"B-060","branch":"B","stage":3,"day":60,"shichen":"辰时","checkpoint":"弟子接棒·060辰","scene":"里程碑日。晨起，你在馆中当众宣布：依「传器之约」，小乐伎月课、试演、课徒三项皆优，教坊旧器中最重要的那副调弦器，今日传她。","options":[{"text":"当众行传器之礼","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":2},"feedback":"调弦器过手，满馆弟子肃立。你补一句：器认功夫不认人——这话今日起也是馆训。","source":"宋人笔记所载技艺传承择人之俗。"},{"text":"私下授器免去张扬","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"器是传了，可众弟子不知其重。传承的仪式，本身就是一堂课。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"器认功夫为馆训,part4延续"},{"id":"B-060-未","branch":"B","stage":3,"day":60,"shichen":"未时","checkpoint":"弟子接棒·060未","scene":"午后，小乐伎抱着调弦器来谢恩，说要把这器物的来历背下来。你却摇头，考她另一件事：器是死的，你说说，它认的是什么？","options":[{"text":"听她答「功夫」再补二字","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"她答功夫，你补「心正」。器认功夫，更认心正——这是比指法更深的一课。","source":"宋人笔记所载师门心法相传之习。"},{"text":"让她背熟来历即可","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"来历背得滚瓜烂熟，道理却只停在嘴上。传器不传心，等于传了个空盒子。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"「心正」二字为弟子线内核"},{"id":"B-060-戌","branch":"B","stage":3,"day":60,"shichen":"戌时","checkpoint":"弟子接棒·060戌","flavor":true,"scene":"夜里，你独自擦拭留下的几件旧器。老乐工的话又在耳边：器物怕的不是换主，是没人再会用它。如今，有人了。","options":[{"text":"在器册上记今日之事","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"册上添一行：某年月日，器传某人。百年之后再有人翻到这页，弦就还没断。","source":"宋人笔记所载器物著录之习。"},{"text":"弹一曲告慰传器之人","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"曲子弹给不在场的老乐工。明早他若听见风声，定会抚掌大笑。","source":"宋人词话所载以乐告友之习。"}],"difficulty":1,"npc":[],"foreshadow":"器册续写,传承不止"},{"id":"B-061","branch":"B","stage":3,"day":61,"shichen":"辰时","checkpoint":"候榜·061辰","scene":"晨起，汴京城都在等一件事：会试放榜的杏榜就快传回。书肆掌柜比你还急，一天来探了三回——桥上之约，近在眼前了。","options":[{"text":"照常授课静候榜讯","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"课上得纹丝不乱。弟子们私下说：先生这定力，够我们学十年。","source":"宋代会试放榜之俗见宋人笔记所载。"},{"text":"停了课专等消息","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"课一停，满馆都跟着你悬着。你一乱，弦正馆的天平就跟着晃。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜"],"foreshadow":"榜讯将至,桥上之约倒计时"},{"id":"B-061-未","branch":"B","stage":3,"day":61,"shichen":"未时","checkpoint":"候榜·061未","scene":"午后，资深歌伎姐姐送来一套簇新的衣裙，说是贺你「桥上之约」的行头。衣裙素雅，针脚却是满汴京最好的。","options":[{"text":"谢过收下,约期再穿","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"衣裙挂进里间。姐姐笑道：当年较技的冤家，如今成了送嫁的娘家人。","source":"宋人笔记所载闺中赠衣之俗。"},{"text":"推说素服惯了就罢了","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"姐姐把衣裙往你怀里一塞：大日子穿旧衣，亏的是你自己。话糙理不糙。","source":"同上。"}],"difficulty":1,"npc":["资深歌伎"],"foreshadow":"新衣候约,重逢在即"},{"id":"B-061-戌","branch":"B","stage":3,"day":61,"shichen":"戌时","checkpoint":"候榜·061戌","flavor":true,"scene":"夜里你试那套新衣，对着铜镜转了一圈。镜中人眉目沉静——不是当年樊楼帘后的歌伎，也不是谁家的眷属，是弦正馆的主人。","options":[{"text":"配及笄那支素银簪","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"新衣旧簪，意外地相称。银簪陪你从及笄走到今日，桥上也该它在场。","source":"宋人笔记所载及笄遗俗与簪珥之习。"},{"text":"将衣簪收入匣中待期","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"衣簪与木匣并排。你忽然觉得，这屋子里所有的东西都在等同一个日子。","source":"宋人笔记所载藏衣待期之俗。"}],"difficulty":1,"npc":[],"foreshadow":"旧簪新衣为重逢装束"},{"id":"B-062","branch":"B","stage":3,"day":62,"shichen":"辰时","checkpoint":"得中·062辰","scene":"晨起，杏榜传回汴京——他中了！名次不显，却在榜尾稳稳当当。书肆掌柜冲进院子时跑丢了一只鞋：姑娘，中了！桥上之约，作数了！","options":[{"text":"先问归期再问名次","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"掌柜的愣了：别人先问名次，你先问归期。你笑：名次是他的，归期是我们的。","source":"宋代杏榜传报之俗见宋人笔记所载。"},{"text":"追问名次与授官","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"名次官阶问得细，掌柜答得也细，可你心里那点欢喜，被问得失了味道。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜"],"foreshadow":"得中而归,物议随榜而至"},{"id":"B-062-未","branch":"B","stage":3,"day":62,"shichen":"未时","checkpoint":"得中·062未","scene":"午后，榜讯传遍，果然有闲话跟着回来了：新科某某，与「乐籍出身的馆主」往来密切，座师门里已有微词。得中之虑，正面来了。","options":[{"text":"取出「来路册」备用","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"册子摊开在案，你不慌不忙又校了一遍。风浪要来，就让它撞一堵干净的墙。","source":"宋人笔记所载科举物议与存证之俗。"},{"text":"急遣人探问他的态度","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"探问的话递出去，倒显得你心虚气短。他的答卷，当年在瓦子就交过了。","source":"同上。"}],"difficulty":3,"npc":[],"foreshadow":"物议压顶,重逢前暗涌"},{"id":"B-062-戌","branch":"B","stage":3,"day":62,"shichen":"戌时","checkpoint":"得中·062戌","flavor":true,"scene":"夜里，你收到他榜后第一信，只比榜讯晚到半日。信很短：「名在榜尾，心在原处。启程在即，桥上见。」","options":[{"text":"回信二字:恭候","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"两个字，不多不少。千言万语都留给桥上——有些话必须当面说。","source":"宋代书简寄远之俗见宋人笔记。"},{"text":"回信附一枝干梅花","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"梅是院里自己开的。他路上若拆开，京城的春风里就有了汴京的香。","source":"宋人笔记所载折梅寄远之雅。"}],"difficulty":1,"npc":[],"foreshadow":"「心在原处」为重逢定调"},{"id":"B-063","branch":"B","stage":3,"day":63,"shichen":"辰时","checkpoint":"物议至·063辰","scene":"晨起，物议正式压来：有同年撰文讥讽，说新科若迎娶「乐籍」，有辱斯文；更有说客绕到弦正馆，劝你「为前程计，自请退避」。","options":[{"text":"开门迎客,当面对答","correct":true,"tags":["自主","名声"],"dims":{"自主":3,"名声":1},"feedback":"你答：奴家的来路写在官府户版上，退避两个字，字典里没有。说客无言而退。","source":"宋代士人婚姻物议之俗见宋人笔记所载。"},{"text":"闭门谢客不予理会","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"门一闭，「理亏」两个字就替你说出了口。这一回，躲比输更难看。","source":"同上。"}],"difficulty":3,"npc":["说客","同年文士"],"foreshadow":"当面折说客,物议第一回合胜"},{"id":"B-063-未","branch":"B","stage":3,"day":63,"shichen":"未时","checkpoint":"物议至·063未","scene":"午后，清直士人听闻物议，遣人问你：可需老朽再写一篇《弦正辩》？你握着笔，斟酌回话的分寸。","options":[{"text":"谢过,请先观他的作为","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你回：他的答卷未到，议论先行，于他不公。士人叹服：姑娘这份沉住气，难得。","source":"宋人笔记所载清议自重之习。"},{"text":"立请士人著文还击","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"文未写，你先把战场铺开了。婚姻本是两个人的事，借刀太多，就变了味。","source":"同上。"}],"difficulty":3,"npc":["清直士人"],"foreshadow":"静候其行,重逢答卷在前"},{"id":"B-063-戌","branch":"B","stage":3,"day":63,"shichen":"戌时","checkpoint":"物议至·063戌","flavor":true,"scene":"夜里物议的杂声隔着墙隐隐可闻。你抱琴上弦，弹的不是《定风波》，是当年州桥书肆他写的第一阕词——你们开始的地方。","options":[{"text":"弹旧曲以定当下心","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"旧曲弹罢，心如古井。外头说什么随它去——你们的根，比物议深得多。","source":"宋人词话所载以旧作明心迹之习。"},{"text":"把讥讽文抄进小册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"抄完在末尾批一句：留待他日笑看。记仇不如记账，账有结清的一天。","source":"宋人笔记所载记事册之习。"}],"difficulty":1,"npc":[],"foreshadow":"旧曲定心,迎接重逢"},{"id":"B-064","branch":"B","stage":3,"day":64,"shichen":"辰时","checkpoint":"本心·064辰","scene":"晨起，又一波压力：有官员放话，若他执意娶你，吏部注官时「须斟酌」。这话分量不轻——功名前程，与你们的婚约，被摆上了同一杆秤。","options":[{"text":"致信于他:但凭本心","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":2},"feedback":"信只一句：前程是你的，我不替你要；我在这儿，不替谁退。落笔，心安。","source":"宋代吏部注官之制见《宋史·选举志》及宋人笔记。"},{"text":"致信劝他三思前程","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"「三思」二字一寄，等于你先替这场仗投了降。他若动摇，是你先松的手。","source":"同上。"}],"difficulty":3,"npc":[],"foreshadow":"本心之信为物议战枢纽"},{"id":"B-064-未","branch":"B","stage":3,"day":64,"shichen":"未时","checkpoint":"本心·064未","scene":"午后，弟子们听闻外头的风风雨雨，小乐伎领着十一人齐整整立在院中：先生若受委屈，我们十二人上街为先生辩白。","options":[{"text":"谢过众弟子令其安坐","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你说：先生的仗先生自己打，你们的功课是把弦弹正。弟子含泪应诺。","source":"宋人笔记所载师门义烈之习。"},{"text":"由弟子们上街声援","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"十二个学生一上街，物议立时变成「弦正馆聚众」。护主的心，办了坏事。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"弟子护主之心为part4情义线"},{"id":"B-064-戌","branch":"B","stage":3,"day":64,"shichen":"戌时","checkpoint":"本心·064戌","flavor":true,"scene":"夜里，归人将至的消息传来：他的船已过陈留，三五日便到汴京。你立在院中，看州桥方向的灯火，把重逢那天要说的话，在心里过了一遍。","options":[{"text":"什么都不预备,凭心说","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"腹稿打了三遍，最后全删了。真心的话不用备，它自己知道路。","source":"宋人词话所载相见之喜。"},{"text":"把新衣银簪理出来","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"衣抚平，簪擦亮。你忽然笑了：这辈子两次郑重，一次及笄，一次见他。","source":"宋人笔记所载整装迎归之俗。"}],"difficulty":1,"npc":[],"foreshadow":"归期在三五日内,约至"},{"id":"B-065","branch":"B","stage":3,"day":65,"shichen":"辰时","checkpoint":"放榜风波·065辰","scene":"决战日。晨起，满城轰动：他抵京前在码头当众焚了一封荐书——座师门下递来的、附条件的美差引荐，条件是「绝旧交」。火光照了半条河。","options":[{"text":"闻讯长出一口气","correct":true,"tags":["情缘","名声","感情"],"dims":{"情缘":2,"名声":1},"feedback":"你缓缓坐下。他交卷了：功名可以慢，来路不能烧。这份答卷，比金榜重。","source":"宋人笔记所载士人辞却干谒之事。"},{"text":"急遣人问荐书原委","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"追问的口信递出去，倒像你在盘点他的牺牲。他烧荐书，烧的是自己的路。","source":"同上。"}],"difficulty":3,"npc":["座师门客"],"foreshadow":"焚荐书为物议战定音"},{"id":"B-065-未","branch":"B","stage":3,"day":65,"shichen":"未时","checkpoint":"放榜风波·065未","scene":"午后，风向一夜倒转：焚荐书的事传开，清议大哗——这回哗的是赞叹。先前讥讽的同年悄悄撤了文章，吏部的「斟酌」之说再没人提。","options":[{"text":"照旧授课不议人非","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你对满馆只说一句：今日课上，不谈馆外事。这份不踩人的稳，满城敬服。","source":"宋人笔记所载清议消长之理。"},{"text":"与姐姐痛议前倨后恭","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"痛快话说了一箩筐，出门就撞见撤文的同年——你脸上先烧起来了。","source":"同上。"}],"difficulty":3,"npc":["资深歌伎","弦正馆学生"],"foreshadow":"物议尽扫,议婚坦途"},{"id":"B-065-戌","branch":"B","stage":3,"day":65,"shichen":"戌时","checkpoint":"放榜风波·065戌","flavor":true,"scene":"夜里，他的信到了，是焚荐书后写的：「荐书烧了，一身轻。当年你说弦有定音人有定心——如今我把这八个字，还给写它的人。」","options":[{"text":"回信:桥上,当面还我","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"六个字寄出。债要当面还，人要当面见——州桥的灯，已经亮起来了。","source":"宋代书简往还见宋人笔记所载。"},{"text":"把信与旧帕同藏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"信贴着旧帕收好。这匣子从及笄收到今日，明日之后，就该换个地方放了。","source":"宋人笔记所载藏札之习。"}],"difficulty":1,"npc":[],"foreshadow":"匣子换处暗指过门"},{"id":"B-066","branch":"B","stage":3,"day":66,"shichen":"辰时","checkpoint":"桥上之约·066辰","scene":"践约日。晨起，你穿上姐姐送的新衣，插上及笄那支素银簪。今日他的船到，州桥之上，半年的词谱往返，都要落地了。","options":[{"text":"抱谱赴约,不早不迟","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你踩着约好的时辰出门。半年的等待，不差这一刻的从容。","source":"《东京梦华录》载州桥形胜与汴河舟楫之盛。"},{"text":"天不亮就候在桥上","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"晨风把你的裙角吹得冰凉。等可以，把自己等成一尊望夫石，不必。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"赴约践诺,情缘线高潮"},{"id":"B-066-未","branch":"B","stage":3,"day":66,"shichen":"未时","checkpoint":"桥上之约·066未","scene":"午后，州桥。他从桥那头走来，青衫换成了襕衫，人清瘦了些，眼里还是那年的光。两人在桥心站定，半年风雨，四目相对。","options":[{"text":"递上《往来集》相迎","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"他接册翻开，词与谱一页页对着。他哑声说：半载山河，都在这册子里了。","source":"宋代词集赠答之雅见宋人词话。"},{"text":"执手相看忘了言语","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"桥上人来人往，你们立在当中，把满桥的目光站成了一道风景。","source":"宋人词话所载久别重逢之喜。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"《往来集》为定情正典"},{"id":"B-066-戌","branch":"B","stage":3,"day":66,"shichen":"戌时","checkpoint":"桥上之约·066戌","flavor":true,"scene":"夜里，两人沿汴河慢慢走，从州桥走到虹桥。他说京城的雪，说贡院的灯，说焚荐书时河面的火光。你静静听，一句都没打断。","options":[{"text":"听罢只说:你瘦了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"三个字，他红了眼眶。千难万险说出来是故事，心疼两个字才是日子。","source":"宋人笔记所载汴河夜行之景。"},{"text":"与他细数十日路程","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你说这十日你每日弹一曲替他数着。他停步看你：往后换我替你数。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「换我替你数」为议婚引子"},{"id":"B-067","branch":"B","stage":3,"day":67,"shichen":"辰时","checkpoint":"议婚·067辰","scene":"晨起，他登门了，一身郑重。第一句交代：座师欲为他保媒某官宦之女，他当面回绝了，说的是——「某已有心上人，汴京弦正馆主」。","options":[{"text":"静听完,问其名分打算","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"他答：明媒正娶，三书六礼，一样不少。你点头：这才是你敢嫁的路数。","source":"宋代婚姻六礼之制见《宋史·礼志》及宋人笔记。"},{"text":"惊喜之下忘了问名分","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"欢喜归欢喜，话没说透。名分这件事，今天不问，往后就是你心里的刺。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"三书六礼之约启动议婚"},{"id":"B-067-未","branch":"B","stage":3,"day":67,"shichen":"未时","checkpoint":"议婚·067未","scene":"午后，轮到你了。他既交了答卷，你也要亮你的章程：这门亲事如何议、嫁妆何来、弦正馆何去——你要他听明白，再点头。","options":[{"text":"亮明:馆不辍,嫁妆自出","correct":true,"tags":["自主","家世"],"dims":{"自主":3,"家世":1},"feedback":"你说：我嫁人不嫁馆，嫁妆是我自己的积蓄。他郑重揖下：正合我意。","source":"宋代女子奁产自主之俗见宋人笔记所载。"},{"text":"含糊说全凭他安排","correct":false,"tags":["自主"],"dims":{"自主":0},"feedback":"「全凭安排」一出口，你半生挣来的主动权，悄悄松了手。他愣了愣，没接。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"自出奁产为议婚底气核心"},{"id":"B-067-戌","branch":"B","stage":3,"day":67,"shichen":"戌时","checkpoint":"议婚·067戌","flavor":true,"scene":"夜里他告辞前，从袖中取出一张纸——是他拟的婚书单，条款细密：婚后弦正馆照开、《往来集》合署刊行、你的奁产永远归你名下。","options":[{"text":"逐条看过,添上一条","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你添的是：「每年州桥一叙，风雨不废。」他笑了：这条我本想写,怕你笑我酸。","source":"宋代婚书之约见宋人笔记所载婚俗。"},{"text":"收书单待与长者商议","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"书单收好。他写得越细，你越要稳——好的开始，值得最慎重的章法。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"州桥年约为part4余韵"},{"id":"B-068","branch":"B","stage":3,"day":68,"shichen":"辰时","checkpoint":"见证·068辰","scene":"晨起，你把婚书单的事禀了老乐工与鸨母——这两位，是你在这世上最亲的长辈。鸨母听完，沉默良久，眼圈红了。","options":[{"text":"请二老做主婚见证","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"鸨母拭泪笑骂：当年账册前的小丫头，如今请我做主婚人。老乐工重重点头。","source":"宋代婚姻尊长见证之俗见宋人笔记所载。"},{"text":"只告知不请见证","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"两位老人笑着应了，笑意却浅。人生大事不请长辈站台，他们嘴上不说,心里空。","source":"同上。"}],"difficulty":2,"npc":["鸨母","老乐工"],"foreshadow":"二老见证为婚礼班底"},{"id":"B-068-未","branch":"B","stage":3,"day":68,"shichen":"未时","checkpoint":"见证·068未","scene":"午后，消息传开，弦正馆沸腾。小乐伎带头闹：先生出嫁，我们十二人要做送嫁的仪仗！馆里顿时乱成一锅欢喜的粥。","options":[{"text":"应下,各派一份差事","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"差事派得井井有条：掌乐的、执礼的、迎宾的。弦正馆的喜日，人人都是主角。","source":"宋代婚仪执事之俗见宋人笔记所载。"},{"text":"笑闹由她们自己张罗","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"撒手不管的结果是章程乱套。喜事也要有谱——这是弦正馆的规矩。","source":"同上。"}],"difficulty":1,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"弟子执事为婚礼阵容"},{"id":"B-068-戌","branch":"B","stage":3,"day":68,"shichen":"戌时","checkpoint":"见证·068戌","flavor":true,"scene":"夜里，资深歌伎姐姐提着酒不请自来，进门就嚷：当年送你新衣时我就知道有今天！两人对坐，把这些年的事从头数了一遍。","options":[{"text":"敬她当年较技之恩","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"她一愣：较技还算恩？你答：不输那一阵较劲，哪有今日这一身硬骨头。","source":"宋人笔记所载同侪夜话之俗。"},{"text":"请她婚礼日坐高堂位","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"她推了三回，到底应了，抹着眼泪笑：我这辈子，总算坐一回正经席面。","source":"宋代婚仪高堂之礼见宋人笔记所载。"}],"difficulty":1,"npc":["资深歌伎"],"foreshadow":"姐姐坐高堂为婚礼泪点"},{"id":"B-069","branch":"B","stage":3,"day":69,"shichen":"辰时","checkpoint":"纳采·069辰","scene":"晨起，媒人上门了——他请的是城里最德高望重的老媒婆，携着纳采之礼，规矩一丝不乱。六礼的第一礼，堂堂正正进了弦正馆的门。","options":[{"text":"依礼接待,章程不乱","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"纳采礼成，媒婆出门逢人便说：走了几十年媒，头一回见姑娘自己把礼数主持得这样稳。","source":"宋代婚姻六礼纳采之制见《宋史·礼志》。"},{"text":"羞怯回避由媒婆自便","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你躲在内室，媒婆隔着帘子问了三回生辰。礼数这东西，躲一步就乱三步。","source":"同上。"}],"difficulty":2,"npc":["媒婆"],"foreshadow":"纳采礼成,六礼启动"},{"id":"B-069-未","branch":"B","stage":3,"day":69,"shichen":"未时","checkpoint":"纳采·069未","scene":"午后，纳采的消息伴着新的闲话传开：有人说他一个功名在身的人，行六礼娶乐籍出身，是自毁前程。媒婆回来学舌，替你生气。","options":[{"text":"请媒婆原话传回去","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你教媒婆传话：前程若靠委屈得来，那样的前程我们不要。话传开，物议又矮一头。","source":"宋人笔记所载媒妁传言之俗。"},{"text":"忍下闲话不欲再生波","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"闲话没人接，就在街上多长了三天腿。迎亲的鼓点还没响，先混进了杂音。","source":"同上。"}],"difficulty":3,"npc":["媒婆"],"foreshadow":"传话退议为议婚清场"},{"id":"B-069-戌","branch":"B","stage":3,"day":69,"shichen":"戌时","checkpoint":"纳采·069戌","flavor":true,"scene":"夜里，你取出当年的「来路册」，在最后一页添了一行：某年月日，纳采礼成，六礼自此始。写完把册子放回木匣，它很快要有新主人共看了。","options":[{"text":"抚册默数来路年月","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"从及笄到纳采，册上不过几十页，脚下却是半生。路短纸薄，人是真走过来了。","source":"宋人笔记所载记事册之习。"},{"text":"弹一曲《满州桥雪》","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"这支曲子从脱籍唱到纳采。雪早化了，可每次弹起，都像回到了那座桥。","source":"宋人词话所载以乐纪事之习。"}],"difficulty":1,"npc":[],"foreshadow":"来路册入奁,part4可展"},{"id":"B-070","branch":"B","stage":3,"day":70,"shichen":"辰时","checkpoint":"提亲议婚·070辰","scene":"议婚正日。晨起，问名、纳吉依次行来，媒婆跑得脚底生风。最关键的一关在眼前：奁产清点——你要当着众人的面，亮出你的嫁妆。","options":[{"text":"当众清点,来路一一说明","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":2},"feedback":"缠头总账、授艺盈余、王府赏赐，笔笔有来路。媒婆叹道：这份奁产，清白得发光。","source":"宋代奁产清点之俗见宋人笔记所载婚俗。"},{"text":"含糊报个总数即可","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"总数报出去，议论跟着来：数目可不小，来路呢？你最清白的仗，险些打得含糊。","source":"同上。"}],"difficulty":3,"npc":["媒婆","鸨母"],"foreshadow":"奁产清白为议婚定音"},{"id":"B-070-未","branch":"B","stage":3,"day":70,"shichen":"未时","checkpoint":"提亲议婚·070未","scene":"午后，清直士人闻讯送来贺仪：不是金银，是一幅亲笔——「德音不忘」。满座传看，都说这四个字，抵得过千金装奁。","options":[{"text":"悬于堂上谢过厚意","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「德音不忘」挂上正堂，与「弦正」匾遥遥相对。文人的秤砣一落，满城再无闲话。","source":"宋代士人题赠贺仪见宋人笔记所载。"},{"text":"珍而重之收入匣中","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"字是好字，收进匣子却可惜。清议的背书要挂出来晒着，才镇得住场。","source":"同上。"}],"difficulty":2,"npc":["清直士人"],"foreshadow":"双匾相映为馆中大雅"},{"id":"B-070-戌","branch":"B","stage":3,"day":70,"shichen":"戌时","checkpoint":"提亲议婚·070戌","flavor":true,"scene":"夜里，他来谢宴，立在堂上看那幅「德音不忘」看了很久。回头对你说：往后这个家，你挂的每一件东西，都有来历。","options":[{"text":"答:人也一样,有来路","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"他郑重拱手。这句话他懂：你嫁给他，连人带物，没有一分是来路不明的。","source":"宋人笔记所载厅堂题悬之俗。"},{"text":"请他题一幅配成对","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他提笔写下「弦歌在兹」。两幅字挂在一处，一赠一答，这个家开始说话了。","source":"宋人词话所载题壁唱和之雅。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「弦歌在兹」为新家镇宅"},{"id":"B-071","branch":"B","stage":3,"day":71,"shichen":"辰时","checkpoint":"奁产·071辰","scene":"晨起，纳征之期将近，外任的高家忽然遣人送来一份贺仪——是那封「弦正名正」短笺的主人，正式具名，附上一份不厚不薄的礼。","options":[{"text":"依常礼收帖,礼回半数","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"帖收礼回，恩怨至此两清。满城皆道：弦正馆主连收礼都收得有章法。","source":"宋人笔记所载贺仪酬答之礼。"},{"text":"原样退回不留余地","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"退得决绝，闲话却起：到底还是有旧怨。恩怨的最后一笔，该用礼数写,不用意气。","source":"同上。"}],"difficulty":2,"npc":["高府仆从"],"foreshadow":"高家线正式落幕"},{"id":"B-071-未","branch":"B","stage":3,"day":71,"shichen":"未时","checkpoint":"奁产·071未","scene":"午后，吏部的消息落定：他注官了，虽非显缺，却是实打实的出身。有人暗笑这官小，他却对来贺的人说：官可以从小做，人要从正做。","options":[{"text":"闻言深以为然","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你对他遣来报喜的人说：回他，弦正馆主也是这么起家的。满座大笑称善。","source":"宋代吏部注官之制见《宋史·选举志》。"},{"text":"私下惋惜官阶不高","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"惋惜的话传到他耳中，他沉默了一瞬。他缺的从来不是官大，是你信他。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"小官正做为part4官途线"},{"id":"B-071-戌","branch":"B","stage":3,"day":71,"shichen":"戌时","checkpoint":"奁产·071戌","flavor":true,"scene":"夜里，你整理奁产清单，把那对玉搔头也写进去了，注了一笔：王府赏，可传。写到「传」字，你想起小乐伎接过调弦器时的手。","options":[{"text":"另立一份传馆清单","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"奁产归新家，器物归弦正馆。两份清单分开立，你这个人,走到哪都是两立的。","source":"宋人笔记所载产业分立之习。"},{"text":"把清单核了又核","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"核到三更，一笔不差。你跟账目打了半辈子交道，最后一本账,要最漂亮。","source":"宋代市井记账之习见宋人笔记。"}],"difficulty":1,"npc":[],"foreshadow":"传馆清单为part4弦正馆安排"},{"id":"B-072","branch":"B","stage":3,"day":72,"shichen":"辰时","checkpoint":"婚期·072辰","scene":"晨起纳征。聘礼进门，你的奁产出门，两担仪仗在州桥头碰了个正着——当年书肆的掌柜特意候在那里看，说这桥今日喜庆。","options":[{"text":"遣人谢掌柜多年照拂","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"掌柜的接过谢礼抹眼睛：我跑了半辈子腿，这条桥上的路，跑得最值。","source":"宋代纳征之礼见《宋史·礼志》及宋人笔记婚俗。"},{"text":"专注仪程无暇旁顾","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"仪程圆满，可掌柜在桥头站成了旧相识里的一个背影。礼数再满，也别忘了人。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜","媒婆"],"foreshadow":"桥头谢恩收通信线"},{"id":"B-072-未","branch":"B","stage":3,"day":72,"shichen":"未时","checkpoint":"婚期·072未","scene":"午后，鸨母与老乐工来帮你合婚期。两个老人翻了半天历书，争得面红耳赤，最后齐声问你：你的日子，你自己定。","options":[{"text":"定在他当年赠词的忌日","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"你定了首阕赠词送到樊楼的那一日。二老先愣后笑：这日子，黄历上没有,你们心里有。","source":"宋代婚期择吉之俗见宋人笔记所载。"},{"text":"依历书择个黄道吉日","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"日子是吉日，可你心里咯噔了一下——你们的婚期,该长在你们自己的故事里。","source":"同上。"}],"difficulty":2,"npc":["鸨母","老乐工"],"foreshadow":"婚期定于赠词之日"},{"id":"B-072-戌","branch":"B","stage":3,"day":72,"shichen":"戌时","checkpoint":"婚期·072戌","flavor":true,"scene":"夜里，婚期写进婚书，二老画押见证。散后你独坐灯下，把婚书单、纳吉帖、奁产清单一一理齐，装进一只新匣子——旧木匣,要退休了。","options":[{"text":"新旧两匣并排安放","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"旧匣装来路，新匣装去路。两只匣子并排一站，你的前半生和后半生就齐了。","source":"宋人笔记所载妆奁之制。"},{"text":"旧匣随身带入新家","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你决定旧匣不离身。那里有第一封字条、第一方墨——新家的镇宅之宝,是它。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"双匣意象为收官物阵"},{"id":"B-073","branch":"B","stage":3,"day":73,"shichen":"辰时","checkpoint":"传馆·073辰","scene":"晨起，婚前最后一课。十二弟子齐坐，你宣布：婚后弦正馆不辍，日常课务由小乐伎代领，你隔日亲授。馆中弦声，一日不断。","options":[{"text":"立代领章程授小乐伎","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"章程立毕，小乐伎郑重接印。你说：馆是大家的，我嫁了人,弦正馆不嫁人。","source":"宋人笔记所载民间馆学代领之俗。"},{"text":"只说照常未立章程","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"一句「照常」撑不起一个馆。你一出门,谁来定音、谁来考校,全成了糊涂账。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"代领章程为part4馆务线"},{"id":"B-073-未","branch":"B","stage":3,"day":73,"shichen":"未时","checkpoint":"传馆·073未","scene":"午后，弟子们抬出合送的贺礼：一副联名手卷，每人抄一句你教过的话。小乐伎抄的是馆训——「器认功夫，更认心正」。","options":[{"text":"收卷悬于馆内正壁","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":2},"feedback":"手卷挂上正壁，十二种字迹，一条心。往后进馆的人，先读这面墙。","source":"宋人笔记所载门生赠卷之俗。"},{"text":"谢过收入箱底珍藏","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"卷收进箱，弟子们的眼神暗了暗。他们送的不是字,是想挂在先生的日子里。","source":"同上。"}],"difficulty":2,"npc":["弦正馆学生"],"foreshadow":"馆训墙为弦正馆象征"},{"id":"B-073-戌","branch":"B","stage":3,"day":73,"shichen":"戌时","checkpoint":"传馆·073戌","flavor":true,"scene":"夜里，婚前最后一弹。你独自在院中，把这一生弹过的曲子从头到尾过了一遍：《婆罗门》、《凉州》、《定风波》、《满州桥雪》。弦声落处，皆是来路。","options":[{"text":"以《满州桥雪》收尾","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"最后一音落定，夜静如水。这支曲子从脱籍陪到出阁——明夜之后,有人同听了。","source":"宋人词话所载以乐述怀之习。"},{"text":"将曲目写进教馆总谱","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"总谱编成，你的一生在谱上排成了课。往后学生弹到某曲,就弹到了你的某年。","source":"宋代乐谱编订之习见宋人笔记。"}],"difficulty":1,"npc":[],"foreshadow":"馆用总谱为技艺线总结"},{"id":"B-074","branch":"B","stage":3,"day":74,"shichen":"辰时","checkpoint":"宜弦·074辰","scene":"晨起，亲迎前夜，姐妹们挤满了小院。资深歌伎坐镇指挥，还账姐妹管宴席，樊楼旧人各有差事——这不像办喜事，像当年樊楼打一场硬仗。","options":[{"text":"笑看众人忙碌不插手","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"你坐在廊下调弦。她们喊：新娘子不许动手！这一院的热闹,是你半生攒的。","source":"宋人笔记所载亲迎前夜乡邻相助之俗。"},{"text":"卷起袖子一同张罗","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你被姐姐按回椅子上：今日你只管坐着。有些人情,要学会心安理得地受。","source":"同上。"}],"difficulty":1,"npc":["资深歌伎","还账姐妹","樊楼姐妹"],"foreshadow":"众姐妹执事,婚礼成局"},{"id":"B-074-未","branch":"B","stage":3,"day":74,"shichen":"未时","checkpoint":"宜弦·074未","scene":"午后，他那边遣人送来亲迎的仪程单，末尾附了一行小字：明夜合卺后，请新娘子为一阕新词定谱——词名《宜弦》，是给你的。","options":[{"text":"连夜为《宜弦》起谱","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"谱到「宜室宜家宜弦歌」一句,你的指尖顿了顿。这一阕,要唱一辈子的。","source":"宋代婚词之体见宋人词话所载。"},{"text":"回话说婚后再谱不迟","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"回话的人走了,你看着仪程单发怔。他讨的不是谱,是合卺夜的第一句话。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"《宜弦》为婚礼定情曲"},{"id":"B-074-戌","branch":"B","stage":3,"day":74,"shichen":"戌时","checkpoint":"宜弦·074戌","flavor":true,"scene":"前夜将尽，小院终于静下来。你立在门口看州桥方向的灯火——明夜此时，你要从这条路上走过去,带着两匣一琴,走进另一个人生。","options":[{"text":"对灯火轻声道别","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你对着这片看了半生的灯火福了一福。不是告别,是报喜：我要往前走了。","source":"《东京梦华录》载州桥夜市灯火之盛。"},{"text":"回屋再理一遍嫁妆","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"两匣一琴,三样不多。可你掂了掂,每一样都沉——都是拿命挣的分量。","source":"宋人笔记所载妆奁之制。"}],"difficulty":1,"npc":[],"foreshadow":"两匣一琴为出阁仪仗核心"},{"id":"B-075","branch":"B","stage":3,"day":75,"shichen":"辰时","checkpoint":"阶段三收官·075辰","scene":"收官日,亲迎。晨起鼓乐至门,他一身吉服立于阶下。你着姐姐送的新衣改制的嫁衣,簪着及笄的素银簪,怀抱琵琶,出了弦正馆的门。","options":[{"text":"抱琴登轿,堂堂正正","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":2},"feedback":"抱琵琶上花轿,满汴京头一份。有人笑不合规矩,更多人喝彩：这才是弦正馆主。","source":"宋代亲迎之礼见《东京梦华录》及宋人笔记所载婚俗。"},{"text":"依俗携常规仪物","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"规规矩矩登轿,人人都说好。可你摸了摸空荡荡的手——琵琶没带,像少了半条命。","source":"同上。"}],"difficulty":3,"npc":["落魄词人","资深歌伎","媒婆"],"foreshadow":"抱琴出阁为全线名场面"},{"id":"B-075-未","branch":"B","stage":3,"day":75,"shichen":"未时","checkpoint":"阶段三收官·075未","scene":"午后行礼。高堂位上坐着鸨母与老乐工,资深歌伎在侧,十二弟子掌乐。三拜礼成,满座皆泣——这一场婚礼,没有一个是旁观者。","options":[{"text":"拜罢向众人团团一揖","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"一揖谢满座。你说:今日无高堂,可我有满座的亲人。鸨母的眼泪终于没绷住。","source":"宋代婚礼拜堂之仪见宋人笔记所载婚俗。"},{"text":"依礼退席直入洞房","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"礼是成了,可满座的话还没谢。这些人陪你打了半生仗,一句话不能省。","source":"同上。"}],"difficulty":3,"npc":["鸨母","老乐工","资深歌伎","弦正馆学生"],"foreshadow":"满座亲人为人情线总结"},{"id":"B-075-戌","branch":"B","stage":3,"day":75,"shichen":"戌时","checkpoint":"阶段三收官·075戌","flavor":true,"scene":"收官之夜。宾客散尽,新宅灯暖。他铺开《宜弦》词稿,你抱起随嫁的琵琶。窗外州桥的灯火遥遥在望,窗内两匣并放,旧帕压底。","options":[{"text":"弹《宜弦》,合卺同听","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"曲至「宜室宜家宜弦歌」,他轻声相和。从州桥书肆到今夜,一词一谱,终成眷属。","source":"宋代婚词唱和之雅见宋人词话所载。"},{"text":"先合弹《满州桥雪》","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"先弹来路,再谱前程。雪满州桥的那年他们不相识,今夜桥上的灯,是他们的了。","source":"《东京梦华录》载州桥形胜;宋人词话所载琴瑟和鸣之喻。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"词谱唱和入新家,part4新章"},{"id":"B-076","branch":"B","stage":4,"day":76,"shichen":"辰时","checkpoint":"新婚开卷·076辰","scene":"婚后第一晨。新宅小院里，你照旧卯时起身调弦。他披着衣出来看，笑道：还以为新娘子头三日不碰琴。你答：弦正馆的先生，没有头三日。","options":[{"text":"新婚不废晨课","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"弦声照常响起，他搬了凳子坐在廊下听。好的婚姻,是两个江山互不打扰又彼此听得见。","source":"宋人笔记所载新妇持家与业艺不辍之习。"},{"text":"依俗歇业三日","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"歇到第二日你就浑身不自在。手里的弦停了,心里的弦就松了——这不是你。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"婚后不辍业为新章定调"},{"id":"B-076-未","branch":"B","stage":4,"day":76,"shichen":"未时","checkpoint":"新婚开卷·076未","scene":"午后回馆视事。三日不见，馆务井然——小乐伎代领得有板有眼，馆训墙下弟子们晨课未断。她交还代领印信时，手有点抖。","options":[{"text":"赞其三日之功再收印","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"你先夸后收：三日无一丝走板,这印你拿得起。她眼眶一热,把印捧得更稳了。","source":"宋人笔记所载师门代领之俗。"},{"text":"默默收印查验账目","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"印收回,账查清,样样都对。可她退下去时背影发紧——功劳不夸,人心会凉。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"代领印信为弟子权责线"},{"id":"B-076-戌","branch":"B","stage":4,"day":76,"shichen":"戌时","checkpoint":"新婚开卷·076戌","flavor":true,"scene":"夜里,新宅第一次亮满灯。他研墨你调弦,各做各的事,偶尔抬头相视一笑。墙上「弦歌在兹」与「德音不忘」静静相对。","options":[{"text":"灯下合校《宜弦》谱","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"一个词一个字地磨,一句弦一个音地校。新婚的第一件功课,是两个人合写后半生。","source":"宋人词话所载夫妇校词之雅。"},{"text":"由他讲官署第一日","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他讲同僚,讲案牍,讲衙门里的旧规矩。你听着剥橘子——烟火气,也是唱和。","source":"宋人笔记所载官员初任日常。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"灯下各业为婚姻日常底色"},{"id":"B-077","branch":"B","stage":4,"day":77,"shichen":"辰时","checkpoint":"馆规·077辰","scene":"晨起,馆中出了第一件烦心事:有弟子练功偷懒,被小乐伎按馆规罚抄谱,那弟子不服,嚷着「你不过是比我早进门,凭什么管我」。","options":[{"text":"挺小乐伎按馆规办","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你当众说:馆规认功夫不认年齿,她代领一日,规矩就是她的。偷懒弟子低头服了。","source":"宋人笔记所载塾学馆规之俗。"},{"text":"和稀泥各打五十大板","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"罚也罚了,哄也哄了,可小乐伎眼里的光暗了——规矩让先生和稀泥,代领就成了空印。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","偷懒弟子"],"foreshadow":"馆规权威为弟子冲突线核心"},{"id":"B-077-未","branch":"B","stage":4,"day":77,"shichen":"未时","checkpoint":"馆规·077未","scene":"午后,那被罚的弟子练完抄谱来见你,眼眶通红,说自己不是懒,是家里嫌她学琵琶没出息,断了她的饭。","options":[{"text":"问明家情替她设法","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你出面与其家中长谈,又免了她半月束脩。她抹泪练琴去了——规矩硬,心要软。","source":"宋人笔记所载贫家子弟向学之艰。"},{"text":"只按馆规不予通融","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"规矩是守住了,三日后那弟子再没来。你后来才知道,她被家里送去了针线铺。","source":"同上。"}],"difficulty":3,"npc":["偷懒弟子"],"foreshadow":"寒门弟子为馆务情义线"},{"id":"B-077-戌","branch":"B","stage":4,"day":77,"shichen":"戌时","checkpoint":"馆规·077戌","flavor":true,"scene":"夜里你与他说起弟子的事。他听完放下笔,说他官署里也有这样的小吏——规矩压人易,规矩护人难。你们对了半天各自的「管人经」。","options":[{"text":"约定各自守住柔处","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"灯下约定:他护他的小吏,你护你的弟子。两个衙门,一种心肠。","source":"宋人笔记所载吏治宽严之辨。"},{"text":"笑他妇人之仁不如你","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他不服,搬出他放走一个误期小吏的旧事反驳。争到最后,俩人都笑了。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"宽严之辨呼应官途线"},{"id":"B-078","branch":"B","stage":4,"day":78,"shichen":"辰时","checkpoint":"校谱·078辰","scene":"晨起,《霓裳》残谱的校补提上日程。你把秘本、残谱、多年小谱摊了一桌,老乐工闻讯赶来,颤着手抚过残谱:今日起,老朽给你打下手。","options":[{"text":"与老乐工立校谱之约","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"约定每旬一会,你校他核。老人临出门说:四十年了,这曲子终于有人当真了。","source":"《霓裳羽衣曲》唐宋流变与辑佚见《碧鸡漫志》。"},{"text":"独自校补不愿劳烦他","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老人怏怏而去。古曲是几百年的接力,一个人跑到黑,跑不完的。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"旬会校谱为技艺线主轴"},{"id":"B-078-未","branch":"B","stage":4,"day":78,"shichen":"未时","checkpoint":"校谱·078未","scene":"午后首次校谱,残谱第三页有半行漫漶不清,你与老乐工各执一说,争了整整一个时辰,谁也压不服谁。","options":[{"text":"两说并存,试弹定夺","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"两种补法都弹了十遍,到底你的顺耳。老人痛快认输:弦比人诚实。","source":"《碧鸡漫志》所载以器验谱之法。"},{"text":"让着老人依他的说","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"补完试弹,那半行怎么听怎么别扭。敬老敬在心里,不敬在错音里。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"「弦比人诚实」为校谱准则"},{"id":"B-078-戌","branch":"B","stage":4,"day":78,"shichen":"戌时","checkpoint":"校谱·078戌","flavor":true,"scene":"夜里,你补出的第一个完整段落在他书房的灯下弹给他听。他听完半晌,说:这曲子几百年没人听全了——今夜我听见的是古人,也是你。","options":[{"text":"请他为此段题词","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":1,"才华":1},"feedback":"他提笔写下数行,题曰《闻霓裳初段》。古曲新词,在这个书房里又活了一世。","source":"宋人词话所载闻乐题词之雅。"},{"text":"把录音心得记入校谱册","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"册上记:某段补成,某人初听。往后若传下去,听曲的人也算入谱了。","source":"宋代乐谱校订著录之习见宋人笔记。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"《闻霓裳》题词入《往来集》"},{"id":"B-079","branch":"B","stage":4,"day":79,"shichen":"辰时","checkpoint":"刊集议·079辰","scene":"晨起,书肆掌柜登门,郑重提起《往来集》刊行之事:书商愿出资刻印,但有个条件——删去集中涉及「樊楼」「乐籍」的字样,「免得惹眼」。","options":[{"text":"一字不删,宁可换书商","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":2},"feedback":"你答:来路二字就是这部集的骨头,删了它,书就别出了。掌柜的击节:我去回绝!","source":"宋代刻书删改之习见宋人笔记所载书坊旧例。"},{"text":"斟酌删改以求刊行","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"删样送回来,你翻到「樊楼」变「歌楼」那页,手抖了。自己的来路,自己先不敢认。","source":"同上。"}],"difficulty":3,"npc":["书肆掌柜"],"foreshadow":"删改之争为刊行风波主线"},{"id":"B-079-未","branch":"B","stage":4,"day":79,"shichen":"未时","checkpoint":"刊集议·079未","scene":"午后,他下值回来听闻此事,把公文一放:我俸禄虽薄,刻一部书还出得起。自家刻,自家印,一个字都不许别人动。","options":[{"text":"商议合资自刻自印","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你出奁产盈余,他出俸禄,掌柜出门路。《往来集》的底页要刻上:此书不删一字。","source":"宋代私家刻书之盛见宋人笔记所载。"},{"text":"由他独资以全其志","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他执意全出,你执意不肯——争到最后他还是拗不过你:合署的书,哪有独出的理。","source":"同上。"}],"difficulty":2,"npc":["落魄词人","书肆掌柜"],"foreshadow":"自刻自印,刊行线自主定调"},{"id":"B-079-戌","branch":"B","stage":4,"day":79,"shichen":"戌时","checkpoint":"刊集议·079戌","flavor":true,"scene":"夜里,你们把《往来集》的书稿一页页理齐校订。翻到最初那阕书肆赠词,他忽然念出声,念到一半笑了:当年写得真嫩。","options":[{"text":"答:嫩才要收,那是来路","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他郑重点头,把「嫩」词排在卷首。一部书敢把青涩放在最前面,才撑得起往后。","source":"宋代词集编次存真之习见宋人词话。"},{"text":"为他的自序拟个题","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你拟的题是《弦上来路》。他拍案:四个字把两个人的半生都装下了。","source":"宋人笔记所载书序命名之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"卷首存真为刊集风骨"},{"id":"B-080","branch":"B","stage":4,"day":80,"shichen":"辰时","checkpoint":"馆务新章·080辰","scene":"馆务新章日。晨起你重立馆约:添贫家减免之条、立月课赏罚之格、定代领轮值之制。十二弟子围观新榜,小乐伎第一个署名。","options":[{"text":"新榜张于馆训墙下","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"新约与馆训并排挂着,一刚一柔。弟子们说:这馆子如今像个正经书院了。","source":"宋代民间塾学学规之俗见宋人笔记。"},{"text":"口头宣布不立文字","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"口说的规矩,过月就松。你看着馆训墙想:字不落地,训就是空的。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"新馆约为馆务线制度化"},{"id":"B-080-未","branch":"B","stage":4,"day":80,"shichen":"未时","checkpoint":"馆务新章·080未","scene":"午后,减免之条刚立,就有殷实人家托人来问:我家可否也沾个减免?来人笑得热络,说「都是街坊」。","options":[{"text":"按条核验,不合则拒","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你请其照条自陈,来人支吾而去。条例立得住,全在第一次有人说「不」。","source":"宋人笔记所载学规执行之难。"},{"text":"碍于情面破例一次","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"例一破,贫家孩子来问时你张不开嘴了。规矩最贵的部分,是没有例外。","source":"同上。"}],"difficulty":3,"npc":["殷实人家仆从"],"foreshadow":"条例无例外为馆誉根基"},{"id":"B-080-戌","branch":"B","stage":4,"day":80,"shichen":"戌时","checkpoint":"馆务新章·080戌","flavor":true,"scene":"夜里,贫家弟子遣其母送来一篮自家蒸的炊饼谢恩。你收了饼,回赠一册抄谱。她母亲说:闺女回家嘴里全是「先生说」。","options":[{"text":"与师母话家常至夜深","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"炊饼就着粗茶吃了两个。这样的谢意,比束脩重——它记得你护过的人。","source":"《东京梦华录》载汴京饼食与市井往来之俗。"},{"text":"把此事记进馆务册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"册上记:某生减免,其家谢饼。馆的账不只有钱,还有人情这一页。","source":"宋人笔记所载记事册之习。"}],"difficulty":1,"npc":["贫家弟子之母"],"foreshadow":"炊饼人情为馆中暖色"},{"id":"B-081","branch":"B","stage":4,"day":81,"shichen":"辰时","checkpoint":"攻坚·081辰","scene":"晨起,《霓裳》校补进至中卷,一处转调卡了三日——残谱此处的记号,与你所知的一切指法都对不上。老乐工也摇头:这一段,怕是世上没人弹过了。","options":[{"text":"翻遍旧谱另寻旁证","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"三日三夜,你在一册唐人的旧抄里找到同类记号。转调豁然贯通,老人击案而歌。","source":"唐宋琵琶谱字记号之流变见《碧鸡漫志》及《乐府杂录》。"},{"text":"跳过此处先补后文","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"绕是绕过去了,可那个记号像根刺,扎在你心里。古曲最险的坎,绕不过。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"唐人旧抄为校谱新据"},{"id":"B-081-未","branch":"B","stage":4,"day":81,"shichen":"未时","checkpoint":"攻坚·081未","scene":"午后,贯通后的中卷第一次完整试弹。小乐伎在窗外偷听了全程,进来时眼睛通红:先生,我刚才好像看见几百年前的教坊了。","options":[{"text":"许她抄习中卷新谱","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"她抱着抄本的手在抖。你说:看得见的教坊,要从你们这代人手里活过来。","source":"宋代乐谱传习见宋人笔记。"},{"text":"令她专心本业勿分心","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"她唯唯退下,一步三回头。最好的苗子碰见最好的曲子,拦她是耽误两个人。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"中卷传弟子,传承升级"},{"id":"B-081-戌","branch":"B","stage":4,"day":81,"shichen":"戌时","checkpoint":"攻坚·081戌","flavor":true,"scene":"夜里,他下值带回一包糖霜,说衙门同僚分的新样果子,他舍不得吃带回来了。两人就着你新补的古曲,分食一包糖霜。","options":[{"text":"笑他堂堂官员藏零食","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他振振有词:官袍里揣糖霜,也是为你练的胆。一包甜,吃出了少年夫妻的味道。","source":"《东京梦华录》载汴京果食糖霜之俗。"},{"text":"留一半给明日的他","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"油纸包好放回他书案。你爱我这件事,从来不说,只留一半糖。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"糖霜小事为婚姻暖色"},{"id":"B-082","branch":"B","stage":4,"day":82,"shichen":"辰时","checkpoint":"开雕·082辰","scene":"晨起,刻工进场,《往来集》开雕。掌柜的领着工匠,你一页页交付书稿,交付到「樊楼」二字那页,特意停了一停——这页,原样上版。","options":[{"text":"亲监首版试印样张","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"样张出来,「樊楼」二字端端正正。掌柜的说:这两个字上版,这书就有骨头了。","source":"宋代雕版印刷之盛见《东京梦华录》及宋人笔记。"},{"text":"全权托付掌柜监工","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"样张送来一看,「乐籍」二字墨色浅了三分——工匠下意识的手软,也是世道的手软。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜","刻工"],"foreshadow":"原样上版为刊行风骨落地"},{"id":"B-082-未","branch":"B","stage":4,"day":82,"shichen":"未时","checkpoint":"开雕·082未","scene":"午后,开雕的消息传开,先前那家被回绝的书商放出话来:删改的书都卖不动,何况不删的——这部集子,注定要压在库里喂虫。","options":[{"text":"不辩,专心校样","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你一头扎进校样里。书还没印,吵什么都早——成书那日,自有人替它说话。","source":"宋人笔记所载书坊同业相轻之习。"},{"text":"著文回击书商狂言","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"文章一出去,对方乐得接招,两部未出世的书先打了场笔墨官司,白送他名声。","source":"同上。"}],"difficulty":2,"npc":["失意书商"],"foreshadow":"压库之讥为刊行反转蓄势"},{"id":"B-082-戌","branch":"B","stage":4,"day":82,"shichen":"戌时","checkpoint":"开雕·082戌","flavor":true,"scene":"夜里,首卷样张装订成一册试本,你们俩在灯下从头读到尾。读到最后,他合上册子说:往后我们的孩子,要读的第一本书就是它。","options":[{"text":"答:先教他读「樊楼」二字","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"他一怔,随即重重点头。来路讲得越早,孩子的腰杆直得越早。","source":"宋人笔记所载课子读书之习。"},{"text":"试本收入新匣作首藏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"新匣第一藏,不是金银,是这部还带着墨香的试本。这家的家风,从第一页立起。","source":"宋人笔记所载藏书之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"试本首藏为家学伏笔"},{"id":"B-083","branch":"B","stage":4,"day":83,"shichen":"辰时","checkpoint":"拒署·083辰","scene":"晨起,他官署里出了事:一桩陈年亏空案翻出来,上司欲让新来的他署名担责,许以「他日照拂」。他回家说与你听,问你主意。","options":[{"text":"答:字一署,就不是你的官了","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你说:当年我的账笔笔清白,你的署名也要笔笔清白。他拱手:夫人之言,正合吾心。","source":"宋代官吏连署担责之制见《宋史·职官志》及宋人笔记所载。"},{"text":"劝他忍辱暂署名保身","correct":false,"tags":["情缘"],"dims":{"情缘":0},"feedback":"话出口你自己先悔了。当年你不卖一辈子,如今怎能劝他卖一个署名。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"拒署亏空案为官途暗礁"},{"id":"B-083-未","branch":"B","stage":4,"day":83,"shichen":"未时","checkpoint":"拒署·083未","scene":"午后,他回署当面辞了署名,上司拂袖。当晚,官署里便有了冷遇:分派给他的,全是没人肯碰的烂账旧卷。","options":[{"text":"宽慰他:烂账里出能吏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你给他烫了酒:当年没人肯唱的词我唱红了,没人肯理的账,你也能理清。","source":"宋人笔记所载能吏清理积案之事。"},{"text":"替他愤懑骂上司不公","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"骂了半宿,气是顺了,可他被你的怒火烧得更燥。家里的火,该是用来暖他的。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"清理积案为官途转机线"},{"id":"B-083-戌","branch":"B","stage":4,"day":83,"shichen":"戌时","checkpoint":"拒署·083戌","flavor":true,"scene":"夜里,他在灯下翻那堆烂账,你在另一头校《霓裳》。两盏灯各亮各的,偶尔他念一个数目,你弹一个音——谁也没说话,谁也没孤单。","options":[{"text":"以弦声应和算珠声","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"算珠噼啪,琵琶叮咚,书房里像合奏。旁人看不见的婚姻,长在这些声响里。","source":"宋人笔记所载夜治文书之习。"},{"text":"煮宵夜看他吃完再睡","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一碗热汤面下肚,他说今日的账都顺了些。你笑:是我的面顺,不是你的账顺。","source":"《东京梦华录》载汴京食面之俗。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"双灯夜课为婚姻名景"},{"id":"B-084","branch":"B","stage":4,"day":84,"shichen":"辰时","checkpoint":"传火·084辰","scene":"晨起,馆中来了位稀客:致仕老官员的女儿——如今是你的学生了——说她父亲读了《往来集》的传抄稿,在家感叹了一夜,想见见写序的人。","options":[{"text":"请他过馆与老先生一见","correct":true,"tags":["名声","情缘"],"dims":{"名声":2,"情缘":1},"feedback":"两位素昧平生的人因一册书稿谈了一下午。老先生临别说:汴京有幸,存此一书。","source":"宋人笔记所载士人以文会友之雅。"},{"text":"代为辞谢免生枝节","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"辞得太快,老先生以为你们清高傲客。一部想传世的集子,不该怕见人。","source":"同上。"}],"difficulty":2,"npc":["官员之女学生","落魄词人"],"foreshadow":"老先生评语为刊行口碑前哨"},{"id":"B-084-未","branch":"B","stage":4,"day":84,"shichen":"未时","checkpoint":"传火·084未","scene":"午后,资深歌伎姐姐来馆,吞吞吐吐半天才说:她攒够了钱,想脱籍了,来向你讨当年的「来路册」做参照。","options":[{"text":"赠册并亲授脱籍章程","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"册子摊开,你逐条讲给她听,讲到中人、律条、账目,她边记边掉泪。","source":"宋代乐户自赎脱籍程序见《宋刑统》及宋人笔记。"},{"text":"只赠册让她自己琢磨","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"册子是好册子,可当年你差点栽在一个「疑」字上——有些坑,得亲口指给她看。","source":"同上。"}],"difficulty":3,"npc":["资深歌伎"],"foreshadow":"姐姐自赎为来路册复用"},{"id":"B-084-戌","branch":"B","stage":4,"day":84,"shichen":"戌时","checkpoint":"传火·084戌","flavor":true,"scene":"夜里,你送姐姐出门,看她的背影走进州桥方向的灯火里。当年她教你「分寸二字值千金」,今日你教她律条账目——樊楼的情义,就这样一代传一代。","options":[{"text":"回来把这段话讲给他听","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他听完说:你们这不叫报恩,叫传火。你想了想,把这四个字记进了馆务册。","source":"宋人笔记所载薪火相传之喻。"},{"text":"在来路册末添一赠记","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"册末添:某年月日,此册转授樊楼旧姐。册子会老,册里的路会越走越宽。","source":"宋人笔记所载记事册之习。"}],"difficulty":1,"npc":["资深歌伎","落魄词人"],"foreshadow":"「传火」二字为馆训补充"},{"id":"B-085","branch":"B","stage":4,"day":85,"shichen":"辰时","checkpoint":"馆训考验·085辰","scene":"考验日。晨起,馆中来了一位豪富,携重礼求女儿免试入馆,被小乐伎按新馆约挡在门外。豪富恼羞成怒,放话要让你这馆子开不下去。","options":[{"text":"支持小乐伎,按约再拒","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":2},"feedback":"你当众复述馆约,一条一条念给豪富听。他拂袖而去,馆训墙下弟子们挺直了腰。","source":"宋人笔记所载学规抗颜之事。"},{"text":"亲自出面缓和周旋","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你一打圆场,小乐伎的脸就白了——先生的圆场,就是拆她的台。","source":"同上。"}],"difficulty":3,"npc":["豪富","小乐伎学生"],"foreshadow":"豪富之怒为馆务外患伏笔"},{"id":"B-085-未","branch":"B","stage":4,"day":85,"shichen":"未时","checkpoint":"馆训考验·085未","scene":"午后,豪富果然动手:他买通牙人,四处放话说弦正馆「收徒看钱、名不副实」。可这一回,不等你们辩,学生家长们先站了出来。","options":[{"text":"由家长口碑自行澄清","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"贫家之母提着炊饼篮子当众讲减免,富室家长讲同弦同课。谣言三日自溃。","source":"宋人笔记所载市井口碑之力。"},{"text":"出面逐条驳斥谣言","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你自己下场,倒显得急了。其实那些你护过的人,早替你备好了千言万语。","source":"同上。"}],"difficulty":3,"npc":["豪富","贫家弟子之母"],"foreshadow":"口碑护城,馆誉大成"},{"id":"B-085-戌","branch":"B","stage":4,"day":85,"shichen":"戌时","checkpoint":"馆训考验·085戌","flavor":true,"scene":"夜里,弟子们凑份子给馆训墙重新装裱,「器认功夫,更认心正」八个字焕然一新。小乐伎说:今日我才算真懂了这八个字。","options":[{"text":"问她今日懂在何处","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"她说:功夫让人进得来,心正让人守得住。你点头——这馆,可以放心交给下一代了。","source":"宋人笔记所载师门心法相传之习。"},{"text":"与弟子们新榜前合影","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"装裱匠笑问你们是什么字号,弟子们齐声答:弦正馆!声音亮得惊起了邻家的狗。","source":"宋人笔记所载市井装裱之俗。"}],"difficulty":1,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"馆训内化,弟子线成熟"},{"id":"B-086","branch":"B","stage":4,"day":86,"shichen":"辰时","checkpoint":"跋文·086辰","scene":"晨起,《往来集》雕版过半,掌柜的送来喜讯:清直士人读了传抄稿,主动愿为集子作跋——跋文标题就叫《不删一字跋》。","options":[{"text":"拜领跋文置于卷末","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"跋文读罢,你与他对坐无言。「不删一字」四字,把你们死守的东西说尽了。","source":"宋代文集序跋之体见宋人笔记所载。"},{"text":"谦辞恐累士人清名","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"士人回信只一句:为这样一部书作跋,是清名之幸,何累之有。你惭愧受之。","source":"同上。"}],"difficulty":2,"npc":["清直士人","书肆掌柜"],"foreshadow":"《不删一字跋》为刊集定音"},{"id":"B-086-未","branch":"B","stage":4,"day":86,"shichen":"未时","checkpoint":"跋文·086未","scene":"午后,先前讥你们「压库喂虫」的书商悄悄遣人来,想订一百部——他门下书肆的主顾们,已经开始打听这部「一字不删」的集子了。","options":[{"text":"按市价供书不究前言","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"书照供,价不抬,话不提。掌柜的替你痛快:这口气,是用一百部订单挣回来的。","source":"宋代书坊行销之俗见宋人笔记所载。"},{"text":"拒其订单以报旧讥","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"订单拒了,痛快了一时。可掌柜的算给你听:一百部出去,就是一百处替你说话的人。","source":"同上。"}],"difficulty":2,"npc":["失意书商"],"foreshadow":"百部订单为刊行反转"},{"id":"B-086-戌","branch":"B","stage":4,"day":86,"shichen":"戌时","checkpoint":"跋文·086戌","flavor":true,"scene":"夜里,印书的墨香从窗缝钻进来——刻坊就在隔壁街。他抽着鼻子说:别人家是炊烟香,我们家是墨香。你答:墨香也是烟火气。","options":[{"text":"以墨香为题戏填一词","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你随口哼了个调子,他随口和了几句。戏作不上集,可这一夜的墨香记住了。","source":"宋人词话所载即兴联句之乐。"},{"text":"商量样书先送何人","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"头三部样书定下来:老乐工、鸨母、姐姐。排在前面的,永远是陪你走过夜路的人。","source":"宋人笔记所载新书馈赠之俗。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"样书三赠收束旧恩"},{"id":"B-087","branch":"B","stage":4,"day":87,"shichen":"辰时","checkpoint":"残页·087辰","scene":"晨起,《霓裳》校补至末卷,只剩最后三行。可这三行比前面全部加起来都难——残损最重,记号最古,老乐工抚谱长叹:就看这一哆嗦了。","options":[{"text":"缓三日静心再攻坚","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你停了弦,读了三日古人论乐的书。第三夜,最后两行忽然通了——就差一行。","source":"《碧鸡漫志》所载研乐求索之苦。"},{"text":"乘勇一鼓作气强补","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"硬补的三行试弹出来,气韵全断。古曲的最后一哆嗦,最忌「差不多」。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"末行未竟为技艺线留白"},{"id":"B-087-未","branch":"B","stage":4,"day":87,"shichen":"未时","checkpoint":"残页·087未","scene":"午后,老乐工带来一个消息:教坊旧档里可能还有一页《霓裳》的旁支残谱,在一位流落外州的老乐师手里,他已去信恳请借阅。","options":[{"text":"备束脩亲书求借信","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"你的信写得不卑不亢,附上新补中卷为证:持谱之人,当见续谱之心。","source":"宋人笔记所载乐人互通谱牒之俗。"},{"text":"托人重金求购残页","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"重金一去,对方反而起了疑:是续曲还是倒卖?宝物的门,只能用同道的心敲。","source":"同上。"}],"difficulty":3,"npc":["老乐工","外州老乐师"],"foreshadow":"外州残页为终章最大悬念"},{"id":"B-087-戌","branch":"B","stage":4,"day":87,"shichen":"戌时","checkpoint":"残页·087戌","flavor":true,"scene":"夜里,求借的信发出去了。你立在院中看南方的夜空,想那位素未谋面的老乐师——几百年的一支曲子,如今系在几个白发人的信上。","options":[{"text":"把这段心事弹给他听","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他听完说:古人散了四百年,你们要把他们聚回来——这件事本身就值得写词。","source":"宋人词话所载以乐寄慨之习。"},{"text":"在校谱册记待页之盼","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"册上留白一页,题「待续」。你忽然觉得,人生最好的状态也就是这两个字。","source":"宋人笔记所载校雠著录之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「待续」一页直通终章"},{"id":"B-088","branch":"B","stage":4,"day":88,"shichen":"辰时","checkpoint":"姐姐赎·088辰","scene":"晨起,姐姐自赎的事有了眉目:律条备齐、中人找好,就缺一笔不大不小的尾款。她不肯开口,是来串门的还账姐妹替你问出来的。","options":[{"text":"以借代赠立字据","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你立据出借,一分利不要,但字据要立。姐姐含泪笑:你当年借我的规矩,原样还我。","source":"宋代民间借贷立约之俗见宋人笔记。"},{"text":"直接赠金不让她还","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"金子塞过去,她的脸白了:你这是可怜我。救命的钱和施舍的钱,差一个字,差一生。","source":"同上。"}],"difficulty":3,"npc":["资深歌伎","还账姐妹"],"foreshadow":"借据互助为姐妹线闭环"},{"id":"B-088-未","branch":"B","stage":4,"day":88,"shichen":"未时","checkpoint":"姐姐赎·088未","scene":"午后,你陪姐姐去办最后的手续。当年你走过的那条路,如今一步一步替她踩平:哪扇门的书吏要什么,哪个环节会卡什么,你门儿清。","options":[{"text":"全程陪同逐关指点","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"书吏见你陪同,一句刁难都不敢有。你走过的路,如今成了别人的桥。","source":"宋代乐户脱籍程序见《宋刑统》及宋人笔记。"},{"text":"指点后让她独自去办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"章程都讲了,可她临到门口还是发怵。有些门,第一次要有人陪着进。","source":"同上。"}],"difficulty":2,"npc":["资深歌伎","乐籍司书吏"],"foreshadow":"姐姐脱籍在即"},{"id":"B-088-戌","branch":"B","stage":4,"day":88,"shichen":"戌时","checkpoint":"姐姐赎·088戌","flavor":true,"scene":"夜里,姐姐捎来口信:文书过了,成了。你怔了半晌,想起她当年在樊楼后院教你「分寸二字值千金」的那个夜晚,眼眶忽然热了。","options":[{"text":"连夜弹曲为姐姐贺","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"曲子顺着墙头飘出去,半个巷子都听见了。她一定知道,这一曲是给她的。","source":"宋人词话所载以乐相贺之习。"},{"text":"在馆务册记下此事","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"册上记:某年月日,樊楼旧姐脱籍。这一页挨着当年你自己的那一页。","source":"宋人笔记所载记事册之习。"}],"difficulty":1,"npc":[],"foreshadow":"姐妹同脱籍,樊楼线圆满"},{"id":"B-089","branch":"B","stage":4,"day":89,"shichen":"辰时","checkpoint":"翻案·089辰","scene":"晨起,他带回了烂账旧卷的第一个成果:三个月,陈年亏空案被他理出了真账目——原来亏空另有其人,上司当年的「照拂」是要他替人顶罪。","options":[{"text":"贺他并问如何处置","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他说已按律呈报,不避不纵。你替他斟茶:当年不署名,今日才署得动这份呈文。","source":"宋代官吏稽核积案之制见宋人笔记所载。"},{"text":"只问上司会否报复","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你问得忧心忡忡,他答得轻描淡写。可你知道,往后几日你要盯着他上下值的路。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"顶罪案翻为官途大转"},{"id":"B-089-未","branch":"B","stage":4,"day":89,"shichen":"未时","checkpoint":"翻案·089未","scene":"午后,风向果然变了:真亏空者被劾,当初压他的上司调离。署中同僚看他的眼神都不一样了——没人再敢塞烂账给这个「会理账的」。","options":[{"text":"嘱他胜后不骄不躁","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你只说了一句:当年我不踩落水之人,你也别踩。他郑重点头:家风如此。","source":"宋人笔记所载官場进退之戒。"},{"text":"设家宴庆贺扬眉吐气","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"宴席摆了,贺客来了,可你俩对视时都觉得闹得慌。你们的胜仗,从来是安静地赢。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"不骄之约呼应家风"},{"id":"B-089-戌","branch":"B","stage":4,"day":89,"shichen":"戌时","checkpoint":"翻案·089戌","flavor":true,"scene":"夜里,他在书房写日记,忽然叫你过去看。今日那页写着:「拒署之日,夫人一言;翻案之日,夫人亦一言。吾之前程,半在弦上。」","options":[{"text":"提笔在旁补批一句","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你批:「吾之弦声,半在案上。」两行字并排,像两个人在纸上也执了手。","source":"宋人笔记所载夫妇题跋之雅。"},{"text":"笑他日记写成了状纸","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他正色说:家事与国事,都要经得起后日回看。你笑着笑着,心里一热。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「半在弦上」为婚姻定评"},{"id":"B-090","branch":"B","stage":4,"day":90,"shichen":"辰时","checkpoint":"刊行风波·090辰","scene":"刊行日。《往来集》正式印成,三百部首发,书肆门口天不亮就排了队。掌柜的站在门楼上喊:不删一字的集子,今日出笼!","options":[{"text":"到场亲售首部样书","correct":true,"tags":["名声","自主"],"dims":{"名声":3,"自主":1},"feedback":"第一部卖给了一个赶早的穷学生,你亲笔题签。掌柜的说:这书的第一页,就该这么翻。","source":"宋代书肆发售新书之俗见《东京梦华录》。"},{"text":"避嫌不到场由掌柜主持","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你没去,排队的人里有人问:写书的两位先生呢?掌柜的替你答:在家校古谱——这答案,比到场更响。","source":"同上。"}],"difficulty":3,"npc":["书肆掌柜","穷学生"],"foreshadow":"刊行盛况为《往来集》收局"},{"id":"B-090-未","branch":"B","stage":4,"day":90,"shichen":"未时","checkpoint":"刊行风波·090未","scene":"午后,三百部半日售罄,加刻的版连夜开雕。那家删改书商的书果然压库了,他遣人来求代销你们的集子,姿态低到了尘埃里。","options":[{"text":"许其代销,约法三章","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"约法:原价、不删、不搭售。书商一一应下。赢到让对手按你的规矩卖书,才是真赢。","source":"宋代书坊代销之俗见宋人笔记。"},{"text":"拒其代销以惩前愆","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"拒是拒得痛快,可掌柜的算给你听:少一个代销,这部集子就少走多远的路。","source":"同上。"}],"difficulty":2,"npc":["失意书商","书肆掌柜"],"foreshadow":"约法代销为书业新规矩"},{"id":"B-090-戌","branch":"B","stage":4,"day":90,"shichen":"戌时","checkpoint":"刊行风波·090戌","flavor":true,"scene":"夜里,第一批印成的集子码在堂屋,墨香满室。你们各执一册,他读词,你读谱,读的是同一本书,也是同一段半生。","options":[{"text":"合签一册赠州桥","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"合签的样书供在正堂。掌柜的来贺,绕着看了三圈:这书往后是要传代的。","source":"宋人笔记所载夫妇合署之雅。"},{"text":"商议版税用途","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"议定:一半入弦正馆贫生减免。你们的书,挣的钱继续养穷孩子的弦。","source":"宋代刻书版润之俗见宋人笔记。"}],"difficulty":1,"npc":["落魄词人","书肆掌柜"],"foreshadow":"版润入馆为公益线伏笔"},{"id":"B-091","branch":"B","stage":4,"day":91,"shichen":"辰时","checkpoint":"余波·091辰","scene":"晨起,刊行大卖的消息惊动了更高处:有御史台的言官撰文,说官员之妻「抛头露面刊书售曲」,有失官箴。物议的余波,换了身衣裳又来了。","options":[{"text":"取「来路册」备质","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"册子仍在匣中,纸页已黄。你抚着它想:这些年它没动过,可它一在,我谁都不怕。","source":"宋人笔记所载存证备质之俗。"},{"text":"急请清直士人再辩","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"士人还未动笔,你已先慌了三分。底牌之所以是底牌,在于你不必次次亮。","source":"同上。"}],"difficulty":3,"npc":["言官"],"foreshadow":"官箴之议为余波主线"},{"id":"B-091-未","branch":"B","stage":4,"day":91,"shichen":"未时","checkpoint":"余波·091未","scene":"午后,不等你们回应,当年弦正馆护过的人先动了:贫家之母、富室家长、老官员、书肆掌柜,各从各处发声——弦正馆主何许人,汴京自己有嘴。","options":[{"text":"谢过众人仍不亲自下场","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"你一一致谢,始终未发一言。言官的文章在满城口碑里,泡了三日就软了。","source":"宋人笔记所载市井口碑与清议消长。"},{"text":"撰长文逐条驳斥言官","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"长文一出去,人们记住的不是你的道理,是你急了。有些仗,不亲自打才叫赢。","source":"同上。"}],"difficulty":3,"npc":["言官","书肆掌柜","贫家弟子之母"],"foreshadow":"不辩而胜为余波定音"},{"id":"B-091-戌","branch":"B","stage":4,"day":91,"shichen":"戌时","checkpoint":"余波·091戌","flavor":true,"scene":"夜里,他下值归来,第一句话是:今日署中有人替我担心,怕你受委屈。你怎么答?他把你的答案学给了同僚听。","options":[{"text":"答:委屈二字,我戒了","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"他学舌学得眉飞色舞,说同僚听完沉默了半晌,拱手说「尊夫人非常人」。","source":"宋人笔记所载夫妇问答之趣。"},{"text":"反问他如何回的","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他说:我答,内子半生风浪,这点涟漪她自己就当茶喝了。你笑出了声。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「戒了委屈」为心性定论"},{"id":"B-092","branch":"B","stage":4,"day":92,"shichen":"辰时","checkpoint":"面弹约·092辰","scene":"晨起,老乐工带来了外州老乐师的回信:残页允借,但有一条件——他要亲自听你弹一遍已校的段落,「谱不借给没听过它呼吸的人」。","options":[{"text":"应约,择日弹给老人听","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"回信即刻发出。老乐工抚掌:这才对——古曲的门,从来只用琴声敲。","source":"宋人笔记所载乐人互相考校之俗。"},{"text":"请先寄抄本再议面弹","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"回信慢了五日才来,语气淡了许多:抄本可议。宝物的缘分,先输给了怠慢。","source":"同上。"}],"difficulty":3,"npc":["老乐工","外州老乐师"],"foreshadow":"面弹之约直通终章考校"},{"id":"B-092-未","branch":"B","stage":4,"day":92,"shichen":"未时","checkpoint":"面弹约·092未","scene":"午后备战面弹之约,你把已校的全卷从头梳理,每个补音都重弹百遍。小乐伎在廊下听了三日,忽然说:先生这几日的弦,比往日更「老」了。","options":[{"text":"问她「老」在何处","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"她说:不慌,不躁,像知道背后站着几百年。你击节——这孩子,已经会听骨头了。","source":"宋人词话所载论乐品评之语。"},{"text":"笑而不答继续练琴","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"她挠头走了。最好的评语来自学生,你一句没接——教学相长的火,被你掐了。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"「弦老了」为技艺境界注脚"},{"id":"B-092-戌","branch":"B","stage":4,"day":92,"shichen":"戌时","checkpoint":"面弹约·092戌","flavor":true,"scene":"夜里,临行前夜,他帮你收拾琴匣。你忽然问他:若老人听完仍不肯借谱呢?他合上琴匣说:那就把你的《霓裳》弹给天下听,让他后悔。","options":[{"text":"笑答:你比我有狠劲","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"琴匣落锁。你忽然不怕了——不是因为有胜算,是因为输得起的人坐在你身边。","source":"宋人笔记所载夫妻问答之趣。"},{"text":"请他同行做个见证","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他二话不说告了假。他说:四百年的曲子要听新声,我这个填词的怎能不在场。","source":"宋代士人告假之俗见宋人笔记。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"夫妇同行为终章远足"},{"id":"B-093","branch":"B","stage":4,"day":93,"shichen":"辰时","checkpoint":"启程·093辰","scene":"晨起启程,赴外州。小乐伎代领馆务,送你到城门,递上一只布囊:里面是十二弟子每人写的一张字条,让你路上想家时拆。","options":[{"text":"收囊嘱其守好馆训","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你说:守好「心正」二字,就是替先生看家。她用力点头,直到你出城还在挥手。","source":"宋人笔记所载远行赠言之俗。"},{"text":"嘱咐功课便匆匆登车","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"车轮滚动,你回头望了一眼,她立在城门洞里,像一株还没长成的竹子。","source":"同上。"}],"difficulty":1,"npc":["小乐伎学生","落魄词人"],"foreshadow":"布囊字条为途中暖色"},{"id":"B-093-未","branch":"B","stage":4,"day":93,"shichen":"未时","checkpoint":"启程·093未","scene":"午后船行汴河,两岸风物倒退。他指着岸上一处渡口说,当年他赴京会试就是从这里上的船——如今两个人,一条船,反着走。","options":[{"text":"与他细数渡口旧事","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他说那日在此回望州桥,你说那日在馆中替他数路程。两段相思,在船上对上了。","source":"《东京梦华录》载汴河漕运渡口之盛。"},{"text":"只在船头看水不说话","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"水声哗哗,各想各的心事。难得同行的路,沉默着走完,可惜了这条河。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"汴河同舟为旅途唱和"},{"id":"B-093-戌","branch":"B","stage":4,"day":93,"shichen":"戌时","checkpoint":"启程·093戌","flavor":true,"scene":"夜泊荒村,舟外满天星斗。你拆开布囊第一张字条,是小乐伎的:「先生的弦,天下的谱。」你们就着船灯,一张张拆完了十二张。","options":[{"text":"逐张读出与他共赏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"读到最后一张,两人都没说话。船在河上轻轻晃,像晃着一个小小的家。","source":"宋人笔记所载舟中夜泊之景。"},{"text":"收好字条明日再读","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一夜拆一张,够拆到回程。弟子们的心意,要省着点用。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"布囊余温伴全程"},{"id":"B-094","branch":"B","stage":4,"day":94,"shichen":"辰时","checkpoint":"草堂·094辰","scene":"晨起抵外州,老乐师的住处在城郊竹林深处。老人开门,先不看你们,先看你怀里的琵琶——那上面有教坊旧器的弦轴。","options":[{"text":"双手呈琴请老人验","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"老人抚轴良久,说:认得,这是我师门的东西。门就此开了——琴比人先通了名。","source":"宋人笔记所载乐人认器相认之俗。"},{"text":"先递名帖再行通传","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"名帖递进去,老人慢条斯理看了半天。物件认得比帖子快——你险些绕了远路。","source":"同上。"}],"difficulty":2,"npc":["外州老乐师"],"foreshadow":"认器入门,同道相认"},{"id":"B-094-未","branch":"B","stage":4,"day":94,"shichen":"未时","checkpoint":"草堂·094未","scene":"午后竹林草堂,考校开始。你弹已校的《霓裳》全卷,老人闭目听完,一言不发,起身入内。你与他相视,手心都出了汗。","options":[{"text":"静候老人示下不催","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"半炷香后老人出来,捧出一页焦黄的纸:最后三行的旁支——它等的人,到了。","source":"宋人笔记所载乐人考校授谱之雅。"},{"text":"忍不住上前叩门求示","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"叩门声惊了竹林。老人开门时皱了眉:弹得古曲的人,怎的坐不住。险些坏事。","source":"同上。"}],"difficulty":3,"npc":["外州老乐师","落魄词人"],"foreshadow":"旁支残页到手,末行可补"},{"id":"B-094-戌","branch":"B","stage":4,"day":94,"shichen":"戌时","checkpoint":"草堂·094戌","flavor":true,"scene":"夜宿草堂,老人留饭。饭后三位老人般的乐人——其实是你们仨——围着残页坐到天亮,讨论那一行记号。他不懂乐,却替你们记了满纸的讨论。","options":[{"text":"谢他笔录成全此夜","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他说:四百年后的人考这段公案,会引用我的笔录——我也是古曲的传人了。","source":"宋人笔记所载笔录论学之习。"},{"text":"与老人约定抄副归还","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"抄副一份留在草堂,老人抚着副本说:我走之后,这页谱在你那里,就算活着。","source":"宋人笔记所载典籍借抄之俗。"}],"difficulty":1,"npc":["外州老乐师","落魄词人"],"foreshadow":"笔录入谱为考据公案"},{"id":"B-095","branch":"B","stage":4,"day":95,"shichen":"辰时","checkpoint":"官途余波·095辰","scene":"归途晨起,京城快马送来消息:翻案之功报到吏部,他获一个「廉干」的考语。可同一份邸报上,也有人嚼舌:功名全靠「内子清议护身」。","options":[{"text":"一笑置之,不问不辩","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你把邸报折好还他:护身的是我,争气的是你,谁也不欠谁。他大笑称是。","source":"宋代官员考课之制见《宋史·职官志》。"},{"text":"着恼要查嚼舌之人","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"查出来又如何?口舌生在所有人嘴上。你越查,越像真被人说中了什么。","source":"宋人笔记所载市井口舌之理。"}],"difficulty":2,"npc":[],"foreshadow":"「廉干」考语为官途进阶"},{"id":"B-095-未","branch":"B","stage":4,"day":95,"shichen":"未时","checkpoint":"官途余波·095未","scene":"午后船近汴京,他忽然说:我在外州夜里想明白了一件事——往后我若升迁,你仍是你;我若贬谪,我仍是我。我们谁也不做谁的影子。","options":[{"text":"答:两盏灯,各亮各的","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"他说这便是你们的家风。船头风大,你把这句话在心里钉得很牢。","source":"宋人词话所载夫妇相期之雅。"},{"text":"笑他船上说大话","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他认真起来:我是说真的。你收了笑——有些话必须当真听,哪怕在玩笑里。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"「两盏灯」家风为终章定调"},{"id":"B-095-戌","branch":"B","stage":4,"day":95,"shichen":"戌时","checkpoint":"官途余波·095戌","flavor":true,"scene":"夜归,汴京的灯火在望。小乐伎带着弟子们候在码头,见你下船,齐声喊:先生带回古谱了!——他们早从老乐工那儿听说了。","options":[{"text":"当众宣布末行将补","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"码头上爆出欢呼。你说:补成那日,弦正馆开坛,满城来听四百年前的声音。","source":"《东京梦华录》载汴京码头迎送之盛。"},{"text":"先谢众人连夜相迎","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一一谢过,灯火里全是熟脸。出门在外才知道,家里有一码头的人等着。","source":"同上。"}],"difficulty":1,"npc":["小乐伎学生","弦正馆学生","落魄词人"],"foreshadow":"开坛之约直通终章高潮"},{"id":"B-096","branch":"B","stage":4,"day":96,"shichen":"辰时","checkpoint":"末行疑·096辰","scene":"晨起,末行攻坚开始。旁支残页与主谱对校,那三个古记号终于可对上了——可最后一个音的位置,两种谱本自相矛盾。","options":[{"text":"暂缓定音,双谱并存","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"你把两种可能都录下,标上「存疑」。老乐工叹服:敢在古曲里写存疑,是真懂它。","source":"《碧鸡漫志》所载古谱校雠存疑之体。"},{"text":"择一谱强为定本","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"定是定了,可弹出来总觉得差了半口气。古曲的最后一音,宁缺毋滥。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"末音存疑为终章技艺扣子"},{"id":"B-096-未","branch":"B","stage":4,"day":96,"shichen":"未时","checkpoint":"末行疑·096未","scene":"午后,你把存疑的两说教给小乐伎,让她各弹十遍,弹到指尖说出自己的判断。她弹罢说:先生,我觉得两说都不对。","options":[{"text":"请她说出第三解","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"她的第三解出自指感,一试惊人地顺。你盯着她看了很久——新竹,要超过老竿了。","source":"宋人笔记所载乐人悟谱之事。"},{"text":"责其不可妄议古谱","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"她吓得不敢再言。你夜里自己试了她的说法——竟是对的。这句「不可妄议」,险些封了古曲的活路。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生"],"foreshadow":"弟子超师为终章传承扣"},{"id":"B-096-戌","branch":"B","stage":4,"day":96,"shichen":"戌时","checkpoint":"末行疑·096戌","flavor":true,"scene":"夜里,你把他叫到琴前,把三种解法都弹了一遍。他不懂乐,却听完说:第三种,像你们家——不,像咱们家。","options":[{"text":"问他何处像咱们家","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他说:前两种是老规矩,第三种是新道理,可都不丢骨头。你愣住——他说对了。","source":"宋人词话所载以乐喻家之趣。"},{"text":"把此语记入校谱册","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"册上记:某夜,外行人一语道破。往后校谱的人读到这行,会知道知音不必懂乐。","source":"宋人笔记所载校雠著录之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「不丢骨头的新道理」为全题眼"},{"id":"B-097","branch":"B","stage":4,"day":97,"shichen":"辰时","checkpoint":"年约备·097辰","scene":"晨起,州桥年约之期近了——当年婚书单上你添的那条「每年州桥一叙」,第一回。他提前三日就开始念叨,像个等过节的孩子。","options":[{"text":"备当年旧物赴约","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你带上《往来集》初稿、旧帕、那支素银簪。年约不是走桥,是盘点这一年。","source":"宋人词话所载桥畔订约之雅事。"},{"text":"说年年都去何必郑重","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他嘴上说好,眼里掠过一点失落。约的意义从来不在事本身,在于你们肯为它郑重。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"年约首践为情感节点"},{"id":"B-097-未","branch":"B","stage":4,"day":97,"shichen":"未时","checkpoint":"年约备·097未","scene":"午后,年约前一日,馆中弟子们知道了这个约,小乐伎提议:先生在桥上一叙,我们在桥下摆个小小的弦阵,给先生助兴。","options":[{"text":"允其弦阵但约法三章","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"约法:不扰行人、不索赏钱、弹完即散。弟子们欢呼——他们要的,只是站成先生的背景。","source":"宋人笔记所载市井献艺之俗。"},{"text":"怕招摇婉拒其议","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"弟子们讪讪散了。你的年约是你的,可他们想把自己的心意也摆到那座桥上。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"桥头弦阵为年约名景"},{"id":"B-097-戌","branch":"B","stage":4,"day":97,"shichen":"戌时","checkpoint":"年约备·097戌","flavor":true,"scene":"夜里年约前夜,你整理要带的旧物。翻到当年那册手抄词稿的第一页——「词因曲活,幸甚至哉」。你把它也带上了,明夜要让他重看这句话。","options":[{"text":"在稿末添一行新注","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你添的是:「词与曲皆活,幸甚至哉。」八个字对八个字,隔了半生才还上。","source":"宋代词简批注之习见宋人词话。"},{"text":"把旧帕系上琴轸","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"旧帕在弦边轻轻晃。明夜弹起来的时候,它会跟着每一个音晃。","source":"宋人笔记所载器饰之俗。"}],"difficulty":1,"npc":[],"foreshadow":"旧稿新注为年约仪式"},{"id":"B-098","branch":"B","stage":4,"day":98,"shichen":"辰时","checkpoint":"年约践·098辰","scene":"晨起,年约之日。你二人不坐车马,步行去州桥。一路走过书肆、旧馆、樊楼的侧门——这条路上的每一砖,都认得你们。","options":[{"text":"途中指认旧迹讲古","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你指书肆,他指樊楼,一路指过去,像两个老人给一座城讲一对年轻人的故事。","source":"《东京梦华录》载州桥至樊楼街市之盛。"},{"text":"默默并肩赶路赴桥","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"路走得快,话就少。这半里路你们走了十年,今日不该急。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"旧迹巡礼收束前半生"},{"id":"B-098-未","branch":"B","stage":4,"day":98,"shichen":"未时","checkpoint":"年约践·098未","scene":"午后,桥上。弟子们的弦阵已在桥尾摆开,桥心只有你们俩。你取出旧稿,他读你添的那行新注,读罢久久不语。","options":[{"text":"与他执手凭栏看水","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"桥下水声汤汤,弦阵的曲子远远传来。他说:往后的年约,我都想这样过。","source":"宋人词话所载桥畔唱和之雅。"},{"text":"急唤弦阵奏乐助兴","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"乐声一起,方才那点静默的千钧就被冲散了。有些话只能在安静里说完。","source":"同上。"}],"difficulty":2,"npc":["落魄词人","弦正馆学生"],"foreshadow":"桥上静默为情感至高点"},{"id":"B-098-戌","branch":"B","stage":4,"day":98,"shichen":"戌时","checkpoint":"年约践·098戌","flavor":true,"scene":"夜归,弦阵已散,弟子们把桥扫得干干净净。你立在院里,想起这半生的两座桥——樊楼的门槛,州桥的石栏。都跨过来了。","options":[{"text":"把今夜写进馆务册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"册上记:某年月日,年约首践。往后弟子们翻到这一页,会知道馆主为何要守一座桥。","source":"宋人笔记所载记事册之习。"},{"text":"与他灯下重弹旧曲","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"弹的是当年书肆初见的那支。他说今日的弦比那年的厚,你说那是因为有人听了十年。","source":"宋人词话所载旧曲重弹之慨。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「听了十年」为情缘注脚"},{"id":"B-099","branch":"B","stage":4,"day":99,"shichen":"辰时","checkpoint":"新弟子·099辰","scene":"晨起,年约的余温未散,馆中却出了新情况:那位豪富的女儿,自己背着琵琶跑来了,跪在门口说要拜师——她父亲说,她绝食了两日。","options":[{"text":"收其为徒,缓颊其父","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"你亲赴豪富家,以「心正」二字说服其父。少女入门那日,馆训墙下多了一双眼里的光。","source":"宋人笔记所载女子抗命向学之事。"},{"text":"拒之门外免惹麻烦","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"她跪在门外到日暮。你终究开了门——不是怕麻烦,是想起当年也有人为你开过门。","source":"同上。"}],"difficulty":3,"npc":["豪富之女","豪富"],"foreshadow":"逆女入门为part5新弟子线"},{"id":"B-099-未","branch":"B","stage":4,"day":99,"shichen":"未时","checkpoint":"新弟子·099未","scene":"午后,新弟子第一课,你教她的不是指法,是馆训。她仰着头问:先生,心正和功夫,哪个更难?你看着她,像看当年的自己。","options":[{"text":"答:心正难在无人处","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"她似懂非懂记下。你说:功夫有人看着,心正没有——所以它更贵。","source":"宋人笔记所载师门授业问答之习。"},{"text":"答:功夫难,先练指","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"她点头去练指了。你心里却知道,那个问题的真正答案,要她用很多年去懂。","source":"同上。"}],"difficulty":2,"npc":["豪富之女"],"foreshadow":"「无人处」为弟子线新课题"},{"id":"B-099-戌","branch":"B","stage":4,"day":99,"shichen":"戌时","checkpoint":"新弟子·099戌","flavor":true,"scene":"夜里,你与他谈及新弟子。他说:豪富之女,贫家之女,都跪过你的门——你这馆子,快成汴京女儿们的另一个娘家了。","options":[{"text":"答:娘家不看出身","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"他说要把这句话写进《宜弦》的续篇。你笑他词瘾又犯了,心里却暖了。","source":"宋人词话所载以词赠内之雅。"},{"text":"细数馆中弟子来历","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"瓦子的、贫家的、富室的、官眷——数完你发现,这馆子早已不是一座馆,是一面旗。","source":"宋人笔记所载民间女学之萌芽。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"弦正馆为旗帜,part5可展"},{"id":"B-100","branch":"B","stage":4,"day":100,"shichen":"辰时","checkpoint":"州桥年约·100辰","scene":"年约之月圆满。晨起,你把这一月的旧物——旧稿、新注、弦阵名册、桥畔落叶——收进新匣。匣底,是当年那支素银簪。","options":[{"text":"以簪定匣,岁岁如此","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"银簪压匣底,旧物层层上。这个匣子往后每年都会厚一点——它是你们的家史。","source":"宋人笔记所载妆奁岁积之俗。"},{"text":"只收文稿不收杂叶","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"落叶扔了,名册收了。多年后你翻看,总觉得缺了点什么——是那年的秋天本身。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"年约匣为家史载体"},{"id":"B-100-未","branch":"B","stage":4,"day":100,"shichen":"未时","checkpoint":"州桥年约·100未","scene":"午后,清直士人遣人送来一卷纸——是他为你们年约写的记,题为《桥约记》,备述首践之盛。满汴京的文人,都在传抄这卷纸。","options":[{"text":"谢过并藏入年约匣","correct":true,"tags":["名声","情缘"],"dims":{"名声":2,"情缘":1},"feedback":"《桥约记》入匣,与旧稿并排。你的私约,如今是汴京的佳话——你不恼,反而坦然。","source":"宋人笔记所载文人记事传抄之俗。"},{"text":"谦辞不敢当此记","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"辞是辞了,记已传抄。有些事越谦辞越显得珍贵——你忘了,清议从不白写。","source":"同上。"}],"difficulty":2,"npc":["清直士人"],"foreshadow":"《桥约记》为年约定名"},{"id":"B-100-戌","branch":"B","stage":4,"day":100,"shichen":"戌时","checkpoint":"州桥年约·100戌","flavor":true,"scene":"夜里,你二人对坐,把这一年的词谱信件重新编次。他忽然提议:年约匣里,该留一页空白,给明年今日。","options":[{"text":"留白页并题「来年」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"空页题罢,两人同时伸手去抚。空白不是无,是约定——明年此时,我们还来。","source":"宋人笔记所载册页留白之雅。"},{"text":"将匣钥匙交他保管","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"钥匙递过去,他愣住:这是你的匣子。你答:是我们的。他收下时,手有点抖。","source":"宋人笔记所载夫妇共藏之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"年约留白直通岁岁年年"},{"id":"B-101","branch":"B","stage":4,"day":101,"shichen":"辰时","checkpoint":"太常召·101辰","scene":"晨起,朝廷忽然降下一道意想不到的文书:太常寺重修乐书,闻弦正馆校补《霓裳》之名,行文征你参与编校——以布衣之身,入国家乐典。","options":[{"text":"应召,但以校谱为限","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"你复文:校谱可应,名分不受。太常寺的博士们传看复文,叹道:这才是真乐人。","source":"宋代太常寺修乐书之制见《宋史·乐志》。"},{"text":"欣然应召求个出身","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"出身两个字一出口,你自己先脸热。半生挣的是「不靠出身」,怎可临老破戒。","source":"同上。"}],"difficulty":3,"npc":["太常寺博士"],"foreshadow":"太常修书为终章最高台"},{"id":"B-101-未","branch":"B","stage":4,"day":101,"shichen":"未时","checkpoint":"太常召·101未","scene":"午后,消息传开,贺者盈门。小乐伎却问你一句:先生入太常校书,弦正馆怎么办?满馆的弟子,都竖着耳朵。","options":[{"text":"当众宣布馆务如常","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"你说:太常寺借的是我的耳朵,不是我的馆。弟子们欢呼,馆训墙下的弦声更齐了。","source":"宋人笔记所载民间塾学存续之习。"},{"text":"含糊说日后再定","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"「日后再定」四个字,让馆中人心悬了三日。主心骨一动,满馆的弦都跟着颤。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"馆务如常为根基不动"},{"id":"B-101-戌","branch":"B","stage":4,"day":101,"shichen":"戌时","checkpoint":"太常召·101戌","flavor":true,"scene":"夜里,贺客散尽,你与他独坐。他说:当年樊楼弹《凉州》的姑娘,如今要进太常寺修乐书了——这条路,我想都不敢想。","options":[{"text":"答:路是一步步弹出来的","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"他点头:不是想出来的,是弹出来的。这一夜,你们把这条路从头数了一遍。","source":"宋人词话所载夫妇忆旧之雅。"},{"text":"笑他也有不敢想的事","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他认了:我只敢想到与你州桥终老,再往后的,都是你自己弹出来的。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「弹出来的路」为全卷题眼"},{"id":"B-102","branch":"B","stage":4,"day":102,"shichen":"辰时","checkpoint":"官本误·102辰","scene":"晨起,入太常寺的第一天。博士们引你入藏谱阁,满架的乐书沉默如林。掌事博士说:先生校补的《霓裳》,我等已列入新乐书待考卷。","options":[{"text":"请先验残谱再论编次","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"你请先核原谱,再定体例。博士们对视一眼,有人低声说:这位先生,是来真的。","source":"宋代太常乐书编校程序见《宋史·乐志》。"},{"text":"客套周旋先应酬关系","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"应酬了一圈,谱还没碰。掌事博士的眼神淡了下来:太常寺要的,终究是真章。","source":"同上。"}],"difficulty":3,"npc":["太常寺博士"],"foreshadow":"先验谱为专业立身"},{"id":"B-102-未","branch":"B","stage":4,"day":102,"shichen":"未时","checkpoint":"官本误·102未","scene":"午后,验谱时发现一桩惊人的事:太常寺藏的《霓裳》官本,与你校补的民间残谱,竟有七处不合——官本,是错的。","options":[{"text":"据实呈报,附双谱为证","correct":true,"tags":["才华","自主"],"dims":{"才华":3,"自主":2},"feedback":"呈文上去,满寺震动。掌事博士亲自来谢:四百年的错,今日被一个民间乐人纠正了。","source":"《碧鸡漫志》所载官谱误传与民间存真之事。"},{"text":"沉默不言免得罪人","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你合上谱,心里像压了块石头。四百年的错音,你听见了,却装作没听见。","source":"同上。"}],"difficulty":3,"npc":["太常寺博士"],"foreshadow":"官本之误为终章大翻案"},{"id":"B-102-戌","branch":"B","stage":4,"day":102,"shichen":"戌时","checkpoint":"官本误·102戌","flavor":true,"scene":"夜里,你回家第一句话是:官本是错的。他放下笔,想了半天说:这话你敢在太常寺说,我却只敢在家说——你比我更像士人。","options":[{"text":"答:士人不如乐人敢","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"他大笑,提笔把这句话记下来。你说:记下也好,往后让孩子们知道,敢字怎么写。","source":"宋人词话所载夫妇戏言之趣。"},{"text":"拉他去院中看星","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"两人仰头看了半天。他说:天上的星,地上的谱,都要有人敢说真话。","source":"宋人笔记所载夜观星象之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「敢字」为终章精神核心"},{"id":"B-103","branch":"B","stage":4,"day":103,"shichen":"辰时","checkpoint":"对弹·103辰","scene":"晨起,翻案的影响来了:太常寺内有老博士不服,说你以民间残谱纠官本,是「以下犯上」;而年轻博士们,已悄悄站到了你这边。","options":[{"text":"以谱会友,公开试弹","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"你请两造同听,官本与残谱当场对弹。弦声一响,老博士的胡子抖了——对错,耳朵知道。","source":"宋人笔记所载以乐证谱之争。"},{"text":"著文自辩求其理解","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"文章写得再好,不如一弹。乐上的事,口舌永远赢不了耳朵。","source":"同上。"}],"difficulty":3,"npc":["太常寺博士"],"foreshadow":"对弹定谳为终章裁决"},{"id":"B-103-未","branch":"B","stage":4,"day":103,"shichen":"未时","checkpoint":"对弹·103未","scene":"午后,对弹毕,满座无声。老博士起身,颤巍巍向你一揖:老朽校谱四十年,今日始知天外有天。掌事博士当场宣布:新乐书,依残谱改。","options":[{"text":"回揖谢其从善如流","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"你扶起老人:错不在人,在谱。老人老泪纵横——乐人的体面,是用真章换来的。","source":"《宋史·乐志》所载乐官论乐之习。"},{"text":"欣然受拜不免得意","correct":false,"tags":["名声"],"dims":{"名声":0},"feedback":"得意之色一闪而过,年轻博士们看在眼里。赢了真理,输了风度——这买卖不值。","source":"同上。"}],"difficulty":3,"npc":["太常寺老博士","掌事博士"],"foreshadow":"老博士归心为太常线收"},{"id":"B-103-戌","branch":"B","stage":4,"day":103,"shichen":"戌时","checkpoint":"对弹·103戌","flavor":true,"scene":"夜里回家,你累得抬不起手。他默默接过你的琵琶挂好,又端来热汤。你忽然说:今日在太常寺,我想起樊楼——都是台子,都是弦。","options":[{"text":"与他细数两种台子","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"樊楼的台子练胆,太常的台子立名。他说:都是你的台子,只是换了个高度。","source":"宋人词话所载抚今追昔之慨。"},{"text":"饮汤入睡不言他事","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"汤喝完,灯吹灭。半生的事,有一件没一件,都让它在热汤里歇着。","source":"宋人笔记所载寝前汤饮之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"两种台子为身份升华"},{"id":"B-104","branch":"B","stage":4,"day":104,"shichen":"辰时","checkpoint":"盲听·104辰","scene":"晨起,馆中传来喜讯:豪富之女入门已满一月,月课竟列第三——比当年小乐伎还快。小乐伎来报时,眼里有笑,也有一点点藏不住的紧。","options":[{"text":"点破其紧,许其更强","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你说:师妹快,你该高兴——当年你超过我时,我也是这么想的。她如释重负。","source":"宋人笔记所载师门竞艺之习。"},{"text":"只夸新生不提旧人","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"夸完新生,小乐伎的笑更紧了。你后来才懂:先生夸新苗时,老竹子最怕被忘。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","豪富之女"],"foreshadow":"新老弟子竞艺为part5引"},{"id":"B-104-未","branch":"B","stage":4,"day":104,"shichen":"未时","checkpoint":"盲听·104未","scene":"午后,《霓裳》末行的存疑终于要解决。三种解法,三种指感,馆中、太常寺、老乐工三方各执。你决定:以一场「盲听会」定夺——不看谱,只凭耳。","options":[{"text":"设盲听会,三方共听","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":1},"feedback":"三解轮弹,满座闭目。曲终,老乐工先开口:第三解,是活的。定音,自此落槌。","source":"宋人笔记所载以耳验谱之雅集。"},{"text":"自行定音免生枝节","correct":false,"tags":["才华"],"dims":{"才华":2},"feedback":"定音快是快,可太常寺的人来问时,你少了一句「公听」的底气。","source":"同上。"}],"difficulty":3,"npc":["老乐工","太常寺博士","小乐伎学生"],"foreshadow":"盲听定音,末行告竣"},{"id":"B-104-戌","branch":"B","stage":4,"day":104,"shichen":"戌时","checkpoint":"盲听·104戌","flavor":true,"scene":"夜里,定音的《霓裳》末行第一次完整试弹。你弹罢,老乐工老泪纵横,他握着你的手说:四百年,今天它喘匀了气。","options":[{"text":"请老乐工署名同校","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"老人颤抖着写下名字,说:我这辈子,总算在乐书上有一行了。","source":"宋代乐书校勘署名之制见宋人笔记。"},{"text":"将此夜记入年约匣","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"匣中添一页:某年月日,霓裳末行定音。来年州桥,可以弹给桥听了。","source":"宋人笔记所载记事册之习。"}],"difficulty":1,"npc":["老乐工","落魄词人"],"foreshadow":"古曲告竣,终章待献"},{"id":"B-105","branch":"B","stage":4,"day":105,"shichen":"辰时","checkpoint":"阶段四收官·105辰","scene":"收官日晨起。太常寺正式行文:新乐书《霓裳》卷,署名「校补:弦正馆主」。你捧着文书,想起当年乐籍司压正本的那个小吏——天地,翻过来了。","options":[{"text":"收文书,弹一曲自贺","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"曲毕,你对自己说:从卖艺到修典,这条路我走了半生——值。","source":"宋代太常乐书署名之制见《宋史·乐志》。"},{"text":"先遣人告他再细读","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"口信递出去,你才发现自己在等他的反应。原来有些荣耀,要有人同看才算数。","source":"同上。"}],"difficulty":3,"npc":["太常寺博士"],"foreshadow":"修典署名为技艺线顶点"},{"id":"B-105-未","branch":"B","stage":4,"day":105,"shichen":"未时","checkpoint":"阶段四收官·105未","scene":"午后,满汴京都来了:老乐工、鸨母、姐姐、书肆掌柜、十二弟子、太常寺的年轻博士们。小院挤得水泄不通,都说要听你弹一遍全本《霓裳》。","options":[{"text":"设席院中,当众全弹","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"四百年大曲在小院复活,曲终满院跪倒一片——不是跪你,是跪那支终于回家的曲子。","source":"《碧鸡漫志》所载《霓裳》之重光。"},{"text":"谦逊推辞只弹片段","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"片段弹罢,众人意犹未尽。你知道,有些时刻不该省——它是几百人共同的节日。","source":"同上。"}],"difficulty":3,"npc":["老乐工","鸨母","资深歌伎","弦正馆学生","太常寺博士"],"foreshadow":"全本首演为收官大典"},{"id":"B-105-戌","branch":"B","stage":4,"day":105,"shichen":"戌时","checkpoint":"阶段四收官·105戌","flavor":true,"scene":"收官之夜,众人散尽,新宅复归安静。你与他并坐阶前,年约匣在膝上,匣中添了新页:太常署名、全本首演、盲听定音。他忽然说:来年州桥,该有新词了。","options":[{"text":"答:词牌我都想好了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"你说叫《桥上月》。他击节:月照桥,桥照水,水照咱们——好,就这个。","source":"宋人词话所载词牌新创之雅。"},{"text":"抚匣回望,静待来年","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":2},"feedback":"你合上匣子,望向州桥方向。来年的空白页已经在那里了——你们的故事,永远有下一页。","source":"宋人笔记所载岁朝展望之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"《桥上月》虚位以待,终章待启"},{"id":"B-106","branch":"B","stage":5,"day":106,"shichen":"辰时","checkpoint":"桥上月·106辰","scene":"终章开卷。晨起,他在书房里关了半日,出来时手里一阕新词——《桥上月》,践年约之作。第一句是:「月照桥时桥照人」。","options":[{"text":"捧读三遍,当场起谱","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"谱至「桥照人」三字,弦声一顿。他说:这一顿里,有十年的州桥。","source":"宋人词话所载词曲唱和、即席度曲之雅。"},{"text":"笑他一年就憋这一阕","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他不恼,慢悠悠道:一年的词,是拿三百六十五日酿的。你细读,果然字字沉。","source":"宋人词话所载炼字之苦。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"《桥上月》为终章主题曲"},{"id":"B-106-未","branch":"B","stage":5,"day":106,"shichen":"未时","checkpoint":"桥上月·106未","scene":"午后,太常寺送来新乐书清样:《霓裳》卷末,你的署名与老乐工的并列。掌事博士附信:全卷待最后献演验定,便可付梓颁行。","options":[{"text":"亲校清样一字不略","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"校至署名那行,你停笔看了很久。半生颠沛,落成两个端正的墨字。","source":"宋代太常乐书付梓程序见《宋史·乐志》。"},{"text":"信任寺中不复重校","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"夜里到底不放心,又爬起来重校——果然清样有一处谱字印倒了。你的不放心,是对的。","source":"同上。"}],"difficulty":3,"npc":["太常寺掌事博士"],"foreshadow":"献演验定为终章大典门槛"},{"id":"B-106-戌","branch":"B","stage":5,"day":106,"shichen":"戌时","checkpoint":"桥上月·106戌","flavor":true,"scene":"夜里,你把《桥上月》的词稿与太常寺清样并排摆在案上——一件是私情,一件是公器,都是这一年结的果。","options":[{"text":"将两件都记入年约匣","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"匣中这一页,左私右公。你忽然明白:你们俩的后半生,就是这么合著的。","source":"宋人笔记所载记事著录之习。"},{"text":"灯下再谱《桥上月》","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"谱到三更,他在隔壁书房应了一声:「第三句的调,再缓半拍。」隔墙唱和,也是团圆。","source":"宋人词话所载隔墙唱和之趣。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"公私合著为终章结构"},{"id":"B-107","branch":"B","stage":5,"day":107,"shichen":"辰时","checkpoint":"无人处·107辰","scene":"晨起,馆中出试:豪富之女在扫洒时拾到一锭遗金——是某位家长遗落的束脩外加厚赠。馆中无人,只有她一人看见。","options":[{"text":"静观其行暂不点破","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你隐在廊下。她犹豫片刻,将金子原样交到了馆务册房。「无人处」这一课,她自己过了。","source":"宋人笔记所载拾金不昧之训。"},{"text":"现身夸赞其拾金不昧","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"她一怔,红着脸说:先生看见了?——你后悔了:无人处的考验,要的是她自己知道。","source":"同上。"}],"difficulty":3,"npc":["豪富之女"],"foreshadow":"「无人处」课题首答"},{"id":"B-107-未","branch":"B","stage":5,"day":107,"shichen":"未时","checkpoint":"无人处·107未","scene":"午后,你在月课上讲了这锭金子——不说人名,只说事。讲罢问十二弟子:心正难在无人处,今日你们懂了么?","options":[{"text":"让弟子们各自作答","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"答案五花八门,小乐伎最后说:无人处的心正,是夜里弹给自己的那遍琴。满室静了。","source":"宋人笔记所载师门问对之习。"},{"text":"直接给出标准答案","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"弟子们齐声记下,可你知道——写在纸上的道理,和长在心里的骨头,差着一场自问。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"弟子问答为馆训终解"},{"id":"B-107-戌","branch":"B","stage":5,"day":107,"shichen":"戌时","checkpoint":"无人处·107戌","flavor":true,"scene":"夜里,豪富之女独自来见你,把白日的事原原本本说了——她本以为无人知晓,说完如释重负。你给她续了盏茶。","options":[{"text":"告诉她先生都看见了","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"她瞪大眼睛,随即笑了:原来先生早知。你答:心正不是做给人看,但先生会记得。","source":"宋人笔记所载师门观人之习。"},{"text":"问她交金时可曾挣扎","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"她老实答:挣扎了一盏茶的工夫。你点头:会挣扎的心正,才是真的心正。","source":"同上。"}],"difficulty":1,"npc":["豪富之女"],"foreshadow":"弟子心性大成"},{"id":"B-108","branch":"B","stage":5,"day":108,"shichen":"辰时","checkpoint":"薪火承·108辰","scene":"晨起,急报自外州来:老乐师昨夜病故,遗命将草堂全部藏谱赠予弦正馆——附言:「谱随知音去,勿使弦断绝。」","options":[{"text":"设灵遥祭,承谱立志","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"你在馆中设香案遥祭,对十二弟子说:往后你们学的每一首古曲,都有这位老人的名字。","source":"宋人笔记所载乐人衣钵相传之俗。"},{"text":"遣人吊唁代己尽礼","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"礼是到了,可你夜里睡不着——最后一面之缘,你欠老人一次亲送。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生"],"foreshadow":"草堂藏谱为终章传承底仓"},{"id":"B-108-未","branch":"B","stage":5,"day":108,"shichen":"未时","checkpoint":"薪火承·108未","scene":"午后,你与他商议:草堂藏谱数十函,是乐人百年心血,或入馆授徒,或刊行公世,或献太常——三条路,都要对得起那句「勿使弦断绝」。","options":[{"text":"三路并行:授、刊、献","correct":true,"tags":["才华","自主"],"dims":{"才华":3,"自主":1},"feedback":"议定:珍本入馆授徒,副本刊行公世,孤本献太常存档。他说:这才叫让每一根弦都不绝。","source":"宋代典籍收藏、刊行、进献之俗见宋人笔记所载。"},{"text":"全部献太常求稳妥","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"太常寺的架阁库深似海,谱一进去,民间就再也摸不到了。老人要的「不绝」,不是「不流通」。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"三路并行收官传承线"},{"id":"B-108-戌","branch":"B","stage":5,"day":108,"shichen":"戌时","checkpoint":"薪火承·108戌","flavor":true,"scene":"夜里,你取出草堂那页旁支残谱的抄副,就着灯又看了一遍。老人已去,纸上的字迹还在呼吸。你忽然想为他弹一曲。","options":[{"text":"弹《霓裳》末行相送","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"末行新定的音在夜空里荡开。他听见,老人也一定听见了——这一音,是他起的头。","source":"宋人词话所载以乐祭友之俗。"},{"text":"将抄副供入馆中谱堂","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"谱堂第一供,给这位只见过一面的老人。往后弟子入门,先拜这页纸。","source":"宋人笔记所载谱堂奉祀之习。"}],"difficulty":1,"npc":[],"foreshadow":"谱堂首供定传承正朔"},{"id":"B-109","branch":"B","stage":5,"day":109,"shichen":"辰时","checkpoint":"公益账·109辰","scene":"晨起,版润公益之账到了收官时:《往来集》刊行一年,盈余尽数入馆,贫生减免之额翻了三倍。掌柜的抱来总账,馆中弟子围观。","options":[{"text":"当众公示,账目上墙","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":2},"feedback":"账榜贴上馆训墙旁,一笔一笔,清白如雪。弟子们说:先生的馆,连银子都是正的。","source":"宋代民间义学账目公示之习见宋人笔记。"},{"text":"内部核销不必公示","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"账清了,可弟子们没看着。公益这件事,账不亮出来,好心就缺了半分底气。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜","弦正馆学生"],"foreshadow":"账榜为公益线收官凭证"},{"id":"B-109-未","branch":"B","stage":5,"day":109,"shichen":"未时","checkpoint":"公益账·109未","scene":"午后,贫家之母又来了——这回不是谢恩,是领着三个邻家贫女来报名。她说:汴京的穷丫头们都知道,弦正馆的门槛,不垫银子。","options":[{"text":"按新额收录三女","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"三个怯生生的丫头入了馆册。你想起当年樊楼教坊里的自己——门槛拆了,路就宽了。","source":"宋人笔记所载贫女向学之事。"},{"text":"额满婉拒登记候缺","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"候缺名册添了三行,三个丫头的眼神暗了暗。公益的规矩要有,可门缝里的光,别关得太快。","source":"同上。"}],"difficulty":2,"npc":["贫家弟子之母"],"foreshadow":"门槛不垫银为馆誉定论"},{"id":"B-109-戌","branch":"B","stage":5,"day":109,"shichen":"戌时","checkpoint":"公益账·109戌","flavor":true,"scene":"夜里,你与他清点这一年的公益账,忽然发现:版润、束脩、捐赠,进出相抵,弦正馆竟已能自我运转——它不再只是你的馆了。","options":[{"text":"议立馆产公管之制","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"制度立起来:馆主、代领、家长共管。你说:馆比人长寿,靠的不是我,是规矩。","source":"宋人笔记所载民间公产管理之萌芽。"},{"text":"感怀良久暂不思制","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"这一夜你们只感慨,不定制。有些大事要趁热血时想,也要等心静了才立得住。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"馆产公制为part5弦正馆永续"},{"id":"B-110","branch":"B","stage":5,"day":110,"shichen":"辰时","checkpoint":"薪火·110辰","scene":"薪火日。晨起,老乐工扶杖而来,把最后一件东西交给你——教坊当年的「传习印」。他说:老朽教不动了,这印往后盖在谁的谱上,你说了算。","options":[{"text":"拜受传习印,立传习之约","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":1},"feedback":"印入手,你当众立约:印随功走,不随名走。老人笑了:弦正馆的印,果然也讲规矩。","source":"宋人笔记所载教坊印信传承旧例。"},{"text":"推辞请老人再掌几年","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老人摇头:我掌印的最后一件事,就是把它交出去。你再推,是误了他最后一课。","source":"同上。"}],"difficulty":3,"npc":["老乐工"],"foreshadow":"传习印为终章授印大典伏笔"},{"id":"B-110-未","branch":"B","stage":5,"day":110,"shichen":"未时","checkpoint":"薪火·110未","scene":"午后,你把传习印交给小乐伎与豪富之女共看,告诉她们:这印不认年齿、不认门第,只认两样——功夫与心正。谁先够格,谁先掌印。","options":[{"text":"令二人共勉不争先后","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"两人对视一眼,同时行礼。你想起当年樊楼你与资深歌伎的较技——较到高处,是同路人。","source":"宋人笔记所载师门竞艺之习。"},{"text":"暗示小乐伎年长优先","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"话一出口,豪富之女的眼神黯了。印还没盖,规矩先弯了——这不是你教的「心正」。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生","豪富之女"],"foreshadow":"共掌印之约收弟子竞艺线"},{"id":"B-110-戌","branch":"B","stage":5,"day":110,"shichen":"戌时","checkpoint":"薪火·110戌","flavor":true,"scene":"夜里,传习印收进馆中谱堂,与草堂残谱并供。你独自在谱堂坐了很久,从及笄那年的旧琵琶,到今日满架的藏谱——这座馆,是你的来路,也是别人的去路。","options":[{"text":"为谱堂题「薪火」二字","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"匾额挂上,墨迹未干。你忽然懂了老乐工当年说的「别烂在我手里」——火,是要传的。","source":"宋人笔记所载题匾之习。"},{"text":"抚旧琵琶默坐至夜深","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"琴身斑驳,弦轴温润。你弹了一个音,很轻——像对多年前的自己,说一声「成了」。","source":"宋人词话所载抚旧感怀之习。"}],"difficulty":1,"npc":[],"foreshadow":"谱堂薪火为传承定名"},{"id":"B-111","branch":"B","stage":5,"day":111,"shichen":"辰时","checkpoint":"献演备·111辰","scene":"晨起,献演验定之期定了:三日后,太常寺设坛,公演全本《霓裳》,验定通过即付梓颁行。满汴京都在等这一场——四百年大曲,当代首演。","options":[{"text":"亲定仪程,以古为尊","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":1},"feedback":"仪程依古制:焚香、净场、序曲、全本。掌事博士看罢说:先生这是替古人办典礼。","source":"宋代太常乐仪之制见《宋史·乐志》。"},{"text":"交由寺中安排仪程","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"寺中仪程热闹有余,古意不足。你连夜改了七处——首演是曲子的,不是场面的。","source":"同上。"}],"difficulty":3,"npc":["太常寺掌事博士"],"foreshadow":"古仪定调为献演大典骨架"},{"id":"B-111-未","branch":"B","stage":5,"day":111,"shichen":"未时","checkpoint":"献演备·111未","scene":"午后,排练最后一遍。弹到末行,你忽然停住:这最后三音,你想让一个人先听——当年外州草堂外,你说要「让老人后悔」的那个人。","options":[{"text":"请他先听末三音","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"三音弹罢,他良久无言,说:老人没后悔,是我先说错了——知音面前,只有敬,没有悔。","source":"宋人词话所载先睹为快之雅。"},{"text":"藏到最后一日再示人","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"末三音捂到首演,惊艳是惊艳了,可你少了一次把最重要的人放在最前面的机会。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"末三音先闻为知音礼"},{"id":"B-111-戌","branch":"B","stage":5,"day":111,"shichen":"戌时","checkpoint":"献演备·111戌","flavor":true,"scene":"首演前夜,你二人对坐检点明日装束。他忽然说:明日我在台下第一排——不是官员,是知音。你笑道:第一排贵着呢,得拿十年词来换。","options":[{"text":"他说词早就写好了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他展开袖中词稿:《霓裳》献演贺词,墨迹已干多日。原来他早备着了,等今夜才拿出来。","source":"宋人词话所载预撰贺词之雅。"},{"text":"约定明日以目相会","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"台上弦动,台下目接。你们约好:弹到「霜满州桥」一句时,只看对方一眼。","source":"宋人笔记所载以目传情之雅。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"台下第一排为首演情感锚点"},{"id":"B-112","branch":"B","stage":5,"day":112,"shichen":"辰时","checkpoint":"霓裳大典·112辰","scene":"献演日。太常寺坛上,香雾缭绕,满朝乐官、清议士人、旧日樊楼姐妹、弦正馆弟子,分列两厢。他坐在第一排,青衫洗得发白,背挺得笔直。","options":[{"text":"焚香净手,凝神登场","correct":true,"tags":["才华","名声"],"dims":{"才华":3,"名声":2},"feedback":"登台一拜,满坛肃然。你拨第一音时,听见老乐工在台下轻轻咳嗽——那是四十年前的回音。","source":"宋代太常大乐献演之仪见《宋史·乐志》。"},{"text":"环视满座略显紧张","correct":false,"tags":["才华"],"dims":{"才华":2},"feedback":"目光扫过台下,你看见鸨母抹泪、姐姐攥拳、小乐伎屏息——这满坛的牵挂,忽然让你定了。","source":"同上。"}],"difficulty":3,"npc":["落魄词人","老乐工","太常寺博士","鸨母","资深歌伎"],"foreshadow":"满坛见证为大典阵容"},{"id":"B-112-未","branch":"B","stage":5,"day":112,"shichen":"未时","checkpoint":"霓裳大典·112未","scene":"全本弹至末行,那三个曾存疑的古音,如今行云流水。曲终,满坛静默三息,随即掌声如雷动——四百年的《霓裳》,回家了。","options":[{"text":"敛衽谢坛,不骄不躁","correct":true,"tags":["才华","自主"],"dims":{"才华":3,"自主":2},"feedback":"你谢坛而退,衣角未乱。掌事博士追上来:先生留名——你答:名在谱上,不在脸上。","source":"宋人笔记所载乐人谦逊之德。"},{"text":"立于坛心受满场欢呼","correct":false,"tags":["名声"],"dims":{"名声":2},"feedback":"欢呼是好听,可你多立了一瞬,老乐工便多咳了一声。有些时刻,退比进更像大家。","source":"同上。"}],"difficulty":3,"npc":["太常寺掌事博士","老乐工"],"foreshadow":"谢坛而退为大师风度"},{"id":"B-112-戌","branch":"B","stage":5,"day":112,"shichen":"戌时","checkpoint":"霓裳大典·112戌","flavor":true,"scene":"大典之夜,贺客散尽。你与他并肩归家,路过州桥,不约而同停下。桥上无月,可你们都知道,那轮月在——在词里,在弦上,在彼此眼里。","options":[{"text":"桥上轻唱《桥上月》","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"无月之桥,唱月之词。唱到「桥照人」时,他接了下一句——两个人,把月亮唱出来了。","source":"宋人词话所载即景唱和之雅。"},{"text":"静立桥上听水声","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"水声汤汤,如十年前。他说:当年我在桥这头写词,你在桥那头弹曲——如今桥还是桥。","source":"《东京梦华录》载州桥形胜与汴河夜声。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"桥上月满,年约前奏"},{"id":"B-113","branch":"B","stage":5,"day":113,"shichen":"辰时","checkpoint":"颁行·113辰","scene":"晨起,太常寺颁下文书:新乐书《霓裳》卷验定通过,即日付梓,颁行天下州府。你的署名,将随这部书,走进每一座府学的藏书楼。","options":[{"text":"收文书,谢寺中诸公","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":3},"feedback":"一一谢过,不居首功。博士们送你出门时说:乐书会老,先生的名字不会。","source":"宋代乐书颁行之制见《宋史·乐志》。"},{"text":"喜形于色遍告亲友","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"喜讯传得是快,可你逢人便说,说到第五遍时,自己先觉得轻了。","source":"同上。"}],"difficulty":3,"npc":["太常寺博士"],"foreshadow":"颁行天下为技艺线封顶"},{"id":"B-113-未","branch":"B","stage":5,"day":113,"shichen":"未时","checkpoint":"颁行·113未","scene":"午后,馆中弟子们闻讯,吵着要庆贺。小乐伎提议:今日不习新曲,把先生教过的旧曲,每人弹一段,弹给谱堂里的老人听。","options":[{"text":"允其请,同往谱堂","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"十二段旧曲,在草堂残谱前轮流响起。你立在门边听,像听见一条河从源头流到了海。","source":"宋人笔记所载门生献艺谢师之俗。"},{"text":"令照常课业勿张扬","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"弟子们怏怏归座。你课后独往谱堂,替他们弹了那十二段——有些庆贺,先生该带头。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","弦正馆学生"],"foreshadow":"谱堂献曲收弟子线"},{"id":"B-113-戌","branch":"B","stage":5,"day":113,"shichen":"戌时","checkpoint":"颁行·113戌","flavor":true,"scene":"夜里,你取出一册刚印成的《霓裳》新谱,翻到署名页,看了很久。他凑过来看,忽然指着谱末的校勘记说:这一行小字,比我的名字值钱。","options":[{"text":"答:那是老人家的名字","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"校勘记里,外州老乐师的名字排在最前。你说:没有他,这行字立不住。","source":"宋代乐书校勘署名之制见宋人笔记。"},{"text":"合谱收入年约匣","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"新谱入匣,与旧帕、词稿、刊本并排。这一夜的匣子,装的是「功成」两个字。","source":"宋人笔记所载藏书之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"功成入匣,来路皆成"},{"id":"B-114","branch":"B","stage":5,"day":114,"shichen":"辰时","checkpoint":"馆碑·114辰","scene":"晨起,公益收官:版润与馆产公管之制正式立碑于馆门,账目、章程、名录,刻石永志。贫家之母携新收的三个贫女来观礼。","options":[{"text":"亲书碑文,立于馆门","correct":true,"tags":["自主","名声"],"dims":{"自主":3,"名声":2},"feedback":"碑文末尾你刻了一句:「门槛不垫银,弦正自在心。」拓片当日就传遍了汴京。","source":"宋人笔记所载义学立碑之俗。"},{"text":"请士人代笔碑文","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"清直士人欣然代笔,辞藻华丽。可你知道,这句话该你自己写——它不是文章,是命脉。","source":"同上。"}],"difficulty":3,"npc":["贫家弟子之母","清直士人"],"foreshadow":"馆碑为公益线永志"},{"id":"B-114-未","branch":"B","stage":5,"day":114,"shichen":"未时","checkpoint":"馆碑·114未","scene":"午后,立碑礼成,资深歌伎——如今该称她姐姐了——送来贺礼:她已脱籍自立,在城东开了间小小的琴舍,招牌是你题的「传火」。","options":[{"text":"携弟子往贺其开业","correct":true,"tags":["自主","名声"],"dims":{"自主":2,"名声":1},"feedback":"两馆相望,一传一承。姐姐拉着你的手说:当年较技,我输了琵琶;今日我才赢回了命。","source":"宋人笔记所载乐户自立开业之事。"},{"text":"遣弟子代往致贺","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"贺礼到了,人没到。姐姐在琴舍门口望了半日——有些开业,要的是那个人亲自来。","source":"同上。"}],"difficulty":2,"npc":["资深歌伎"],"foreshadow":"两馆并立收姐妹线"},{"id":"B-114-戌","branch":"B","stage":5,"day":114,"shichen":"戌时","checkpoint":"馆碑·114戌","flavor":true,"scene":"夜里,你从姐姐琴舍归来,绕道樊楼。楼中灯火依旧,笙歌依旧,只是台上弹琵琶的,已是新一批姑娘。你立在对街,听了一曲。","options":[{"text":"听完一曲悄然离去","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"新曲弹得生涩,你听得出错音,也听得出希望。你当年也是这样,从错音里长出来的。","source":"《东京梦华录》载樊楼笙歌之盛。"},{"text":"遣人赠新曲谱一册","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"谱册送进楼中,附言:赠弦上有心人。你没留名——薪火相传,本就不必留名。","source":"宋人笔记所载乐谱赠遗之雅。"}],"difficulty":1,"npc":[],"foreshadow":"樊楼回望收来路线"},{"id":"B-115","branch":"B","stage":5,"day":115,"shichen":"辰时","checkpoint":"乐书颁行·115辰","scene":"颁行日。晨起,驿马自太常寺出发,载着新乐书奔赴各州府。你与他在城门口目送,看那些书箱装上船,顺汴河而下。","options":[{"text":"目送书船出城","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":2},"feedback":"书船渐远,他说:四百年后,还会有人翻开这页。你答:那就够了。","source":"宋代驿递颁书之制见《宋史·职官志》。"},{"text":"转身回馆不送","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你说书是弹出来的,不是送出来的。他点头,可两人都站在原地,直到船看不见。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"书船出城为技艺线远航"},{"id":"B-115-未","branch":"B","stage":5,"day":115,"shichen":"未时","checkpoint":"乐书颁行·115未","scene":"午后,州桥年约第二度将至。他告了假,说今年要早些去,把桥上的位置先看好了。你笑他急,他却认真:年约是约,不是礼数。","options":[{"text":"携《桥上月》词稿同往","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"词稿、旧帕、银簪、年约匣——你收拾停当,像赴一场准备了十年的约。","source":"宋人词话所载桥畔践约之雅。"},{"text":"说今年事务繁暂缓","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"「暂缓」两个字一出口,他眼里的光就暗了。年约之所以是约,正在于从不暂缓。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"年约二度为终章情感顶点"},{"id":"B-115-戌","branch":"B","stage":5,"day":115,"shichen":"戌时","checkpoint":"乐书颁行·115戌","flavor":true,"scene":"年约前夜,你把《桥上月》的谱最后校了一遍。窗外无月,可谱上的每一个音都亮着——你们自己,就是彼此的月亮。","options":[{"text":"在谱末题「照人」二字","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"二字题罢,你想起十年前他说「词要入乐才算活过来」。如今词活了,人也活了。","source":"宋人词话所载题跋之雅。"},{"text":"将谱与词稿合订","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"词谱合订成册,封面你写:《桥上月》,某年某月,州桥。册子很轻,装的是一生。","source":"宋人笔记所载词谱合编之习。"}],"difficulty":1,"npc":[],"foreshadow":"《桥上月》成册,年约在即"},{"id":"B-116","branch":"B","stage":5,"day":116,"shichen":"辰时","checkpoint":"年约二度·116辰","scene":"晨起,年约之日。你二人不携从者,步行至州桥。桥上已有先到的弟子们,远远望见你们,悄悄退到桥尾——他们把桥心,留给了先生。","options":[{"text":"谢弟子们成全此约","correct":true,"tags":["情缘","名声","感情"],"dims":{"情缘":2,"名声":1},"feedback":"你回身一揖,弟子们齐回。桥心二人,桥尾十二人,一座桥,站成了两代人的江山。","source":"宋人笔记所载桥畔雅集之俗。"},{"text":"挥手令弟子们散去","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"弟子们散得安静,可你看见小乐伎回头望了三回。年约是你们的,也是他们想看的。","source":"同上。"}],"difficulty":2,"npc":["落魄词人","弦正馆学生"],"foreshadow":"桥心二人,桥尾传承"},{"id":"B-116-未","branch":"B","stage":5,"day":116,"shichen":"未时","checkpoint":"年约二度·116未","scene":"午后,桥心。你展开《桥上月》词谱合订册,他读词,你调弦。桥下水声依旧,桥上人影依旧,只是这一回,你们站在岁月的下游,回望上游。","options":[{"text":"弹《桥上月》全阕","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":3,"才华":1},"feedback":"曲终,他轻声说:当年桥上相约的人,如今在桥上弹成了曲子。你答:曲子比人长久。","source":"宋人词话所载桥畔度曲之雅。"},{"text":"先叙旧事再弹新词","correct":false,"tags":["情缘"],"dims":{"情缘":2},"feedback":"旧事叙到日影西斜,新词险些没来得及弹。你忽然明白:来路太长,要省着点回头。","source":"同上。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"桥上月成,年约圆满"},{"id":"B-116-戌","branch":"B","stage":5,"day":116,"shichen":"戌时","checkpoint":"年约二度·116戌","flavor":true,"scene":"年约之夜,月升起来了。你们没有立刻归家,在桥上坐到夜深。弟子们早散了,只有卖汤圆的小贩记得你们——他给你们留了两碗。","options":[{"text":"分食汤圆谢小贩","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"汤圆很甜,小贩说:二位年年这时候来,我这摊子就是你们的见证。你多给了钱。","source":"《东京梦华录》载州桥夜市食摊之俗。"},{"text":"踏月而归不扰夜市","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"月色把两条影子拉得很长,交叠在一处。你想起婚书上的话:两盏灯,各亮各的——可影子早就叠在一起了。","source":"同上。"}],"difficulty":1,"npc":["落魄词人","汤圆小贩"],"foreshadow":"小贩见证为年约余韵"},{"id":"B-117","branch":"B","stage":5,"day":117,"shichen":"辰时","checkpoint":"双印·117辰","scene":"晨起,太常寺传来最后的消息:新乐书颁行途中,有外州学官快马回报——当地教坊得谱,连夜习弹,《霓裳》已在州城复活。","options":[{"text":"将回报转示谱堂","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"回报供在草堂残谱旁。你对弟子们说:看见了吗?你们学的每一个音,都可能救活一支四百年后的曲子。","source":"宋代州府教坊习乐之制见《宋史·乐志》。"},{"text":"收作私藏不示人","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"回报收进匣中,弟子们没看见。你夜里想:薪火要让人看见,才点得着下一把。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生"],"foreshadow":"州府复活为传火远播"},{"id":"B-117-未","branch":"B","stage":5,"day":117,"shichen":"未时","checkpoint":"双印·117未","scene":"午后,小乐伎与豪富之女同来见你,说她们商议好了:传习印,二人共掌——一管内,一管外;一授技,一授德。请你裁夺。","options":[{"text":"允其共掌,立双印之制","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":2},"feedback":"你抚掌:一印分阴阳,一馆有两仪。当年较技的两个人,如今要并肩守一座馆了。","source":"宋人笔记所载师门共治之创例。"},{"text":"仍主一人独掌为正","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"两人对视一眼,退下了。你后来想:你教她们心正,她们教你——共治,也是正。","source":"同上。"}],"difficulty":3,"npc":["小乐伎学生","豪富之女"],"foreshadow":"双印共治为馆务终局"},{"id":"B-117-戌","branch":"B","stage":5,"day":117,"shichen":"戌时","checkpoint":"双印·117戌","flavor":true,"scene":"夜里,你与他提及双印之议。他听完笑道:你们这馆子,快成汴京的女儿国了——官印分阴阳,馆印也分阴阳。你说:阴阳相济,才是人间。","options":[{"text":"请他题「双印堂」匾","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":1,"才华":1},"feedback":"他提笔一挥而就。你忽然发现:这馆里的匾,一半是他题的——你们的江山,从来都是合著。","source":"宋人词话所载夫妇题咏之雅。"},{"text":"笑他酸儒不解馆务","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他不恼,反问你:那你说,双印堂里,你管什么?你答:我管——看着你们管。","source":"宋人笔记所载夫妇戏言之趣。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"双印堂为馆务新章"},{"id":"B-118","branch":"B","stage":5,"day":118,"shichen":"辰时","checkpoint":"旧书·118辰","scene":"晨起,你忽然想去一个地方——当年州桥书肆。掌柜的已老,见你来,颤巍巍从架顶取下一册旧书:当年你替他取下的那册《乐章集》,他一直留着。","options":[{"text":"购回旧书,重温旧缘","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"书页泛黄,当年你指尖触过的那页还在。掌柜的说:这书等你们,等了十年。","source":"《东京梦华录》载州桥书肆之盛。"},{"text":"谢绝掌柜好意","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"掌柜的把书又放回架顶,说:再留十年,也是一样的。你出门时,心里空了一块。","source":"同上。"}],"difficulty":2,"npc":["书肆掌柜"],"foreshadow":"旧书重温收初遇线"},{"id":"B-118-未","branch":"B","stage":5,"day":118,"shichen":"未时","checkpoint":"旧书·118未","scene":"午后,你携旧书归家,他正在校《往来集》的二版。见书愣住,随即大笑:这书我找了半生——当年在书肆,就是它让我们说的话。","options":[{"text":"合校旧书,补入二版","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"你们把当年初遇的那页,影写补入《往来集》卷首——来路,终于成了正文。","source":"宋人词话所载词集补遗之习。"},{"text":"各自收藏不预刊行","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"书收进年约匣,他继续校二版。你夜里想:有些缘分,只配我们两个人知道。","source":"同上。"}],"difficulty":2,"npc":["落魄词人"],"foreshadow":"初遇入集,来路成正文"},{"id":"B-118-戌","branch":"B","stage":5,"day":118,"shichen":"戌时","checkpoint":"旧书·118戌","flavor":true,"scene":"夜里,二版《往来集》校毕,你在新补的卷首那页,添了一行小注:「某年月日,州桥书肆,初遇。」他凑过来看,说:这行字,值整本书。","options":[{"text":"答:整本书都是这行字","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"他怔住,随即重重点头。你们都知道:往后所有的好日子,都是从那一页开始的。","source":"宋人词话所载词集本事之注。"},{"text":"将初版与二版并藏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"两版并排,一版是「当年」,一版是「后来」。中间隔着的,是你们并肩走过的全部岁月。","source":"宋人笔记所载版本收藏之习。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"双版并藏,情缘成史"},{"id":"B-119","branch":"B","stage":5,"day":119,"shichen":"辰时","checkpoint":"盘点·119辰","scene":"晨起,终章前一日。你把这一生的要紧物事都取出来了:素银簪、旧帕、木匣、新匣、年约匣、来路册、传习印、双版《往来集》——摆了满满一案。","options":[{"text":"逐件擦拭,默数来路","correct":true,"tags":["自主"],"dims":{"自主":3},"feedback":"从及笄到今日,每一件都记得一个日子。你忽然不怕老了——这些东西替你记得。","source":"宋人笔记所载器物著录与岁暮盘点之习。"},{"text":"只留三五件,余者收匣","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"收起来的那几件,你后来很久没再打开。原来最舍不得的,不是物,是物里的日子。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"物阵盘点为终章总收"},{"id":"B-119-未","branch":"B","stage":5,"day":119,"shichen":"未时","checkpoint":"盘点·119未","scene":"午后,馆中弟子、樊楼旧人、太常同僚、书肆掌柜、贫家之母……满汴京与你相干的人,都不约而同来了。他们说:不为什么,就想来看看你。","options":[{"text":"设茶待客,一一叙旧","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":2},"feedback":"茶续了七遍,话说了百句。你忽然明白:所谓一生,就是这么多人,肯为你跑这一趟。","source":"宋人笔记所载岁暮雅集之俗。"},{"text":"谢客闭门预备明日","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"门是关了,可你在门里听见外头不肯散的脚步声。这些人,是你要谢的,不是要挡的。","source":"同上。"}],"difficulty":2,"npc":["老乐工","鸨母","资深歌伎","书肆掌柜","弦正馆学生","太常寺博士"],"foreshadow":"满座谢客为终章前夜"},{"id":"B-119-戌","branch":"B","stage":5,"day":119,"shichen":"戌时","checkpoint":"盘点·119戌","flavor":true,"scene":"终章前夜,众人都散了,只剩你们二人。他忽然问:若当年州桥书肆,我没有踮脚去够那册《乐章集》,你会嫁给我吗?你看着他,笑了。","options":[{"text":"答:我会自己取下那册书","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":2},"feedback":"他大笑,笑出了眼泪。你补一句:取下书,然后——还是会借给你看。","source":"宋人词话所载夫妇戏论前缘之趣。"},{"text":"答:哪有那么多如果","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你说:如果来如果去,我就不是我了。他点头:对,你从来都是「一定」。","source":"同上。"}],"difficulty":1,"npc":["落魄词人"],"foreshadow":"「一定」为终章答案"},{"id":"B-120","branch":"B","stage":5,"day":120,"shichen":"辰时","checkpoint":"终章·120辰","scene":"终章日晨起。你簪上那支素银簪,怀抱琵琶,走向弦正馆。今日无典无会,只是馆中最寻常的一课——可你知道,这是最圆满的一课。","options":[{"text":"授《桥上月》为馆课","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":2},"feedback":"新曲入课,弟子们弹得生涩。你听着,像听见十年前的自己——薪火,就这样传下去了。","source":"宋人笔记所载师门授曲之习。"},{"text":"仍授《霓裳》古曲","correct":false,"tags":["才华"],"dims":{"才华":2},"feedback":"古曲当然好,可你忽然想:让弟子们学你们的新词,比学古人的旧谱,更像活着。","source":"同上。"}],"difficulty":2,"npc":["弦正馆学生"],"foreshadow":"新曲入课,薪火日新"},{"id":"B-120-未","branch":"B","stage":5,"day":120,"shichen":"未时","checkpoint":"终章·120未","scene":"午后,最后一课毕,弟子们问:先生往后还教什么?你望着馆训墙上「器认功夫,更认心正」,望着双印堂、谱堂、账碑,笑了。","options":[{"text":"答:教你们成为你们","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":2},"feedback":"弟子们愣住,小乐伎先懂了,深深一揖。你扶起她:不必学我,学你自己——这才是真传。","source":"宋人笔记所载师门心法之传。"},{"text":"答:教到我教不动为止","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"话说得悲壮,可弟子们眼里有了愁。你后来想:最好的先生,是让学生敢超过先生。","source":"同上。"}],"difficulty":2,"npc":["小乐伎学生","豪富之女"],"foreshadow":"「成为你们」为馆训终解"},{"id":"B-120-戌","branch":"B","stage":5,"day":120,"shichen":"戌时","checkpoint":"终章·120戌","finale":true,"scene":"终章之夜。你与他并坐州桥,月正中天。桥下流水汤汤,桥上灯火万家。你怀抱琵琶,从及笄那年的樊楼,弹到今日的《桥上月》。半生荣辱,都在弦上。他问你:这一题,有答案了么?——我在宋朝,会出嫁吗?","options":[{"text":"答:嫁了知音,立了自己","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":3,"情缘":3},"feedback":"你弹罢最后一音,月满州桥。嫁的是词曲里的知音,立的是弦上的自己——这题,你答了半生,字字都对。","source":"《东京梦华录》载州桥形胜;宋人词话所载琴瑟和鸣、巾帼自立之义。"},{"text":"不答,再弹一曲","correct":true,"tags":["才华","自主"],"dims":{"才华":3,"自主":2},"feedback":"弦声起处,万籁俱寂。答案不在话里,在曲里——这一曲,从樊楼弹到太常寺,从歌伎弹到乐家,就是你的一生。","source":"《碧鸡漫志》所载以乐言志、曲终见道之义。"}],"difficulty":3,"npc":["落魄词人"],"foreshadow":"终章:嫁知音,立自己"}];
